window.__X_NEWS__ = {"updated_at": "2026-10-21 20:14 Asia/Shanghai", "updated_at_iso": "2026-10-21T12:14:10Z", "count": 91, "domains": ["科技", "商业", "中国", "国际", "体育", "娱乐", "科学"], "items": [{"id": "2112290597440745963", "domain": "科技", "title_en": "Merz Hosts Nvidia's Huang in Berlin to Boost German AI Investments", "title_zh": "默茨在柏林会见英伟达黄仁勋，推动德国 AI 投资", "hook_en": "In Berlin, Chancellor Friedrich Merz sat down with Nvidia CEO Jensen Huang, urging Germany to lead in industrial AI by blending its engineering prowess with cutting-edge tech.", "hook_zh": "德国总理弗里德里希·默茨与英伟达 CEO 黄仁勋会面，呼吁以工程实力引领工业 AI。", "summary_en": "At the Invest in Germany Summit on October 19, Merz welcomed global investors and discussed AI regulation with Huang, who stressed that thriving industry must come before rules, with safety rooted in engineering and best practices. Nvidia announced investments in four German startups—Agile Robots, Avelios Medical, Mirelo, and Reflex Aerospace—as part of its $10 billion European commitment, and signed a deal with the government for advanced physical AI models using German industrial data. Huang praised Germany's irreplaceable engineering, noting Nvidia's 1,000 local employees and nearly $1 billion invested last year, while Merz highlighted the nation's strong industrial base and market access to shape its economic future.", "summary_zh": "在 10 月 19 日“投资德国峰会”上，默茨与黄仁勋讨论 AI 监管；黄仁勋强调产业繁荣应先于规则，安全植根于工程与最佳实践。英伟达宣布投资 Agile Robots、Avelios Medical、Mirelo、Reflex Aerospace 四家德国初创，并纳入其 100 亿美元欧洲承诺，同时与德国政府就基于本土工业数据的物理 AI 模型达成合作。黄仁勋称赞德国工程不可替代，并提到英伟达在当地约有 1000 名员工、去年投资近 10 亿美元。", "body_en": "Merz Hosts Nvidia's Huang in Berlin to Boost German AI Investments.\n\nIn Berlin, Chancellor Friedrich Merz sat down with Nvidia CEO Jensen Huang, urging Germany to lead in industrial AI by blending its engineering prowess with cutting-edge tech.\n\nAt the Invest in Germany Summit on October 19, Merz welcomed global investors and discussed AI regulation with Huang, who stressed that thriving industry must come before rules, with safety rooted in engineering and best practices.\n\nNvidia announced investments in four German startups—Agile Robots, Avelios Medical, Mirelo, and Reflex Aerospace—as part of its $10 billion European commitment, and signed a deal with the government for advanced physical AI models using German industrial data. Huang praised Germany's irreplaceable engineering, noting Nvidia's 1,000 local employees and nearly $1 billion invested last year, while Merz highlighted the nation's strong industrial base and market access to shape its economic future.", "body_zh": "默茨在柏林会见英伟达黄仁勋，推动德国 AI 投资。\n\n德国总理弗里德里希·默茨与英伟达 CEO 黄仁勋会面，呼吁以工程实力引领工业 AI。\n\n在 10 月 19 日“投资德国峰会”上，默茨与黄仁勋讨论 AI 监管；黄仁勋强调产业繁荣应先于规则，安全植根于工程与最佳实践。\n\n英伟达宣布投资 Agile Robots、Avelios Medical、Mirelo、Reflex Aerospace 四家德国初创，并纳入其 100 亿美元欧洲承诺，同时与德国政府就基于本土工业数据的物理 AI 模型达成合作。黄仁勋称赞德国工程不可替代，并提到英伟达在当地约有 1000 名员工、去年投资近 10 亿美元。", "url": "https://x.com/i/trending/2112290597440745963", "category": "News", "topics": ["Technology", "Politics"], "updated_at": "2026-10-20T20:55:18.000Z"}, {"id": "2112386205996245100", "domain": "科技", "title_en": "Sam Altman Outlines Three Paths for Safe Advanced AI Development", "title_zh": "奥特曼勾勒先进 AI 安全发展的三条路径", "hook_en": "Sam Altman gathered OpenAI staff to map out three stark options for handling super-smart AI, right as the Trump administration steps in with its own oversight plans.", "hook_zh": "萨姆·奥特曼召集 OpenAI 员工讨论应对超强 AI 的三条截然不同选项，恰逢特朗普政府推出自有监管计划。", "summary_en": "Last week, Altman described an international body like the IAEA to enforce safety at frontier labs, which he favors; a CERN-style merger of AI labs to share models, known as the 'Demis plan'; and a rejected idea of one lab dominating by disabling rivals' hardware, dubbed the 'Eliezer plan.' He stressed OpenAI must pick a path within a year to avoid falling behind competitors amid safety pressures. The talk coincides with the Trump administration's new Super Intelligence Force, using existing laws to tackle national security and civil liberties risks from advanced AI. Reports from The Information have sparked online talks on AI's future, blending safety concerns with hopes for shared prosperity.", "summary_zh": "上周奥特曼描述了三条路径：他倾向的类似国际原子能机构的国际机构以约束前沿实验室安全；被称为「Demis 方案」的类 CERN 实验室合并以共享模型；以及被否决的「Eliezer 方案」——由单一实验室通过瘫痪对手硬件来主导。他强调 OpenAI 须在一年内选定路径，以免在安全压力下落后于竞争对手。谈话正值特朗普政府成立「超级智能部队」，拟用现有法律应对先进 AI 带来的国家安全与公民自由风险。《The Information》相关报道引发网上对 AI 未来的讨论，交织安全关切与共享繁荣期待。", "body_en": "Sam Altman Outlines Three Paths for Safe Advanced AI Development.\n\nSam Altman gathered OpenAI staff to map out three stark options for handling super-smart AI, right as the Trump administration steps in with its own oversight plans.\n\nLast week, Altman described an international body like the IAEA to enforce safety at frontier labs, which he favors; a CERN-style merger of AI labs to share models, known as the 'Demis plan'; and a rejected idea of one lab dominating by disabling rivals' hardware, dubbed the 'Eliezer plan.' He stressed OpenAI must pick a path within a year to avoid falling behind competitors amid safety pressures.\n\nThe talk coincides with the Trump administration's new Super Intelligence Force, using existing laws to tackle national security and civil liberties risks from advanced AI. Reports from The Information have sparked online talks on AI's future, blending safety concerns with hopes for shared prosperity.", "body_zh": "奥特曼勾勒先进 AI 安全发展的三条路径。\n\n萨姆·奥特曼召集 OpenAI 员工讨论应对超强 AI 的三条截然不同选项，恰逢特朗普政府推出自有监管计划。\n\n上周奥特曼描述了三条路径：他倾向的类似国际原子能机构的国际机构以约束前沿实验室安全；被称为「Demis 方案」的类 CERN 实验室合并以共享模型；以及被否决的「Eliezer 方案」——由单一实验室通过瘫痪对手硬件来主导。他强调 OpenAI 须在一年内选定路径，以免在安全压力下落后于竞争对手。\n\n谈话正值特朗普政府成立「超级智能部队」，拟用现有法律应对先进 AI 带来的国家安全与公民自由风险。《The Information》相关报道引发网上对 AI 未来的讨论，交织安全关切与共享繁荣期待。", "url": "https://x.com/i/trending/2112386205996245100", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T14:10:55.000Z"}, {"id": "2112684362596766177", "domain": "科技", "title_en": "Viggle JST-2 and Dream Labs Dream-1 Launch Fast AI Tools for 3D and Robots", "title_zh": "Viggle JST-2 与 Dream Labs Dream-1 推出快速 3D 与机器人 AI 工具", "hook_en": "Imagine generating a full 3D world in one second for under a penny, or powering robots you've never seen before at just $3 an hour. Two new AI models make these feats real this week.", "hook_zh": "一秒生成完整三维世界、成本不到一美分，或是用每小时约 3 美元驱动从未见过的机器人——两款新模型本周让这些场景成真。", "summary_en": "Viggle released JST-2, the first full-stack physics-native world foundation model that builds 3D scenes from scratch in about one second for less than a cent, allowing real-time expansion from any angle with characters and motion from text or video. Dream Labs debuted Dream-1 from stealth, a robot foundation model backed by a $90 million seed round, which controls unfamiliar bimanual robots on new tasks via a public API starting at $3 per hour. Early testers praised quick successes like playground tasks on rover arms, though finer precision needs work, pointing to lower barriers for creators in simulations, games, and robotics.", "summary_zh": "Viggle 发布 JST-2，号称首个全栈、物理原生的世界基础模型，可在约一秒内从零构建三维场景，成本不足一美分，并能从任意角度实时扩展，用文本或视频加入角色与动作。Dream Labs 则从隐身状态亮相 Dream-1，这是一款机器人基础模型，获 9000 万美元种子轮支持，可通过公开 API 以每小时约 3 美元起控制陌生双臂机器人完成新任务。早期测试者称在漫游车机械臂上能较快完成场地任务，但精细精度仍待提升，整体降低了仿真、游戏与机器人创作者的门槛。", "body_en": "Viggle JST-2 and Dream Labs Dream-1 Launch Fast AI Tools for 3D and Robots.\n\nImagine generating a full 3D world in one second for under a penny, or powering robots you've never seen before at just $3 an hour. Two new AI models make these feats real this week.\n\nViggle released JST-2, the first full-stack physics-native world foundation model that builds 3D scenes from scratch in about one second for less than a cent, allowing real-time expansion from any angle with characters and motion from text or video.\n\nDream Labs debuted Dream-1 from stealth, a robot foundation model backed by a $90 million seed round, which controls unfamiliar bimanual robots on new tasks via a public API starting at $3 per hour. Early testers praised quick successes like playground tasks on rover arms, though finer precision needs work, pointing to lower barriers for creators in simulations, games, and robotics.", "body_zh": "Viggle JST-2 与 Dream Labs Dream-1 推出快速 3D 与机器人 AI 工具。\n\n一秒生成完整三维世界、成本不到一美分，或是用每小时约 3 美元驱动从未见过的机器人——两款新模型本周让这些场景成真。\n\nViggle 发布 JST-2，号称首个全栈、物理原生的世界基础模型，可在约一秒内从零构建三维场景，成本不足一美分，并能从任意角度实时扩展，用文本或视频加入角色与动作。\n\nDream Labs 则从隐身状态亮相 Dream-1，这是一款机器人基础模型，获 9000 万美元种子轮支持，可通过公开 API 以每小时约 3 美元起控制陌生双臂机器人完成新任务。早期测试者称在漫游车机械臂上能较快完成场地任务，但精细精度仍待提升，整体降低了仿真、游戏与机器人创作者的门槛。", "url": "https://x.com/i/trending/2112684362596766177", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T23:23:26.000Z"}, {"id": "2112595601669919101", "domain": "科技", "title_en": "OpenAI Quiets Support for AI Chip Export Limits to China", "title_zh": "OpenAI 对限制对华出口 AI 芯片的立场明显降温", "hook_en": "OpenAI once pushed hard for strict U.S. limits on advanced AI chips heading to China. Now, the company has gone quiet, leaving policymakers surprised and critics pointing fingers.", "hook_zh": "OpenAI 曾大力推动美国严格限制先进 AI 芯片输往中国，如今却基本不再发声。", "summary_en": "Last year, OpenAI lobbied for curbs on sales of Nvidia's advanced processors to Beijing-backed AI labs to protect U.S. interests. Capitol Hill aides note the firm has stopped advocating, a shift that aids Nvidia—which opposes tighter rules—and aligns with broader political approaches amid a major 2025 infrastructure partnership worth up to $100 billion. Critics like Samuel Hammond call it shortsighted for U.S. AI dominance and security, while OpenAI stresses maintaining a compute lead through effective controls as part of strategy. Rival Anthropic continues backing restriction bills as lawmakers eye defense bill amendments.", "summary_zh": "去年 OpenAI 曾游说限制英伟达处理器流向有北京背景的实验室；知情人士称公司已停止相关倡议。这一转向有利于英伟达，也与其 2025 年一项重大基础设施合作相呼应。", "body_en": "OpenAI Quiets Support for AI Chip Export Limits to China.\n\nOpenAI once pushed hard for strict U.S. limits on advanced AI chips heading to China. Now, the company has gone quiet, leaving policymakers surprised and critics pointing fingers.\n\nLast year, OpenAI lobbied for curbs on sales of Nvidia's advanced processors to Beijing-backed AI labs to protect U.S. interests. Capitol Hill aides note the firm has stopped advocating, a shift that aids Nvidia—which opposes tighter rules—and aligns with broader political approaches amid a major 2025 infrastructure partnership worth up to $100 billion.\n\nCritics like Samuel Hammond call it shortsighted for U.S. AI dominance and security, while OpenAI stresses maintaining a compute lead through effective controls as part of strategy. Rival Anthropic continues backing restriction bills as lawmakers eye defense bill amendments.", "body_zh": "OpenAI 对限制对华出口 AI 芯片的立场明显降温。\n\nOpenAI 曾大力推动美国严格限制先进 AI 芯片输往中国，如今却基本不再发声。\n\n去年 OpenAI 曾游说限制英伟达处理器流向有北京背景的实验室；知情人士称公司已停止相关倡议。这一转向有利于英伟达，也与其 2025 年一项重大基础设施合作相呼应。\n\n综合以上信息，OpenAI 对限制对华出口 AI 芯片的立场明显降温一事持续引发关注。", "url": "https://x.com/i/trending/2112595601669919101", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T17:34:14.000Z"}, {"id": "2112188369618784335", "domain": "科技", "title_en": "DHS Orders Federal Agencies to Remove DeepSeek AI Products", "title_zh": "美国土安全部要求民事机构清除 DeepSeek 产品", "hook_en": "The U.S. Department of Homeland Security just drew a firm line on Chinese AI tools in government systems, citing risks of data flowing to China and hidden security threats.", "hook_zh": "联邦民事机构接到明确指令：因涉华安全风险，须从系统中移除相关中国 AI 工具。", "summary_en": "Under a new Federal Register notice dated October 20, 2026, DHS directed civilian federal agencies to halt procurement from Hangzhou DeepSeek Artificial Intelligence Co. and remove all its products, including those embedded in third-party services. The order highlights dangers like sensitive data transfers mandated by Chinese law, collection of personal information, and potential malware in the models. DeepSeek, known for efficient open-weight AI models that run well on modest hardware, now faces these restrictions amid broader U.S. limits on Chinese tech, though defense and intelligence systems remain separately regulated.", "summary_zh": "美国国土安全部于 10 月 20 日下令，要求联邦民事机构从 IT 系统中移除所有 DeepSeek 产品、关联方及相关第三方服务，并停止后续采购。关切包括公司总部位于中国、数据可能移交中国当局、收集个人信息，以及对美国人实施恶意软件或情报搜集的风险。此举凸显美中 AI 博弈；DeepSeek 最新 V4.1 因在日常硬件上的速度与效率仍受关注。命令仅适用于民事机构，可有例外。", "body_en": "DHS Orders Federal Agencies to Remove DeepSeek AI Products.\n\nFederal agencies now face a clear directive: pull DeepSeek's Chinese AI tools from their systems to guard against data risks heading to China.\n\nThe U.S. Department of Homeland Security issued an order on October 20 requiring civilian federal agencies to remove DeepSeek products from IT systems and halt future purchases under the Federal Acquisition Supply Chain Security Act. The move addresses threats like sensitive data transfers to China, potential intelligence generation on U.S.\n\npersons, and malware risks in the models. This builds on prior limits by some agencies and states, applying broadly to civilian executive branch systems while sparing defense networks. Reactions split, with supporters praising network protection and critics noting the model's open-source nature could spur local alternatives.", "body_zh": "美国土安全部要求民事机构清除 DeepSeek 产品。\n\n联邦民事机构接到明确指令：因涉华安全风险，须从系统中移除相关中国 AI 工具。\n\n美国国土安全部于 10 月 20 日下令，要求联邦民事机构从 IT 系统中移除所有 DeepSeek 产品、关联方及相关第三方服务，并停止后续采购。关切包括公司总部位于中国、数据可能移交中国当局、收集个人信息，以及对美国人实施恶意软件或情报搜集的风险。\n\n此举凸显美中 AI 博弈；DeepSeek 最新 V4.1 因在日常硬件上的速度与效率仍受关注。命令仅适用于民事机构，可有例外。", "url": "https://x.com/i/trending/2112188369618784335", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T11:44:28.000Z"}, {"id": "2112741574346162483", "domain": "科技", "title_en": "Nvidia in Talks for Hundreds of Millions Investment in Firmus After Scrapped IPO", "title_zh": "Nvidia 洽谈向 Firmus 注资数亿美元，Firmus 已搁置 IPO", "hook_en": "Firmus had its sights set on a massive IPO, but pulled back amid market jitters. Now Nvidia, already a partner, is stepping up with talks of a huge cash infusion.", "hook_zh": "Firmus 本瞄准大型 IPO，却因市场紧张而撤回；已是合作方的 Nvidia，正讨论大规模注资。", "summary_en": "Australian AI cloud provider Firmus abandoned its planned blockbuster IPO on the Australian Securities Exchange earlier this month due to investor concerns over high valuations and its short track record. Nvidia, which already invests in Firmus and partners on a major GPU deployment in Indonesia's Batam campus, is now discussing an equity investment of several hundred million dollars—possibly at least AU$500 million. This move aligns with Nvidia's strategy to back neocloud operators amid surging AI computing demand, as Firmus pivots to private funding up to US$3 billion. No final deal details are confirmed yet.", "summary_zh": "澳大利亚 AI 云服务商 Firmus 本月初因投资者担忧估值过高与业绩记录偏短，放弃在澳大利亚证券交易所的大型 IPO。已投资 Firmus、并在印尼巴淡岛校园合作大规模 GPU 部署的 Nvidia，正讨论数亿美元股权投资，金额可能至少 5 亿澳元。此举契合 Nvidia 在 AI 算力需求飙升背景下支持 neocloud 运营商的策略；Firmus 则转向最高可达约 30 亿美元的私募融资。最终交易细节尚未确认。", "body_en": "Nvidia in Talks for Hundreds of Millions Investment in Firmus After Scrapped IPO.\n\nFirmus had its sights set on a massive IPO, but pulled back amid market jitters. Now Nvidia, already a partner, is stepping up with talks of a huge cash infusion.\n\nAustralian AI cloud provider Firmus abandoned its planned blockbuster IPO on the Australian Securities Exchange earlier this month due to investor concerns over high valuations and its short track record. Nvidia, which already invests in Firmus and partners on a major GPU deployment in Indonesia's Batam campus, is now discussing an equity investment of several hundred million dollars—possibly at least AU$500 million.\n\nThis move aligns with Nvidia's strategy to back neocloud operators amid surging AI computing demand, as Firmus pivots to private funding up to US$3 billion. No final deal details are confirmed yet.", "body_zh": "Nvidia 洽谈向 Firmus 注资数亿美元，Firmus 已搁置 IPO。\n\nFirmus 本瞄准大型 IPO，却因市场紧张而撤回；已是合作方的 Nvidia，正讨论大规模注资。\n\n澳大利亚 AI 云服务商 Firmus 本月初因投资者担忧估值过高与业绩记录偏短，放弃在澳大利亚证券交易所的大型 IPO。已投资 Firmus、并在印尼巴淡岛校园合作大规模 GPU 部署的 Nvidia，正讨论数亿美元股权投资，金额可能至少 5 亿澳元。\n\n此举契合 Nvidia 在 AI 算力需求飙升背景下支持 neocloud 运营商的策略；Firmus 则转向最高可达约 30 亿美元的私募融资。最终交易细节尚未确认。", "url": "https://x.com/i/trending/2112741574346162483", "category": "News", "topics": ["Technology", "AI", "Business & Finance"], "updated_at": "2026-10-21T04:17:50.000Z"}, {"id": "2112867595250806871", "domain": "科技", "title_en": "NVIDIA Unveils OpenShell to Secure Enterprise AI Agents", "title_zh": "英伟达发布 OpenShell，为企业 AI 智能体加固安全", "hook_en": "Jensen Huang took the stage at GTC Berlin to stress a key truth: AI's power needs matching safety controls as businesses ready billions of autonomous agents.", "hook_zh": "黄仁勋在柏林 GTC 强调：企业即将部署海量自主智能体，算力越强，安全管控越要跟上。", "summary_en": "NVIDIA CEO Jensen Huang introduced the OpenShell Reference Architecture, an open-source secure runtime that runs AI agents in isolated sandboxes with strict policy enforcement on system calls and network access. It combines NVIDIA Vera Rubin systems for inference, Vera CPUs for agent management, and BlueField-4 DPUs for constant monitoring, supporting deployment across enterprise infrastructure and major OS like those from Canonical and Red Hat. Over 100 partners including Anthropic, AWS, Microsoft, and OpenAI are integrating it to ensure agents stay within defined boundaries while accessing files, tools, and private data. Huang noted, 'AI capability and safety must advance together,' addressing the shift from content generation to real enterprise tasks.", "summary_zh": "英伟达 CEO 黄仁勋推出开源安全运行时 OpenShell 参考架构，可在隔离沙箱中运行 AI 智能体，并对系统调用与网络访问实施严格策略。方案结合 Vera Rubin 推理系统、Vera CPU 的智能体管理与 BlueField-4 DPU 持续监控，支持部署到企业基础设施及 Canonical、红帽等主流操作系统。包括 Anthropic、AWS、微软、OpenAI 在内逾百名合作伙伴正接入该架构，以在访问文件、工具与私有数据时守住边界。黄仁勋表示：「AI 能力与安全必须同步推进。」", "body_en": "NVIDIA Unveils OpenShell to Secure Enterprise AI Agents.\n\nJensen Huang took the stage at GTC Berlin to stress a key truth: AI's power needs matching safety controls as businesses ready billions of autonomous agents.\n\nNVIDIA CEO Jensen Huang introduced the OpenShell Reference Architecture, an open-source secure runtime that runs AI agents in isolated sandboxes with strict policy enforcement on system calls and network access. It combines NVIDIA Vera Rubin systems for inference, Vera CPUs for agent management, and BlueField-4 DPUs for constant monitoring, supporting deployment across enterprise infrastructure and major OS like those from Canonical and Red Hat.\n\nOver 100 partners including Anthropic, AWS, Microsoft, and OpenAI are integrating it to ensure agents stay within defined boundaries while accessing files, tools, and private data. Huang noted, 'AI capability and safety must advance together,' addressing the shift from content generation to real enterprise tasks.", "body_zh": "英伟达发布 OpenShell，为企业 AI 智能体加固安全。\n\n黄仁勋在柏林 GTC 强调：企业即将部署海量自主智能体，算力越强，安全管控越要跟上。\n\n英伟达 CEO 黄仁勋推出开源安全运行时 OpenShell 参考架构，可在隔离沙箱中运行 AI 智能体，并对系统调用与网络访问实施严格策略。方案结合 Vera Rubin 推理系统、Vera CPU 的智能体管理与 BlueField-4 DPU 持续监控，支持部署到企业基础设施及 Canonical、红帽等主流操作系统。\n\n包括 Anthropic、AWS、微软、OpenAI 在内逾百名合作伙伴正接入该架构，以在访问文件、工具与私有数据时守住边界。黄仁勋表示：「AI 能力与安全必须同步推进。」", "url": "https://x.com/i/trending/2112867595250806871", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T11:29:25.000Z"}, {"id": "2112613033243721837", "domain": "科技", "title_en": "OpenAI Acquires Orchestra Bio to Speed Drug Development", "title_zh": "OpenAI 收购 Orchestra Bio，加速药物研发", "hook_en": "OpenAI just brought in a team that's been streamlining drug development for four years, right on the startup's anniversary.", "hook_zh": "创业四周年那天，Ashoka Rajendra 得知 OpenAI 将把团队收入麾下。", "summary_en": "On October 20, 2026, OpenAI announced its acquisition of Orchestra Bio, a four-year-old platform that coordinates biopharma teams on tasks like monitoring studies and flagging delays. The deal merges Orchestra's technology with OpenAI's Rosalind AI tools to help scientists link discoveries to treatments faster, using agents that handle operational workflows. OpenAI President Greg Brockman called it an exciting step toward accelerating medicines, while founder Ashoka Rajendra noted AI's growing role in teaming up with people. This move aligns with rivals like Anthropic entering life sciences.", "summary_zh": "OpenAI 收购 Orchestra Bio，将其生物制药协作工具与面向生物、化学的 Rosalind AI 模型结合，推动发现更快转化为疗法。", "body_en": "OpenAI Acquires Orchestra Bio to Speed Drug Development.\n\nImagine AI agents spotting a failed drug batch and instantly suggesting fixes to keep treatments on track for patients.\n\nOpenAI acquired Orchestra Bio, a four-year-old startup founded by Ashoka Rajendra, to integrate its platform with Rosalind AI tools for life sciences. The deal equips biopharma teams with agents that monitor studies, track timelines, flag delays, and coordinate across partners, aiming to turn scientific discoveries into patient treatments faster.\n\nIt builds on OpenAI's work with customers like Moderna and Novo Nordisk, amid a trend of AI labs entering biotech. Investors and leaders like Greg Brockman expressed excitement about accelerating the 10-15 year drug development process.", "body_zh": "OpenAI 收购 Orchestra Bio，加速药物研发。\n\n创业四周年那天，Ashoka Rajendra 得知 OpenAI 将把团队收入麾下。\n\nOpenAI 收购 Orchestra Bio，将其生物制药协作工具与面向生物、化学的 Rosalind AI 模型结合，推动发现更快转化为疗法。\n\n综合以上信息，OpenAI 收购 Orchestra Bio，加速药物研发一事持续引发关注。", "url": "https://x.com/i/trending/2112613033243721837", "category": "News", "topics": ["Technology", "Biotech"], "updated_at": "2026-10-21T10:08:04.000Z"}, {"id": "2112496630352281688", "domain": "科技", "title_en": "Microsoft Pulls Out of UK's Largest Planned AI Data Center Over Power Shortage", "title_zh": "电力短缺，微软退出英国最大拟建 AI 数据中心", "hook_en": "Microsoft backed away from a massive AI supercomputer project in Essex after learning grid power won't arrive until the 2030s. The move spotlights Britain's struggle to fuel its AI dreams with reliable electricity.", "hook_zh": "得知电网供电要到 2030 年代才能到位后，微软退出埃塞克斯巨型 AI 超算项目。", "summary_en": "Nscale planned a £2 billion facility in Loughton, the UK's biggest AI data center, with Microsoft as anchor tenant for a setup using 23,000 Nvidia chips and up to 90 megawatts of capacity. UK Power Networks cited decade-long delays, prompting Microsoft to terminate just for this site while keeping ties with Nscale strong. Nscale presses on with alternative power and other locations, amid talk of grid bottlenecks holding back the UK's third-place global AI ranking. Observers debate fixes like faster permits and targeted grid investments to match policy ambition with infrastructure reality.", "summary_zh": "Nscale 原计划在劳顿投资 20 亿英镑建设英国最大 AI 数据中心，微软为锚定租户，拟部署约 2.3 万块英伟达芯片、容量最高约 90 兆瓦。英国电力网络公司称供电延迟可能长达十年，微软因此仅终止该站点合作，与 Nscale 其他合作仍保持。Nscale 正寻求替代电力与其他选址；舆论认为电网瓶颈拖累英国全球 AI 第三的定位，呼吁加快许可与定向电网投资。", "body_en": "Microsoft Pulls Out of UK's Largest Planned AI Data Center Over Power Shortage.\n\nMicrosoft backed away from a massive AI supercomputer project in Essex after learning grid power won't arrive until the 2030s. The move spotlights Britain's struggle to fuel its AI dreams with reliable electricity.\n\nNscale planned a £2 billion facility in Loughton, the UK's biggest AI data center, with Microsoft as anchor tenant for a setup using 23,000 Nvidia chips and up to 90 megawatts of capacity. UK Power Networks cited decade-long delays, prompting Microsoft to terminate just for this site while keeping ties with Nscale strong.\n\nNscale presses on with alternative power and other locations, amid talk of grid bottlenecks holding back the UK's third-place global AI ranking. Observers debate fixes like faster permits and targeted grid investments to match policy ambition with infrastructure reality.", "body_zh": "电力短缺，微软退出英国最大拟建 AI 数据中心。\n\n得知电网供电要到 2030 年代才能到位后，微软退出埃塞克斯巨型 AI 超算项目。\n\nNscale 原计划在劳顿投资 20 亿英镑建设英国最大 AI 数据中心，微软为锚定租户，拟部署约 2.3 万块英伟达芯片、容量最高约 90 兆瓦。英国电力网络公司称供电延迟可能长达十年，微软因此仅终止该站点合作，与 Nscale 其他合作仍保持。\n\nNscale 正寻求替代电力与其他选址；舆论认为电网瓶颈拖累英国全球 AI 第三的定位，呼吁加快许可与定向电网投资。", "url": "https://x.com/i/trending/2112496630352281688", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T10:54:58.000Z"}, {"id": "2112343868393816356", "domain": "科技", "title_en": "Nebius and NVIDIA Expand AI Builder Program Across Europe with $10 Million Boost", "title_zh": "Nebius 与英伟达加码欧洲 AI 建设者计划，注入千万美元算力", "hook_en": "European AI builders, often scraping by with limited compute like 8 GB VRAM, now get a real shot at scaling their open-source projects.", "hook_zh": "欧洲开源 AI 开发者常困于 8GB 显存级算力；如今有望真正把项目做大。", "summary_en": "Nebius and NVIDIA are rolling out their AI Builder Program across Europe with $10 million in compute grants, investor links, and community events to help open AI developers grow from experiments to funded companies. Targeting open models, coding agents, post-training, and evaluations, selected builders gain access to Nebius infrastructure, connections to VCs like Accel, and hackathons with groups such as AI Tinkerers. Builders praise it for tackling key hurdles—compute shortages and funding gaps—with one calling it a game changer that rewards those already shipping code. The expansion launches this week at NVIDIA GTC Berlin, building on a global program to keep Europe's strong AI research talent at home.", "summary_zh": "Nebius 与英伟达在欧洲推广 AI Builder Program，提供约 1000 万美元算力资助、投资人对接与社群活动，帮助开源开发者从实验走向融资公司。面向开源模型、编程智能体、后训练与评测，入选者可使用 Nebius 基础设施，并连接 Accel 等风投及 AI Tinkerers 等黑客松。建设者称其直击算力与资金两大瓶颈，有人形容「对已经在写代码的人来说是改变游戏规则」。扩展计划本周在柏林 GTC 启动，意在留住欧洲研究人才。", "body_en": "Nebius and NVIDIA Expand AI Builder Program Across Europe with $10 Million Boost.\n\nEuropean AI builders, often scraping by with limited compute like 8 GB VRAM, now get a real shot at scaling their open-source projects.\n\nNebius and NVIDIA are rolling out their AI Builder Program across Europe with $10 million in compute grants, investor links, and community events to help open AI developers grow from experiments to funded companies. Targeting open models, coding agents, post-training, and evaluations, selected builders gain access to Nebius infrastructure, connections to VCs like Accel, and hackathons with groups such as AI Tinkerers.\n\nBuilders praise it for tackling key hurdles—compute shortages and funding gaps—with one calling it a game changer that rewards those already shipping code. The expansion launches this week at NVIDIA GTC Berlin, building on a global program to keep Europe's strong AI research talent at home.", "body_zh": "Nebius 与英伟达加码欧洲 AI 建设者计划，注入千万美元算力。\n\n欧洲开源 AI 开发者常困于 8GB 显存级算力；如今有望真正把项目做大。\n\nNebius 与英伟达在欧洲推广 AI Builder Program，提供约 1000 万美元算力资助、投资人对接与社群活动，帮助开源开发者从实验走向融资公司。面向开源模型、编程智能体、后训练与评测，入选者可使用 Nebius 基础设施，并连接 Accel 等风投及 AI Tinkerers 等黑客松。\n\n建设者称其直击算力与资金两大瓶颈，有人形容「对已经在写代码的人来说是改变游戏规则」。扩展计划本周在柏林 GTC 启动，意在留住欧洲研究人才。", "url": "https://x.com/i/trending/2112343868393816356", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T00:48:05.000Z"}, {"id": "2112213032193372268", "domain": "科技", "title_en": "Town Raises $108 Million at $1 Billion Valuation for Team AI Assistants", "title_zh": "Town 融资 1.08 亿美元，估值达 10 亿美元，主打团队 AI 助手", "hook_en": "Imagine AI helpers that don't just manage your inbox but chat with your teammates' assistants to keep projects moving without the wait.", "hook_zh": "设想一下：AI 助手不仅管邮箱，还能与同事的助手直接沟通，减少项目等待。", "summary_en": "Town, an AI startup, secured $108 million in Series B funding, co-led by Forerunner Ventures and Menlo Ventures, pushing its valuation to $1 billion. The company launched its public product in June, hitting seven figures in annual recurring revenue with paying customers growing fourfold since July. Townies connect to workplace tools, learn individual styles, and now coordinate directly with each other for smoother team handoffs—addressing CEO Jean-Denis Greze's point that work's biggest bottleneck is waiting on others. Investors like Menlo Ventures, which uses it firm-wide, praise the focus on real tasks and rapid adoption across thousands of businesses.", "summary_zh": "AI 初创公司 Town 完成 1.08 亿美元 B 轮融资，由 Forerunner Ventures 与 Menlo Ventures 联合领投，估值升至 10 亿美元。产品于 6 月公开上线，年经常性收入已达七位数，付费客户自 7 月以来增长约四倍。Townies 可连接职场工具、学习个人风格，并彼此协调交接——回应 CEO Jean-Denis Greze 所说，工作最大瓶颈往往是「等别人」。Menlo 等投资人已全员使用，称其聚焦真实任务、落地很快。", "body_en": "Town Raises $108 Million at $1 Billion Valuation for Team AI Assistants.\n\nImagine AI helpers that don't just manage your inbox but chat with your teammates' assistants to keep projects moving without the wait.\n\nTown, an AI startup, secured $108 million in Series B funding, co-led by Forerunner Ventures and Menlo Ventures, pushing its valuation to $1 billion. The company launched its public product in June, hitting seven figures in annual recurring revenue with paying customers growing fourfold since July.\n\nTownies connect to workplace tools, learn individual styles, and now coordinate directly with each other for smoother team handoffs—addressing CEO Jean-Denis Greze's point that work's biggest bottleneck is waiting on others. Investors like Menlo Ventures, which uses it firm-wide, praise the focus on real tasks and rapid adoption across thousands of businesses.", "body_zh": "Town 融资 1.08 亿美元，估值达 10 亿美元，主打团队 AI 助手。\n\n设想一下：AI 助手不仅管邮箱，还能与同事的助手直接沟通，减少项目等待。\n\nAI 初创公司 Town 完成 1.08 亿美元 B 轮融资，由 Forerunner Ventures 与 Menlo Ventures 联合领投，估值升至 10 亿美元。产品于 6 月公开上线，年经常性收入已达七位数，付费客户自 7 月以来增长约四倍。\n\nTownies 可连接职场工具、学习个人风格，并彼此协调交接——回应 CEO Jean-Denis Greze 所说，工作最大瓶颈往往是「等别人」。Menlo 等投资人已全员使用，称其聚焦真实任务、落地很快。", "url": "https://x.com/i/trending/2112213032193372268", "category": "News", "topics": ["Technology", "Business & Finance"], "updated_at": "2026-10-19T21:18:43.000Z"}, {"id": "2112552619117809960", "domain": "科技", "title_en": "Qualitate Raises $25M to Transform Market Research with AI Expert Interviews", "title_zh": "Qualitate 获 2500 万美元，用 AI 专家访谈改造市场研究", "hook_en": "Imagine querying thousands of expert conversations instantly to spot market shifts. Qualitate's AI platform makes that real, turning one-off calls into a living knowledge base.", "hook_zh": "一次性专家通话变成可检索的活知识库，数千段访谈可即时查询、捕捉市场转向。", "summary_en": "Qualitate secured $25 million in Series A funding led by Insight Partners, an existing customer, to build an AI system that interviews vetted experts at scale and structures their insights for easy querying and trend tracking. CEO Sagar Kadakia aims to challenge giants like Gartner, McKinsey, and GLG, with the platform already serving over 100 investment firms and enterprises amid 10x revenue growth this year. Charts from the company show AI factors surging in spend decreases and churn plans from late 2025 to early 2026, while plans call for expanding the expert network and AI capabilities after logging over one million minutes of interviews.", "summary_zh": "Qualitate 完成由现有客户 Insight Partners 领投的 2500 万美元 A 轮，打造可规模化访谈认证专家、结构化洞察并追踪趋势的 AI 系统。CEO Sagar Kadakia 意在挑战 Gartner、麦肯锡与 GLG；平台已服务逾 100 家投资机构与企业，今年收入增长约 10 倍。公司图表显示 2025 年末至 2026 年初，支出削减与流失计划中 AI 因素上升；已累计超 100 万分钟访谈，计划继续扩大专家网络与 AI 能力。", "body_en": "Qualitate Raises $25M to Transform Market Research with AI Expert Interviews.\n\nImagine querying thousands of expert conversations instantly to spot market shifts. Qualitate's AI platform makes that real, turning one-off calls into a living knowledge base.\n\nQualitate secured $25 million in Series A funding led by Insight Partners, an existing customer, to build an AI system that interviews vetted experts at scale and structures their insights for easy querying and trend tracking.\n\nCEO Sagar Kadakia aims to challenge giants like Gartner, McKinsey, and GLG, with the platform already serving over 100 investment firms and enterprises amid 10x revenue growth this year. Charts from the company show AI factors surging in spend decreases and churn plans from late 2025 to early 2026, while plans call for expanding the expert network and AI capabilities after logging over one million minutes of interviews.", "body_zh": "Qualitate 获 2500 万美元，用 AI 专家访谈改造市场研究。\n\n一次性专家通话变成可检索的活知识库，数千段访谈可即时查询、捕捉市场转向。\n\nQualitate 完成由现有客户 Insight Partners 领投的 2500 万美元 A 轮，打造可规模化访谈认证专家、结构化洞察并追踪趋势的 AI 系统。\n\nCEO Sagar Kadakia 意在挑战 Gartner、麦肯锡与 GLG；平台已服务逾 100 家投资机构与企业，今年收入增长约 10 倍。公司图表显示 2025 年末至 2026 年初，支出削减与流失计划中 AI 因素上升；已累计超 100 万分钟访谈，计划继续扩大专家网络与 AI 能力。", "url": "https://x.com/i/trending/2112552619117809960", "category": "News", "topics": ["Business & Finance", "Entrepreneurship", "Technology", "AI"], "updated_at": "2026-10-20T17:34:42.000Z"}, {"id": "2112595597664391555", "domain": "科技", "title_en": "Bria AI Launches Fibo 2.0, Top Open Model for Image Editing", "title_zh": "Bria AI 发布 Fibo 2.0：开源图像编辑榜首模型", "hook_en": "Bria AI just dropped Fibo 2.0, an 8-billion-parameter model that tops open-weights benchmarks for image editing while tying for the lead in text-to-image generation.", "hook_zh": "80 亿参数的 Fibo 2.0 在开源权重图像编辑基准居首，文生图也并列领先。", "summary_en": "The new release unifies editing and generation capabilities, outperforming prior versions in text rendering, layout, and precise edits, with an Elo score of 1087 on the AA-Image-Editing v2.1 leaderboard. Trained exclusively on licensed data, it offers clearer commercial paths and comes in two Hugging Face variants: Fibo 2.0 Dev for generation and fine-tuning, and Fibo 2.0 Edit Turbo for speed. Developers praised its immediate availability, JSON-native controls for consistent results, and strong detail preservation in tasks like background swaps and lighting adjustments, now accessible via Bria's $32-per-1,000-images API.", "summary_zh": "新版本统一编辑与生成能力，在文字渲染、版式与精细修改上优于前代，AA-Image-Editing v2.1 排行榜 Elo 达 1087。模型仅用授权数据训练，商业路径更清晰；Hugging Face 提供面向生成微调的 Fibo 2.0 Dev，以及偏速度的 Edit Turbo。开发者称赞立即可用、JSON 原生控制与背景替换、光照调整时的细节保持；亦可通过 Bria 每千张约 32 美元的 API 调用。", "body_en": "Bria AI Launches Fibo 2.0, Top Open Model for Image Editing.\n\nBria AI just dropped Fibo 2.0, an 8-billion-parameter model that tops open-weights benchmarks for image editing while tying for the lead in text-to-image generation.\n\nThe new release unifies editing and generation capabilities, outperforming prior versions in text rendering, layout, and precise edits, with an Elo score of 1087 on the AA-Image-Editing v2.1 leaderboard.\n\nTrained exclusively on licensed data, it offers clearer commercial paths and comes in two Hugging Face variants: Fibo 2.0 Dev for generation and fine-tuning, and Fibo 2.0 Edit Turbo for speed. Developers praised its immediate availability, JSON-native controls for consistent results, and strong detail preservation in tasks like background swaps and lighting adjustments, now accessible via Bria's $32-per-1,000-images API.", "body_zh": "Bria AI 发布 Fibo 2.0：开源图像编辑榜首模型。\n\n80 亿参数的 Fibo 2.0 在开源权重图像编辑基准居首，文生图也并列领先。\n\n新版本统一编辑与生成能力，在文字渲染、版式与精细修改上优于前代，AA-Image-Editing v2.1 排行榜 Elo 达 1087。\n\n模型仅用授权数据训练，商业路径更清晰；Hugging Face 提供面向生成微调的 Fibo 2.0 Dev，以及偏速度的 Edit Turbo。开发者称赞立即可用、JSON 原生控制与背景替换、光照调整时的细节保持；亦可通过 Bria 每千张约 32 美元的 API 调用。", "url": "https://x.com/i/trending/2112595597664391555", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T20:42:48.000Z"}, {"id": "2112796521959985524", "domain": "商业", "title_en": "America's Finance Hits Record-Breaking Pace with Mega-Deals", "title_zh": "美国资本市场连创纪录：巨额IPO与债券齐发", "hook_en": "From SpaceX's massive IPO to SoftBank's record junk-bond sale, U.S. markets just powered through an eye-popping wave of financial feats.", "hook_zh": "从 SpaceX 超大规模 IPO 到软银创纪录的垃圾债发行，美国市场正掀起一波令人瞩目的融资潮。", "summary_en": "The Economist highlighted a stunning lineup of achievements, including the biggest IPO ever from SpaceX, huge equity raises by Google and others, OpenAI's private funding, Broadcom's debt deal, Amazon's bond issuance, the first trillion-dollar ETF, and Berkshire Hathaway's cash pile. SoftBank recently sealed the largest corporate junk-bond offering on record, raising over $11 billion for AI investments amid a surge in new markets for compute and predictions. Observers celebrated this resilience as proof of America's unmatched capital markets strength, with comments hailing its bottomless appetite for innovation and ability to sideline setbacks.", "summary_zh": "《经济学人》梳理了一系列里程碑：SpaceX 完成史上最大 IPO，谷歌等巨头大幅增发股权，OpenAI 继续私募融资，博通债务交易、亚马逊发债、首只万亿美元 ETF 以及伯克希尔庞大现金储备也同台亮相。软银近日完成有史以来最大规模公司垃圾债发行，筹资逾 110 亿美元投入 AI。观察者认为，这印证了美国资本市场的深度与对创新的吸纳能力。", "body_en": "America's Finance Hits Record-Breaking Pace with Mega-Deals.\n\nFrom SpaceX's massive IPO to SoftBank's record junk-bond sale, U.S. markets just powered through an eye-popping wave of financial feats.\n\nThe Economist highlighted a stunning lineup of achievements, including the biggest IPO ever from SpaceX, huge equity raises by Google and others, OpenAI's private funding, Broadcom's debt deal, Amazon's bond issuance, the first trillion-dollar ETF, and Berkshire Hathaway's cash pile.\n\nSoftBank recently sealed the largest corporate junk-bond offering on record, raising over $11 billion for AI investments amid a surge in new markets for compute and predictions. Observers celebrated this resilience as proof of America's unmatched capital markets strength, with comments hailing its bottomless appetite for innovation and ability to sideline setbacks.", "body_zh": "美国资本市场连创纪录：巨额IPO与债券齐发。\n\n从 SpaceX 超大规模 IPO 到软银创纪录的垃圾债发行，美国市场正掀起一波令人瞩目的融资潮。\n\n《经济学人》梳理了一系列里程碑：SpaceX 完成史上最大 IPO，谷歌等巨头大幅增发股权，OpenAI 继续私募融资，博通债务交易、亚马逊发债、首只万亿美元 ETF 以及伯克希尔庞大现金储备也同台亮相。软银近日完成有史以来最大规模公司垃圾债发行，筹资逾 110 亿美元投入 AI。\n\n观察者认为，这印证了美国资本市场的深度与对创新的吸纳能力。", "url": "https://x.com/i/trending/2112796521959985524", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T06:46:48.000Z"}, {"id": "2112540739628630161", "domain": "商业", "title_en": "Amazon Explores Offloading $8 Billion in Nvidia Chips to Investors", "title_zh": "亚马逊探讨向投资者转移约 80 亿美元英伟达芯片", "hook_en": "Amazon has thousands of cutting-edge Nvidia chips ready for its U.S. data centers, but power shortages mean many sit unused in warehouses.", "hook_zh": "大量先进英伟达芯片已备好进美国数据中心，却因电力不足堆在仓库。", "summary_en": "The company is in talks to shift about $8 billion worth of Grace Blackwell chips into a special-purpose vehicle, which would lease them back to Amazon and raise funds through debt and a small equity stake. This comes as internal documents reveal a massive influx of Nvidia GB300 racks—$5 billion in one month alone—piling up due to insufficient power and infrastructure in data centers across Nevada and Virginia. Observers note the timing raises questions about Amazon's AI hardware glut amid its $220 billion capital spending push, though some see the move as smart financing to keep using the chips without owning them outright.", "summary_zh": "公司正洽谈将约 80 亿美元 Grace Blackwell 芯片装入特殊目的载体，再回租给亚马逊，并以债务与少量股权融资。内部文件显示英伟达 GB300 机架大量涌入——单月即约 50 亿美元——因内华达与弗吉尼亚等地电力与基础设施不足而积压。有人质疑其在约 2200 亿美元资本开支背景下的算力过剩，也有人视之为「用而不必全资持有」的融资安排。", "body_en": "Amazon Explores Offloading $8 Billion in Nvidia Chips to Investors.\n\nAmazon has thousands of cutting-edge Nvidia chips ready for its U.S. data centers, but power shortages mean many sit unused in warehouses.\n\nThe company is in talks to shift about $8 billion worth of Grace Blackwell chips into a special-purpose vehicle, which would lease them back to Amazon and raise funds through debt and a small equity stake.\n\nThis comes as internal documents reveal a massive influx of Nvidia GB300 racks—$5 billion in one month alone—piling up due to insufficient power and infrastructure in data centers across Nevada and Virginia. Observers note the timing raises questions about Amazon's AI hardware glut amid its $220 billion capital spending push, though some see the move as smart financing to keep using the chips without owning them outright.", "body_zh": "亚马逊探讨向投资者转移约 80 亿美元英伟达芯片。\n\n大量先进英伟达芯片已备好进美国数据中心，却因电力不足堆在仓库。\n\n公司正洽谈将约 80 亿美元 Grace Blackwell 芯片装入特殊目的载体，再回租给亚马逊，并以债务与少量股权融资。内部文件显示英伟达 GB300 机架大量涌入——单月即约 50 亿美元——因内华达与弗吉尼亚等地电力与基础设施不足而积压。\n\n有人质疑其在约 2200 亿美元资本开支背景下的算力过剩，也有人视之为「用而不必全资持有」的融资安排。", "url": "https://x.com/i/trending/2112540739628630161", "category": "News", "topics": ["Business & Finance", "Stocks", "Technology", "AI"], "updated_at": "2026-10-20T13:52:24.000Z"}, {"id": "2112431560116826201", "domain": "商业", "title_en": "Former Finance Secretary Sparks Debate on India's GDP in Dollar Terms", "title_zh": "前财秘以美元口径 GDP 数据引发印度增长辩论", "hook_en": "Subhash Chandra Garg, ex-Finance Secretary, shared IMF data showing India's GDP growth in current US dollars at just 3.87%—well below the world average and China's rate—prompting a lively back-and-forth online.", "hook_zh": "前财政秘书苏巴什·钱德拉·加尔格分享 IMF 数据称，印度按现价美元计 GDP 增速仅 3.87%，低于全球均值与中国，引发网上热议。", "summary_en": "Garg contrasted this with India's real GDP growth of around 7% in local terms, arguing the dollar measure gives a fuller picture often missed in domestic talks. Critics say focusing on dollars mixes in currency fluctuations and overlooks actual output, while supporters like Sanjay Jha tie it to investor outflows exceeding Rs 3 lakh crore from Indian stocks in 2026 and job concerns. The IMF's October 2026 outlook projects India's real growth at 7%, but nominal dollar GDP lags partly due to rupee depreciation, highlighting tensions between real output metrics and global investor views.", "summary_zh": "加尔格将其与印度本币实际 GDP 约 7% 的增速对照，认为美元口径更能呈现国内讨论常忽略的全貌。批评者称盯住美元会混入汇率波动、忽视实际产出；支持者如 Sanjay Jha 则将其与 2026 年印度股市外资流出逾 3 万亿卢比及就业担忧挂钩。IMF 2026 年 10 月展望仍预计印度实际增速 7%，但名义美元 GDP 因卢比贬值等因素滞后，凸显产出指标与全球投资者视角之间的张力。", "body_en": "Former Finance Secretary Sparks Debate on India's GDP in Dollar Terms.\n\nSubhash Chandra Garg, ex-Finance Secretary, shared IMF data showing India's GDP growth in current US dollars at just 3.87%—well below the world average and China's rate—prompting a lively back-and-forth online.\n\nGarg contrasted this with India's real GDP growth of around 7% in local terms, arguing the dollar measure gives a fuller picture often missed in domestic talks.\n\nCritics say focusing on dollars mixes in currency fluctuations and overlooks actual output, while supporters like Sanjay Jha tie it to investor outflows exceeding Rs 3 lakh crore from Indian stocks in 2026 and job concerns. The IMF's October 2026 outlook projects India's real growth at 7%, but nominal dollar GDP lags partly due to rupee depreciation, highlighting tensions between real output metrics and global investor views.", "body_zh": "前财秘以美元口径 GDP 数据引发印度增长辩论。\n\n前财政秘书苏巴什·钱德拉·加尔格分享 IMF 数据称，印度按现价美元计 GDP 增速仅 3.87%，低于全球均值与中国，引发网上热议。\n\n加尔格将其与印度本币实际 GDP 约 7% 的增速对照，认为美元口径更能呈现国内讨论常忽略的全貌。批评者称盯住美元会混入汇率波动、忽视实际产出；支持者如 Sanjay Jha 则将其与 2026 年印度股市外资流出逾 3 万亿卢比及就业担忧挂钩。\n\nIMF 2026 年 10 月展望仍预计印度实际增速 7%，但名义美元 GDP 因卢比贬值等因素滞后，凸显产出指标与全球投资者视角之间的张力。", "url": "https://x.com/i/trending/2112431560116826201", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T06:36:16.000Z"}, {"id": "2112771431633502285", "domain": "商业", "title_en": "Nifty Gaps Up Then Faces Selling Pressure on October 21", "title_zh": "节后高开后 Nifty 遭遇抛压", "hook_en": "Nifty started the day with a promising gap-up above 23,000, fueled by IT gains and IPO buzz, but sellers quickly stepped in as charts signaled risks.", "hook_zh": "排灯节后 Nifty 曾乐观跳空高开，但卖方迅速入场，指数在震荡中回落。", "summary_en": "After Monday's 1.11% drop to 22,888.95, the index opened higher on positive GIFT Nifty signals, Jio Platforms IPO excitement, and India-US trade hopes, yet Elliott Wave analysis warned of a downside zone between 23,060-23,175 targeting 22,560-22,478. Analysts like Ashish H Kyal highlighted key levels, with a break above 22,970 eyeing 23,050-23,120 or below 22,830 pressuring 22,728, and morning targets hit before a sharp reversal. Broader factors included global cues and high Brent crude at $110, underscoring the market's focus on precise supports around 22,700-22,800 amid volatility.", "summary_zh": "指数周一收于 22888.95，跌 1.11%；随后开于约 23016，最高 23120.90，再回落至 22700–22800 一带。技术派如 SweeGlu 艾略特波浪使用者在 23060–23175 区间看到抛售，下行关注 22560–22478；Ashish H Kyal 指出关键区间波动，Mahesh Khandelwal 则预期自 22500 一带反转冲向 24000 上方。布伦特原油约每桶 110 美元加重通胀担忧；Jio Platforms IPO 与二季报推动部分 IT 买盘，但整体仍偏获利了结。", "body_en": "Nifty Gaps Up Then Faces Selling Pressure on October 21.\n\nNifty started the day with a promising gap-up above 23,000, fueled by IT gains and IPO buzz, but sellers quickly stepped in as charts signaled risks.\n\nAfter Monday's 1.11% drop to 22,888.95, the index opened higher on positive GIFT Nifty signals, Jio Platforms IPO excitement, and India-US trade hopes, yet Elliott Wave analysis warned of a downside zone between 23,060-23,175 targeting 22,560-22,478.\n\nAnalysts like Ashish H Kyal highlighted key levels, with a break above 22,970 eyeing 23,050-23,120 or below 22,830 pressuring 22,728, and morning targets hit before a sharp reversal. Broader factors included global cues and high Brent crude at $110, underscoring the market's focus on precise supports around 22,700-22,800 amid volatility.", "body_zh": "节后高开后 Nifty 遭遇抛压。\n\n排灯节后 Nifty 曾乐观跳空高开，但卖方迅速入场，指数在震荡中回落。\n\n指数周一收于 22888.95，跌 1.11%；随后开于约 23016，最高 23120.90，再回落至 22700–22800 一带。技术派如 SweeGlu 艾略特波浪使用者在 23060–23175 区间看到抛售，下行关注 22560–22478；Ashish H Kyal 指出关键区间波动，Mahesh Khandelwal 则预期自 22500 一带反转冲向 24000 上方。\n\n布伦特原油约每桶 110 美元加重通胀担忧；Jio Platforms IPO 与二季报推动部分 IT 买盘，但整体仍偏获利了结。", "url": "https://x.com/i/trending/2112771431633502285", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T08:16:34.000Z"}, {"id": "2112266057628913774", "domain": "商业", "title_en": "Hedge Funds Dump Tech Stocks at Fastest Pace in Decade", "title_zh": "对冲基金十年最快速度抛售科技股", "hook_en": "Hedge funds hit the sell button on tech stocks harder than they have in at least a decade, unloading positions amid sharp market drops.", "hook_zh": "对冲基金对科技股的抛售力度至少创下十年来最快，正值市场大跌。", "summary_en": "Through October 15, hedge funds cut technology exposure at the quickest rate since at least 2016, reversing all net buying of AI stocks since early 2025 in just one week. Semiconductors bore the brunt, making up 57% of U.S. tech sales, as the Nasdaq 100 fell 5.5%—its worst week since April 2025—and the SOX index hit its lowest ratio to the S&P 500 since April. Investors also rushed into credit default swaps on AI-linked firms like Nvidia and Meta, with spreads hitting records and trading volumes surging, while funds shifted toward U.S. Treasurys amid a negative risk-appetite signal.", "summary_zh": "截至 10 月 15 日，对冲基金削减科技敞口的速度为至少 2016 年以来最快，一周内就逆转了自 2025 年初以来对 AI 股的净买入。半导体占美国科技卖出的 57%；纳斯达克 100 当周跌 5.5%，为 2025 年 4 月以来最差。投资者还大量买入英伟达、Meta 等 AI 相关信用违约互换，利差与成交量创新高，同时资金转向美债。", "body_en": "Hedge Funds Dump Tech Stocks at Fastest Pace in Decade.\n\nHedge funds hit the sell button on tech stocks harder than they have in at least a decade, unloading positions amid sharp market drops.\n\nThrough October 15, hedge funds cut technology exposure at the quickest rate since at least 2016, reversing all net buying of AI stocks since early 2025 in just one week. Semiconductors bore the brunt, making up 57% of U.S.\n\ntech sales, as the Nasdaq 100 fell 5.5%—its worst week since April 2025—and the SOX index hit its lowest ratio to the S&P 500 since April. Investors also rushed into credit default swaps on AI-linked firms like Nvidia and Meta, with spreads hitting records and trading volumes surging, while funds shifted toward U.S. Treasurys amid a negative risk-appetite signal.", "body_zh": "对冲基金十年最快速度抛售科技股。\n\n对冲基金对科技股的抛售力度至少创下十年来最快，正值市场大跌。\n\n截至 10 月 15 日，对冲基金削减科技敞口的速度为至少 2016 年以来最快，一周内就逆转了自 2025 年初以来对 AI 股的净买入。半导体占美国科技卖出的 57%；纳斯达克 100 当周跌 5.5%，为 2025 年 4 月以来最差。\n\n投资者还大量买入英伟达、Meta 等 AI 相关信用违约互换，利差与成交量创新高，同时资金转向美债。", "url": "https://x.com/i/trending/2112266057628913774", "category": "News", "topics": ["Business & Finance", "Technology"], "updated_at": "2026-10-20T21:07:55.000Z"}, {"id": "2112003183275090362", "domain": "商业", "title_en": "China's Economy Grows Faster Than Expected Amid Record Stock Slump", "title_zh": "中国经济增速超预期，股市却创最长连跌", "hook_en": "China's GDP beat forecasts in Q3, offering a bright spot even as stocks hit their longest losing streak ever.", "hook_zh": "三季度 GDP 好于预期，A 股却录得史上最长连跌。", "summary_en": "Official data showed 4.5% year-on-year growth in the third quarter, topping estimates of 4.4% and lifting the first nine months to 4.6%, within Beijing's annual target. Industrial output rose 5.5% in September, retail sales gained 1.1%, and a $133.5 billion trade surplus provided support, driven by tech exports tied to global AI demand. Yet the CSI 300 index fell for 10 straight weeks, its worst streak, as domestic demand stayed soft with property woes and weak consumer spending. Economists see the rebound easing stimulus pressure but question its staying power.", "summary_zh": "三季度同比增长 4.5%，高于 4.4% 预期；工业增加值增 5.5%，但内需疲软令沪深 300 连续 10 周下跌。", "body_en": "China's Economy Grows Faster Than Expected Amid Record Stock Slump.\n\nChina's GDP beat forecasts in Q3, offering a bright spot even as stocks hit their longest losing streak ever.\n\nOfficial data showed 4.5% year-on-year growth in the third quarter, topping estimates of 4.4% and lifting the first nine months to 4.6%, within Beijing's annual target. Industrial output rose 5.5% in September, retail sales gained 1.1%, and a $133.5 billion trade surplus provided support, driven by tech exports tied to global AI demand.\n\nYet the CSI 300 index fell for 10 straight weeks, its worst streak, as domestic demand stayed soft with property woes and weak consumer spending. Economists see the rebound easing stimulus pressure but question its staying power.", "body_zh": "中国经济增速超预期，股市却创最长连跌。\n\n三季度 GDP 好于预期，A 股却录得史上最长连跌。\n\n三季度同比增长 4.5%，高于 4.4% 预期；工业增加值增 5.5%，但内需疲软令沪深 300 连续 10 周下跌。", "url": "https://x.com/i/trending/2112003183275090362", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T10:15:42.000Z"}, {"id": "2112795003680342391", "domain": "商业", "title_en": "S&P 500's Top 15 Stocks Hit Record 46.7% Share", "title_zh": "标普 500 前 15 大股权重创纪录达 46.7%", "hook_en": "A handful of tech giants now steer the entire S&P 500, with Nvidia alone claiming 7.5% of the index's value. Everyday investors in broad funds might not realize how much they're riding on these leaders.", "hook_zh": "少数科技巨头主导整个标普 500，仅英伟达就占指数市值约 7.5%。买宽基基金的普通投资者未必意识到自己有多依赖这些龙头。", "summary_en": "The 15 largest S&P 500 stocks account for a record 46.7% of the index's total market value, far exceeding the 27.2% seen at the 2000 dot-com peak. Nvidia tops the list at 7.5%, followed by Apple at 7.1%, Alphabet at 5.9%, and Microsoft at 5.6%, with these four alone making up 26.1%. The top five equal the market cap of the bottom 434 companies, prompting market watchers to question diversification in popular index funds and ETFs. While some highlight the leaders' strong cash flows, others note that any slowdown could hit passive portfolios hard.", "summary_zh": "标普 500 最大的 15 只股票合计占指数总市值创纪录的 46.7%，远超 2000 年互联网泡沫顶峰时的 27.2%。英伟达以 7.5% 居首，苹果 7.1%、Alphabet 5.9%、微软 5.6%，四家合计 26.1%。前五名市值相当于后 434 家之和，引发对热门指数基金与 ETF「分散」成色的质疑。有人强调龙头现金流强劲，也有人警告一旦放缓，被动组合将承压。", "body_en": "S&P 500's Top 15 Stocks Hit Record 46.7% Share.\n\nA handful of tech giants now steer the entire S&P 500, with Nvidia alone claiming 7.5% of the index's value. Everyday investors in broad funds might not realize how much they're riding on these leaders.\n\nThe 15 largest S&P 500 stocks account for a record 46.7% of the index's total market value, far exceeding the 27.2% seen at the 2000 dot-com peak. Nvidia tops the list at 7.5%, followed by Apple at 7.1%, Alphabet at 5.9%, and Microsoft at 5.6%, with these four alone making up 26.1%.\n\nThe top five equal the market cap of the bottom 434 companies, prompting market watchers to question diversification in popular index funds and ETFs. While some highlight the leaders' strong cash flows, others note that any slowdown could hit passive portfolios hard.", "body_zh": "标普 500 前 15 大股权重创纪录达 46.7%。\n\n少数科技巨头主导整个标普 500，仅英伟达就占指数市值约 7.5%。买宽基基金的普通投资者未必意识到自己有多依赖这些龙头。\n\n标普 500 最大的 15 只股票合计占指数总市值创纪录的 46.7%，远超 2000 年互联网泡沫顶峰时的 27.2%。英伟达以 7.5% 居首，苹果 7.1%、Alphabet 5.9%、微软 5.6%，四家合计 26.1%。\n\n前五名市值相当于后 434 家之和，引发对热门指数基金与 ETF「分散」成色的质疑。有人强调龙头现金流强劲，也有人警告一旦放缓，被动组合将承压。", "url": "https://x.com/i/trending/2112795003680342391", "category": "News", "topics": ["Stocks"], "updated_at": "2026-10-21T06:39:54.000Z"}, {"id": "2112637290933789168", "domain": "商业", "title_en": "Netflix Stock Drops After Mixed Earnings and Weak Guidance", "title_zh": "奈飞财报喜忧参半、指引偏弱，股价盘后大跌", "hook_en": "Netflix hit Wall Street with solid profits but a revenue forecast that fell short, sending shares tumbling in after-hours trading.", "hook_zh": "利润尚可，但营收展望不及预期，盘后交易中奈飞股价应声下挫。", "summary_en": "The company reported third-quarter revenue of $12.87 billion, up 12% from last year and matching estimates, with earnings per share of $0.87 beating forecasts and operating margins hitting a record 34.6%. However, fourth-quarter revenue guidance of $13.44 billion missed expectations around $13.5 billion, and full-year ad revenue outlook dropped to $2.7 billion from $3 billion. Investors pointed to slowing growth and competition from YouTube, which grabbed 14.2% of U.S. TV viewing time in July 2026 versus Netflix's 7.8%, as one investor noted Netflix feels like a 'dormant subscription' amid shifting habits. Shares plunged over 6% in extended trading, erasing billions in market value.", "summary_zh": "奈飞三季度营收 128.7 亿美元，同比增 12%、符合预期；每股收益 0.87 美元超预期，运营利润率创纪录达 34.6%。但四季度营收指引 134.4 亿美元低于约 135 亿美元预期，全年广告收入展望从 30 亿下调至 27 亿美元。投资者担忧增长放缓及 YouTube 竞争——2026 年 7 月 YouTube 占美国电视观看时长 14.2%，奈飞仅 7.8%。盘后股价跌逾 6%，市值蒸发数十亿美元。", "body_en": "Netflix Stock Drops After Mixed Earnings and Weak Guidance.\n\nNetflix hit Wall Street with solid profits but a revenue forecast that fell short, sending shares tumbling in after-hours trading.\n\nThe company reported third-quarter revenue of $12.87 billion, up 12% from last year and matching estimates, with earnings per share of $0.87 beating forecasts and operating margins hitting a record 34.6%. However, fourth-quarter revenue guidance of $13.44 billion missed expectations around $13.5 billion, and full-year ad revenue outlook dropped to $2.7 billion from $3 billion.\n\nInvestors pointed to slowing growth and competition from YouTube, which grabbed 14.2% of U.S. TV viewing time in July 2026 versus Netflix's 7.8%, as one investor noted Netflix feels like a 'dormant subscription' amid shifting habits. Shares plunged over 6% in extended trading, erasing billions in market value.", "body_zh": "奈飞财报喜忧参半、指引偏弱，股价盘后大跌。\n\n利润尚可，但营收展望不及预期，盘后交易中奈飞股价应声下挫。\n\n奈飞三季度营收 128.7 亿美元，同比增 12%、符合预期；每股收益 0.87 美元超预期，运营利润率创纪录达 34.6%。但四季度营收指引 134.4 亿美元低于约 135 亿美元预期，全年广告收入展望从 30 亿下调至 27 亿美元。\n\n投资者担忧增长放缓及 YouTube 竞争——2026 年 7 月 YouTube 占美国电视观看时长 14.2%，奈飞仅 7.8%。盘后股价跌逾 6%，市值蒸发数十亿美元。", "url": "https://x.com/i/trending/2112637290933789168", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T11:44:14.000Z"}, {"id": "2112496627072319559", "domain": "商业", "title_en": "Gujarat Deputy CM Sanghavi Secures Japan Investment Talks in Tokyo", "title_zh": "古吉拉特副首席部长东京招商，对接日本企业投资", "hook_en": "In Tokyo's formal meeting rooms, Gujarat's Deputy Chief Minister Harsh Sanghavi shook hands with Japanese corporate leaders, flags of both nations side by side, discussing fresh investments amid cultural exchanges like gifts of traditional textiles.", "hook_zh": "Harsh Sanghavi 在东京会见日本企业领袖，国旗并立，商谈化工、生命科学与绿色能源等投资。", "summary_en": "Harsh Sanghavi leads a high-level delegation in Tokyo to boost industrial ties ahead of the January 2027 Vibrant Gujarat Global Summit, targeting chemicals, life sciences, green energy, textiles, and advanced manufacturing. He held key meetings with Kaneka Corporation, ITOCHU Corporation, Ultra Fabrics, and Nippon Steel Chairman Eiji Hashimoto to explore collaborations, including precision steel and synthetic leather opportunities. These efforts build on existing projects like ITOCHU’s green ammonia facility at Kandla port and aim to draw Japanese expertise to Gujarat’s growing industries. The delegation will also engage with Shizuoka’s government for further partnerships.", "summary_zh": "为筹备 2027 年 1 月充满活力的古吉拉特全球峰会，Sanghavi 率团赴东京推动化工、生命科学、绿色能源、纺织与先进制造合作。他会见钟渊化学、伊藤忠、Ultra Fabrics 及日本制铁会长桥本英二，探讨精密钢材与合成革等机会。合作延续伊藤忠在坎德拉港的绿色氨项目等既有布局，并计划与静冈县政府进一步对接。", "body_en": "Gujarat Deputy CM Sanghavi Secures Japan Investment Talks in Tokyo.\n\nIn Tokyo's formal meeting rooms, Gujarat's Deputy Chief Minister Harsh Sanghavi shook hands with Japanese corporate leaders, flags of both nations side by side, discussing fresh investments amid cultural exchanges like gifts of traditional textiles.\n\nHarsh Sanghavi leads a high-level delegation in Tokyo to boost industrial ties ahead of the January 2027 Vibrant Gujarat Global Summit, targeting chemicals, life sciences, green energy, textiles, and advanced manufacturing. He held key meetings with Kaneka Corporation, ITOCHU Corporation, Ultra Fabrics, and Nippon Steel Chairman Eiji Hashimoto to explore collaborations, including precision steel and synthetic leather opportunities.\n\nThese efforts build on existing projects like ITOCHU’s green ammonia facility at Kandla port and aim to draw Japanese expertise to Gujarat’s growing industries. The delegation will also engage with Shizuoka’s government for further partnerships.", "body_zh": "古吉拉特副首席部长东京招商，对接日本企业投资。\n\nHarsh Sanghavi 在东京会见日本企业领袖，国旗并立，商谈化工、生命科学与绿色能源等投资。\n\n为筹备 2027 年 1 月充满活力的古吉拉特全球峰会，Sanghavi 率团赴东京推动化工、生命科学、绿色能源、纺织与先进制造合作。\n\n他会见钟渊化学、伊藤忠、Ultra Fabrics 及日本制铁会长桥本英二，探讨精密钢材与合成革等机会。合作延续伊藤忠在坎德拉港的绿色氨项目等既有布局，并计划与静冈县政府进一步对接。", "url": "https://x.com/i/trending/2112496627072319559", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T10:54:40.000Z"}, {"id": "2112825460593934566", "domain": "商业", "title_en": "India Eyes Raising FDI Limit in Public Sector Banks to 49 Percent", "title_zh": "印度拟将公有银行外资持股上限提至 49%", "hook_en": "Public sector banks in India could soon welcome more foreign investment, with officials drafting plans to nearly double the cap from 20 percent to 49 percent.", "hook_zh": "官员正起草方案，拟把公有银行外商直接投资上限从 20% 近乎翻倍至 49%。", "summary_en": "The Finance Ministry has prepared a draft Cabinet note to increase the foreign direct investment limit for public sector banks, backed by a Reserve Bank of India recommendation to draw in more capital. This would level the field with private banks, which already allow up to 74 percent FDI, while current foreign holdings in major PSU banks like Canara Bank (12.27 percent) and State Bank of India (11.07 percent) remain well below the existing 20 percent ceiling. Supporters see it strengthening banks for global competition, though skeptics question the need amid unused limits and raise concerns over public control, with the government set to retain over 51 percent stake.", "summary_zh": "财政部已准备内阁草案，拟提高公有银行 FDI 上限，印度储备银行亦建议吸引更多资本。此举将缩小与私有银行（最高 74% FDI）的差距；目前 Canara Bank（约 12.27%）、印度国家银行（约 11.07%）等外资持股仍远低于现行 20% 上限。支持者认为有助参与全球竞争，质疑者则指出额度尚未用满并担心公共控制；政府拟仍持股逾 51%。", "body_en": "India Eyes Raising FDI Limit in Public Sector Banks to 49 Percent.\n\nPublic sector banks in India could soon welcome more foreign investment, with officials drafting plans to nearly double the cap from 20 percent to 49 percent.\n\nThe Finance Ministry has prepared a draft Cabinet note to increase the foreign direct investment limit for public sector banks, backed by a Reserve Bank of India recommendation to draw in more capital.\n\nThis would level the field with private banks, which already allow up to 74 percent FDI, while current foreign holdings in major PSU banks like Canara Bank (12.27 percent) and State Bank of India (11.07 percent) remain well below the existing 20 percent ceiling. Supporters see it strengthening banks for global competition, though skeptics question the need amid unused limits and raise concerns over public control, with the government set to retain over 51 percent stake.", "body_zh": "印度拟将公有银行外资持股上限提至 49%。\n\n官员正起草方案，拟把公有银行外商直接投资上限从 20% 近乎翻倍至 49%。\n\n财政部已准备内阁草案，拟提高公有银行 FDI 上限，印度储备银行亦建议吸引更多资本。\n\n此举将缩小与私有银行（最高 74% FDI）的差距；目前 Canara Bank（约 12.27%）、印度国家银行（约 11.07%）等外资持股仍远低于现行 20% 上限。支持者认为有助参与全球竞争，质疑者则指出额度尚未用满并担心公共控制；政府拟仍持股逾 51%。", "url": "https://x.com/i/trending/2112825460593934566", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T10:44:03.000Z"}, {"id": "2112656501483684033", "domain": "商业", "title_en": "United Airlines Hits Record Revenue but Misses Earnings on High Fuel Costs", "title_zh": "美联航营收创新高，高油价拖累利润不及预期", "hook_en": "United Airlines flew a record number of passengers and smashed revenue highs this quarter, but soaring fuel prices clipped their earnings wings.", "hook_zh": "本季旅客量与营收刷新纪录，但油价飙升令每股收益略低于华尔街预期。", "summary_en": "For the three months ended September 30, United reported $17.9 billion in operating revenue, up 17.4% from last year, with passenger revenue rising 17.6% to $16.24 billion and a record 49.5 million customers carried. Adjusted earnings per share came in at $2.54, slightly below Wall Street's $2.57 to $2.59 expectations, as fuel costs surged 61.6% to $4.84 billion at $3.90 per gallon. CEO Scott Kirby praised employees' resilience and highlighted Starlink Wi-Fi now on over 640 aircraft, while Q4 guidance forecasts over 20% revenue growth but adjusted EPS of just $0.50 to $1.50 amid $4.80 per gallon fuel—far under analyst hopes—sending shares down 2% to 4% after hours.", "summary_zh": "截至 9 月 30 日的三个月，美联航运营收入 179 亿美元，同比增 17.4%；客运收入增 17.6% 至 162.4 亿美元，承运旅客创纪录 4950 万人次。调整后每股收益 2.54 美元，略低于 2.57–2.59 美元预期；燃油成本大增 61.6% 至 48.4 亿美元，均价每加仑 3.90 美元。CEO Scott Kirby 肯定员工韧性，并称超 640 架飞机已装 Starlink Wi-Fi。四季度营收料增逾 20%，但调整 EPS 指引仅 0.50–1.50 美元，油价假设约 4.80 美元，盘后股价跌约 2%–4%。", "body_en": "United Airlines Hits Record Revenue but Misses Earnings on High Fuel Costs.\n\nUnited Airlines flew a record number of passengers and smashed revenue highs this quarter, but soaring fuel prices clipped their earnings wings.\n\nFor the three months ended September 30, United reported $17.9 billion in operating revenue, up 17.4% from last year, with passenger revenue rising 17.6% to $16.24 billion and a record 49.5 million customers carried.\n\nAdjusted earnings per share came in at $2.54, slightly below Wall Street's $2.57 to $2.59 expectations, as fuel costs surged 61.6% to $4.84 billion at $3.90 per gallon. CEO Scott Kirby praised employees' resilience and highlighted Starlink Wi-Fi now on over 640 aircraft, while Q4 guidance forecasts over 20% revenue growth but adjusted EPS of just $0.50 to $1.50 amid $4.80 per gallon fuel—far under analyst hopes—sending shares down 2% to 4% after hours.", "body_zh": "美联航营收创新高，高油价拖累利润不及预期。\n\n本季旅客量与营收刷新纪录，但油价飙升令每股收益略低于华尔街预期。\n\n截至 9 月 30 日的三个月，美联航运营收入 179 亿美元，同比增 17.4%；客运收入增 17.6% 至 162.4 亿美元，承运旅客创纪录 4950 万人次。调整后每股收益 2.54 美元，略低于 2.57–2.59 美元预期；燃油成本大增 61.6% 至 48.4 亿美元，均价每加仑 3.90 美元。\n\nCEO Scott Kirby 肯定员工韧性，并称超 640 架飞机已装 Starlink Wi-Fi。四季度营收料增逾 20%，但调整 EPS 指引仅 0.50–1.50 美元，油价假设约 4.80 美元，盘后股价跌约 2%–4%。", "url": "https://x.com/i/trending/2112656501483684033", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T01:10:41.000Z"}, {"id": "2112501506846916810", "domain": "商业", "title_en": "GM Shares Drop After Earnings Beat but Lowered 2026 Profit Outlook", "title_zh": "通用汽车季报超预期却下调全年展望，股价承压", "hook_en": "General Motors posted a strong quarter with revenue topping estimates, yet shares tumbled as investors zeroed in on a narrower full-year profit forecast amid rising costs.", "hook_zh": "营收与利润好于预期，但全年盈利指引收窄、成本上升，投资者用脚投票。", "summary_en": "GM reported third-quarter revenue of $50.02 billion, beating expectations of $48.7 billion, with adjusted EPS at $3.70 versus $3.63 anticipated and adjusted EBIT of $4.11 billion. Despite this and a new $20 billion stock buyback plus a $0.18 quarterly dividend, the company cut its 2026 outlook to adjusted EPS of $12.75-$13.75, below prior consensus, and adjusted EBIT of $14.5-$15.5 billion due to higher commodity and logistics costs. Strong North American truck sales boosted automotive free cash flow 40% to $5.9 billion, but critics questioned buybacks over EV and autonomy investments as shares fell as much as 8% in premarket trading to around $77.", "summary_zh": "通用汽车三季度营收 500.2 亿美元，高于预期 487 亿；调整 EPS 3.70 美元对预期 3.63 美元，调整 EBIT 41.1 亿美元。公司同时宣布 200 亿美元回购与每季 0.18 美元股息，但因大宗商品与物流成本上升，将 2026 年调整 EPS 展望下调至 12.75–13.75 美元、调整 EBIT 145–155 亿美元，低于此前共识。北美皮卡销售推动汽车自由现金流增 40% 至 59 亿美元；盘前股价一度跌约 8% 至 77 美元附近，有批评质疑回购优先于电动车与自动驾驶投入。", "body_en": "GM Shares Drop After Earnings Beat but Lowered 2026 Profit Outlook.\n\nGeneral Motors posted a strong quarter with revenue topping estimates, yet shares tumbled as investors zeroed in on a narrower full-year profit forecast amid rising costs.\n\nGM reported third-quarter revenue of $50.02 billion, beating expectations of $48.7 billion, with adjusted EPS at $3.70 versus $3.63 anticipated and adjusted EBIT of $4.11 billion.\n\nDespite this and a new $20 billion stock buyback plus a $0.18 quarterly dividend, the company cut its 2026 outlook to adjusted EPS of $12.75-$13.75, below prior consensus, and adjusted EBIT of $14.5-$15.5 billion due to higher commodity and logistics costs. Strong North American truck sales boosted automotive free cash flow 40% to $5.9 billion, but critics questioned buybacks over EV and autonomy investments as shares fell as much as 8% in premarket trading to around $77.", "body_zh": "通用汽车季报超预期却下调全年展望，股价承压。\n\n营收与利润好于预期，但全年盈利指引收窄、成本上升，投资者用脚投票。\n\n通用汽车三季度营收 500.2 亿美元，高于预期 487 亿；调整 EPS 3.70 美元对预期 3.63 美元，调整 EBIT 41.1 亿美元。\n\n公司同时宣布 200 亿美元回购与每季 0.18 美元股息，但因大宗商品与物流成本上升，将 2026 年调整 EPS 展望下调至 12.75–13.75 美元、调整 EBIT 145–155 亿美元，低于此前共识。北美皮卡销售推动汽车自由现金流增 40% 至 59 亿美元；盘前股价一度跌约 8% 至 77 美元附近，有批评质疑回购优先于电动车与自动驾驶投入。", "url": "https://x.com/i/trending/2112501506846916810", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-20T20:55:03.000Z"}, {"id": "2112369182595788855", "domain": "商业", "title_en": "Jio Platforms Gears Up for India's Largest IPO with ₹30,000 Crore Raise", "title_zh": "Jio Platforms 冲刺印度史上最大 IPO，募资约 3 万亿卢比", "hook_en": "From making mobile data affordable for millions to powering everyday streaming, Jio's decade-long journey has transformed lives across India.", "hook_zh": "从让亿万人用得起移动流量，到撑起日常流媒体，Jio 十年改变了印度数字生活。", "summary_en": "Jio Platforms, Reliance Industries' digital arm, will launch India's biggest IPO on October 21, offering up to 27 crore shares to raise around ₹30,213 crore at the top price of ₹1,119 each. The funds will mostly repay debt at its telecom subsidiary, which serves 533 million customers and handles 60% of India's wireless data traffic. People fondly remember the shift from cautious video watching to seamless scrolling and calls, crediting Jio's growth under Mukesh and Akash Ambani, while analysts watch if its scale can drive better returns through efficiency and new services like cloud and broadband.", "summary_zh": "信实工业数字臂膀 Jio Platforms 定于 10 月 21 日启动印度最大 IPO，最多发行约 27 亿股，顶格价约 1119 卢比/股，募资约 30213 亿卢比。资金主要用于偿还电信子公司债务；该业务服务约 5.33 亿用户，承载印度约 60% 无线数据流量。公众回忆从「省着用视频」到流畅刷屏通话的转变，归功于穆克什与阿卡什·安巴尼治下的扩张；分析师则关注规模能否靠效率与云、宽带等新业务转化为更好回报。", "body_en": "Jio Platforms Gears Up for India's Largest IPO with ₹30,000 Crore Raise.\n\nFrom making mobile data affordable for millions to powering everyday streaming, Jio's decade-long journey has transformed lives across India.\n\nJio Platforms, Reliance Industries' digital arm, will launch India's biggest IPO on October 21, offering up to 27 crore shares to raise around ₹30,213 crore at the top price of ₹1,119 each.\n\nThe funds will mostly repay debt at its telecom subsidiary, which serves 533 million customers and handles 60% of India's wireless data traffic. People fondly remember the shift from cautious video watching to seamless scrolling and calls, crediting Jio's growth under Mukesh and Akash Ambani, while analysts watch if its scale can drive better returns through efficiency and new services like cloud and broadband.", "body_zh": "Jio Platforms 冲刺印度史上最大 IPO，募资约 3 万亿卢比。\n\n从让亿万人用得起移动流量，到撑起日常流媒体，Jio 十年改变了印度数字生活。\n\n信实工业数字臂膀 Jio Platforms 定于 10 月 21 日启动印度最大 IPO，最多发行约 27 亿股，顶格价约 1119 卢比/股，募资约 30213 亿卢比。\n\n资金主要用于偿还电信子公司债务；该业务服务约 5.33 亿用户，承载印度约 60% 无线数据流量。公众回忆从「省着用视频」到流畅刷屏通话的转变，归功于穆克什与阿卡什·安巴尼治下的扩张；分析师则关注规模能否靠效率与云、宽带等新业务转化为更好回报。", "url": "https://x.com/i/trending/2112369182595788855", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T02:29:15.000Z"}, {"id": "2112486884211650655", "domain": "中国", "title_en": "Sindh CM Secures 34 China Deals at Shanghai Conference", "title_zh": "巴基斯坦信德省首席部长在沪签下 34 项对华合作", "hook_en": "Sindh Chief Minister Syed Murad Ali Shah stood by as 34 key agreements were signed in Shanghai, unlocking fresh paths for jobs and growth back home.", "hook_zh": "信德省首席部长穆拉德·阿里·沙阿在上海见证 34 项关键协议签署，为本地就业与增长打开新路。", "summary_en": "At the Sindh Investment and Trade Conference in Shanghai on October 15, 2026, CM Shah witnessed 34 memorandums of understanding and agreements with Chinese partners—10 government-to-government and 24 business-to-business. These cover energy like Thar coal, electric vehicles, AI-driven digital transformation, agriculture, and logistics, building on successes such as power plants and wind farms in the province. The event drew 400 delegates from over 100 companies, highlighting Sindh's ports, workforce, resources, and tax incentives, while follow-up meetings in Wuhan advanced projects like climate-resilient crops and Karachi's water supply. Supporters praise the moves for fostering investment, innovation, and prosperity rooted in the 75-year Pak-China friendship.", "summary_zh": "2026 年 10 月 15 日上海举行的信德投资贸易会议上，沙阿见证与中国伙伴签署 34 份备忘录与协议，其中政府间 10 项、企业间 24 项，涵盖塔尔煤电、电动车、AI 数字化、农业与物流等。活动吸引百余家企业约 400 名代表；后续武汉会谈推进耐气候作物与卡拉奇供水等项目。支持者称这延续巴中建交 75 年的合作传统。", "body_en": "Sindh CM Secures 34 China Deals at Shanghai Conference.\n\nSindh Chief Minister Syed Murad Ali Shah stood by as 34 key agreements were signed in Shanghai, unlocking fresh paths for jobs and growth back home.\n\nAt the Sindh Investment and Trade Conference in Shanghai on October 15, 2026, CM Shah witnessed 34 memorandums of understanding and agreements with Chinese partners—10 government-to-government and 24 business-to-business. These cover energy like Thar coal, electric vehicles, AI-driven digital transformation, agriculture, and logistics, building on successes such as power plants and wind farms in the province.\n\nThe event drew 400 delegates from over 100 companies, highlighting Sindh's ports, workforce, resources, and tax incentives, while follow-up meetings in Wuhan advanced projects like climate-resilient crops and Karachi's water supply. Supporters praise the moves for fostering investment, innovation, and prosperity rooted in the 75-year Pak-China friendship.", "body_zh": "巴基斯坦信德省首席部长在沪签下 34 项对华合作。\n\n信德省首席部长穆拉德·阿里·沙阿在上海见证 34 项关键协议签署，为本地就业与增长打开新路。\n\n2026 年 10 月 15 日上海举行的信德投资贸易会议上，沙阿见证与中国伙伴签署 34 份备忘录与协议，其中政府间 10 项、企业间 24 项，涵盖塔尔煤电、电动车、AI 数字化、农业与物流等。活动吸引百余家企业约 400 名代表；后续武汉会谈推进耐气候作物与卡拉奇供水等项目。\n\n支持者称这延续巴中建交 75 年的合作传统。", "url": "https://x.com/i/trending/2112486884211650655", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T13:25:56.000Z"}, {"id": "2112022699237310708", "domain": "中国", "title_en": "Liangzhu Forum Opens Marking 90th Anniversary of Ancient Ruins Discovery", "title_zh": "良渚论坛开幕：纪念遗址发现 90 周年", "hook_en": "Experts from nearly 60 countries gathered in Hangzhou to celebrate 5,000-year-old Liangzhu ruins, blending ancient history with modern tech and global chats.", "hook_zh": "近 60 国专家齐聚杭州，围绕约五千年历史的良渚遗址，把古代文明、现代技术与国际交流放在同一舞台。", "summary_en": "The fourth Liangzhu Forum, held October 18-20 in Zhejiang province, honors the 90th anniversary of discovering the UNESCO-listed Liangzhu ruins, evidence of an early advanced society with rice farming. Under the theme 'Bridging the Past and the Future,' it features forums, an artists' exhibition, a cultural market with Belt and Road products, and AI glasses at the museum that guide visitors using real archives. An American archaeologist on his first China trip praised the scenery and hopes to study sites, while an Australian curator noted the link between ancient Liangzhu and today's Hangzhou; young volunteers provide bilingual support amid calls for global heritage cooperation.", "summary_zh": "第四届良渚论坛于 10 月 18–20 日在浙江举行，纪念列入联合国教科文组织名录的良渚遗址发现 90 周年——遗址见证早期发达社会与稻作农业。主题为「连接过去与未来」，活动包括论坛、艺术家展览、「一带一路」相关文创市集，以及博物馆用真实档案导览的 AI 眼镜。首次访华的美国考古学家称赞景色并希望研究遗址；澳大利亚策展人谈到古代良渚与今日杭州的关联；青年志愿者提供双语服务，各方呼吁加强全球遗产合作。", "body_en": "Liangzhu Forum Opens Marking 90th Anniversary of Ancient Ruins Discovery.\n\nExperts from nearly 60 countries gathered in Hangzhou to celebrate 5,000-year-old Liangzhu ruins, blending ancient history with modern tech and global chats.\n\nThe fourth Liangzhu Forum, held October 18-20 in Zhejiang province, honors the 90th anniversary of discovering the UNESCO-listed Liangzhu ruins, evidence of an early advanced society with rice farming.\n\nUnder the theme 'Bridging the Past and the Future,' it features forums, an artists' exhibition, a cultural market with Belt and Road products, and AI glasses at the museum that guide visitors using real archives. An American archaeologist on his first China trip praised the scenery and hopes to study sites, while an Australian curator noted the link between ancient Liangzhu and today's Hangzhou; young volunteers provide bilingual support amid calls for global heritage cooperation.", "body_zh": "良渚论坛开幕：纪念遗址发现 90 周年。\n\n近 60 国专家齐聚杭州，围绕约五千年历史的良渚遗址，把古代文明、现代技术与国际交流放在同一舞台。\n\n第四届良渚论坛于 10 月 18–20 日在浙江举行，纪念列入联合国教科文组织名录的良渚遗址发现 90 周年——遗址见证早期发达社会与稻作农业。主题为「连接过去与未来」，活动包括论坛、艺术家展览、「一带一路」相关文创市集，以及博物馆用真实档案导览的 AI 眼镜。\n\n首次访华的美国考古学家称赞景色并希望研究遗址；澳大利亚策展人谈到古代良渚与今日杭州的关联；青年志愿者提供双语服务，各方呼吁加强全球遗产合作。", "url": "https://x.com/i/trending/2112022699237310708", "category": "News", "topics": ["Science"], "updated_at": "2026-10-20T03:21:48.000Z"}, {"id": "2112044241161433358", "domain": "中国", "title_en": "Asia Markets Plunge on AI Spending Worries and Oil Pressures", "title_zh": "亚洲股市因 AI 开支忧虑与油价承压深跌", "hook_en": "Japanese and South Korean stocks have shed hundreds of billions in value over two tense weeks. Investors are pulling back from AI bets amid rising oil prices and global jitters.", "hook_zh": "日韩股市两周蒸发数千亿美元市值。投资者在油价上涨与全球动荡中撤出 AI 押注。", "summary_en": "Japan's Nikkei dropped nearly 10% in recent sessions, wiping out over ¥100 trillion, or about $700 billion, from equities. South Korea's KOSPI fell around 3.5% to 4% on Tuesday, part of a 22% two-week slide that erased ₩1,118 trillion, or $745 billion, with Samsung Electronics and SK Hynix hit hard as key AI chip suppliers. A South Korean AI cloud firm, Elice Inc., saw its shares plunge 30% on its IPO debut despite heavy retail interest, fueled by U.S. tech sell-offs, Middle East oil tensions, and doubts over AI investment returns. Markets now eye earnings reports and oil shifts for signs of recovery.", "summary_zh": "日经近几日累计下跌近 10%，市值蒸发逾 100 万亿日元（约 7000 亿美元）。韩国综指周二再跌约 3.5%–4%，两周累计约 22%、蒸发约 1118 万亿韩元（约 7450 亿美元），三星电子与 SK 海力士等 AI 供应链重镇受创。韩国 AI 云公司 Elice 上市首日暴跌约 30%。市场等待财报与油价信号。", "body_en": "Asia Markets Plunge on AI Spending Worries and Oil Pressures.\n\nJapanese and South Korean stocks have shed hundreds of billions in value over two tense weeks. Investors are pulling back from AI bets amid rising oil prices and global jitters.\n\nJapan's Nikkei dropped nearly 10% in recent sessions, wiping out over ¥100 trillion, or about $700 billion, from equities. South Korea's KOSPI fell around 3.5% to 4% on Tuesday, part of a 22% two-week slide that erased ₩1,118 trillion, or $745 billion, with Samsung Electronics and SK Hynix hit hard as key AI chip suppliers.\n\nA South Korean AI cloud firm, Elice Inc., saw its shares plunge 30% on its IPO debut despite heavy retail interest, fueled by U.S. tech sell-offs, Middle East oil tensions, and doubts over AI investment returns. Markets now eye earnings reports and oil shifts for signs of recovery.", "body_zh": "亚洲股市因 AI 开支忧虑与油价承压深跌。\n\n日韩股市两周蒸发数千亿美元市值。投资者在油价上涨与全球动荡中撤出 AI 押注。\n\n日经近几日累计下跌近 10%，市值蒸发逾 100 万亿日元（约 7000 亿美元）。韩国综指周二再跌约 3.5%–4%，两周累计约 22%、蒸发约 1118 万亿韩元（约 7450 亿美元），三星电子与 SK 海力士等 AI 供应链重镇受创。\n\n韩国 AI 云公司 Elice 上市首日暴跌约 30%。市场等待财报与油价信号。", "url": "https://x.com/i/trending/2112044241161433358", "category": "News", "topics": ["Stocks"], "updated_at": "2026-10-20T12:59:35.000Z"}, {"id": "2112290595213554074", "domain": "中国", "title_en": "Irish Government Pushes to Reform Triple Lock on Peacekeeping Missions", "title_zh": "爱尔兰辩论改革维和「三重锁」部署机制", "hook_en": "In a heated Dáil session, Taoiseach Micheál Martin grew animated defending Ireland's peacekeeping role, while opposition TDs waved 'Save Neutrality' signs amid shouts from the floor.", "hook_zh": "总理马丁在议会回击：「你凭什么教训我爱尔兰中立？俄罗斯不该对爱尔兰参与维和拥有否决权。」现场气氛火药味十足。", "summary_en": "Taoiseach Micheál Martin argued that reforming the Triple Lock would end vetoes from Russia, China, or the US blocking Ireland's UN peacekeeping missions, as no new ones have been approved since 2014. The bill removes UN Security Council approval for deployments over 12 troops, requiring only government and Dáil okay, while keeping ties to UN, OSCE, or EU bodies. Opposition from left and right, including Aontú and People Before Profit, calls it a sovereignty sellout risking EU military alignment without a referendum, uniting protesters outside parliament.", "summary_zh": "爱尔兰政府推进《国防（修正）法案》，拟废除「三重锁」中的联合国授权要求——目前向海外部署超过 12 名国防军须经政府批准、议会表决与联合国背书。马丁等支持者称可防止俄中等大国否决，保障如黎巴嫩维和等任务，尤其在 2014 年以来联合国僵局下。反对派包括玛丽·卢·麦克唐纳与 Peadar Tóibín 指责此举偏离维和、倒向欧盟军事行动，要求公投；议员挥舞「保卫中立」标语，民间亦有抗议。", "body_en": "Ireland Debates Reforming Triple Lock on Peacekeeping Deployments.\n\nTaoiseach Micheál Martin fired back in the Dáil: 'How dare you lecture me about Irish neutrality? Russia should not have a veto on Irish participation in peacekeeping.' The exchange captured the chamber's raw tension over neutrality's future.\n\nThe Irish government is advancing the Defence (Amendment) Bill to scrap the UN mandate requirement in the Triple Lock, which currently needs government approval, a Dáil vote, and UN backing for deploying over 12 Defence Forces members abroad.\n\nProponents like Martin argue it prevents vetoes by powers like Russia or China, safeguarding missions such as Ireland's in Lebanon amid UN gridlock since 2014. Opposition leaders, including Mary Lou McDonald and Peadar Tóibín, decry it as a drift from peacekeeping to EU-aligned military action and demand a referendum, with TDs waving 'Save Neutrality' signs amid public protests.", "body_zh": "爱尔兰辩论改革维和「三重锁」部署机制。\n\n总理马丁在议会回击：「你凭什么教训我爱尔兰中立？俄罗斯不该对爱尔兰参与维和拥有否决权。」现场气氛火药味十足。\n\n爱尔兰政府推进《国防（修正）法案》，拟废除「三重锁」中的联合国授权要求——目前向海外部署超过 12 名国防军须经政府批准、议会表决与联合国背书。\n\n马丁等支持者称可防止俄中等大国否决，保障如黎巴嫩维和等任务，尤其在 2014 年以来联合国僵局下。反对派包括玛丽·卢·麦克唐纳与 Peadar Tóibín 指责此举偏离维和、倒向欧盟军事行动，要求公投；议员挥舞「保卫中立」标语，民间亦有抗议。", "url": "https://x.com/i/trending/2112290595213554074", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T11:50:11.000Z"}, {"id": "2112572571275370804", "domain": "中国", "title_en": "Japan Faces Yttrium Shortage, Seeks US Help Against China Curbs", "title_zh": "日本钇供应告急，寻求美方协助应对中国出口限制", "hook_en": "Japan has just months left before running out of yttrium, a vital metal for jet engines and chips, as Chinese shipments nearly halt.", "hook_zh": "用于喷气发动机与芯片的关键金属钇，中国对日发运几近停滞，日本称只剩数月库存。", "summary_en": "Yttrium oxide shipments from China to Japan have almost stopped in 2026 after tighter export restrictions, driving outside prices to $1,150 per kilogram from $6 two years ago. The shortage endangers aerospace, autos, electronics, and defense, with a Japanese official warning of world economy risks if ignored. Japan asked the US to pressure China, while Washington withheld jet engine exports to Beijing and discussed solutions in recent meetings. Allies seek substitutes and new supplies amid limited global processing outside China.", "summary_zh": "2026 年中国收紧出口限制后，氧化钇对日发运几乎停止，日本以外市场价格从两年前每公斤约 6 美元飙至 1150 美元。短缺危及航空航天、汽车、电子与国防，日方官员警告若忽视将冲击世界经济。日本请求美国向中国施压；华盛顿则暂停对北京喷气发动机出口，并在近期会谈中讨论对策。盟友正寻找替代品与新供应，因中国以外全球加工能力有限。", "body_en": "Japan Faces Yttrium Shortage, Seeks US Help Against China Curbs.\n\nJapan has just months left before running out of yttrium, a vital metal for jet engines and chips, as Chinese shipments nearly halt.\n\nYttrium oxide shipments from China to Japan have almost stopped in 2026 after tighter export restrictions, driving outside prices to $1,150 per kilogram from $6 two years ago. The shortage endangers aerospace, autos, electronics, and defense, with a Japanese official warning of world economy risks if ignored.\n\nJapan asked the US to pressure China, while Washington withheld jet engine exports to Beijing and discussed solutions in recent meetings. Allies seek substitutes and new supplies amid limited global processing outside China.", "body_zh": "日本钇供应告急，寻求美方协助应对中国出口限制。\n\n用于喷气发动机与芯片的关键金属钇，中国对日发运几近停滞，日本称只剩数月库存。\n\n2026 年中国收紧出口限制后，氧化钇对日发运几乎停止，日本以外市场价格从两年前每公斤约 6 美元飙至 1150 美元。短缺危及航空航天、汽车、电子与国防，日方官员警告若忽视将冲击世界经济。\n\n日本请求美国向中国施压；华盛顿则暂停对北京喷气发动机出口，并在近期会谈中讨论对策。盟友正寻找替代品与新供应，因中国以外全球加工能力有限。", "url": "https://x.com/i/trending/2112572571275370804", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T19:24:35.000Z"}, {"id": "2112810342728323293", "domain": "中国", "title_en": "China Replaces Billboards with Scientists' Portraits in Major Cities", "title_zh": "中国多地用科学家肖像替换地铁商业广告", "hook_en": "Rocket scientist Qian Xuesen's giant portrait now greets shoppers in a Heze mall, replacing flashy ads with faces of national heroes.", "hook_zh": "走进地铁站，巨型屏幕上是杂交水稻先驱袁隆平等科学家，而非炫目广告。这一简单替换引来关于榜样的讨论。", "summary_en": "Since August 2026, cities like Heze, Zhengzhou, and Chongqing have filled public screens in malls, metros, and plazas with portraits of scientists such as Qian Xuesen, Yuan Longping, and Tu Youyou, complete with notes on their breakthroughs in rockets, rice, and malaria drugs. Local venues made these voluntary changes, often timed for holidays to highlight achievements in science and defense. The shift has sparked online talk about honoring innovators over celebrities and what public spaces say about a society's values.", "summary_zh": "中国开始在地铁站、商场等公共大屏用著名科学家肖像替换广告，包括农学家袁隆平、因疟疾治疗获诺奖的屠呦呦、火箭专家钱学森、核物理学家邓稼先等。举措 2026 年 8 月起自山东推开，并扩展至郑州、重庆等城市，尤其在国庆等节点，企业自愿腾出空间致敬科学成就、激励下一代。相关视频在印度等地引发讨论，有人对比本地公共传播，呼吁更重视创新而非商业喧嚣。", "body_en": "China Replaces Metro Ads with Portraits of Scientists.\n\nImagine stepping into a metro station where giant screens honor scientists like hybrid rice pioneer Yuan Longping instead of flashy ads. It's a simple swap that's getting people talking about role models.\n\nChina has started replacing advertisements on large public screens in metro stations, malls, and other spaces with portraits of renowned scientists such as agronomist Yuan Longping, Nobel winner Tu Youyou for malaria treatment, rocket expert Qian Xuesen, and nuclear physicist Deng Jiaxian.\n\nThe initiative began in Shandong province in August 2026 and spread to cities like Zhengzhou and Chongqing, especially around national holidays, with businesses voluntarily dedicating the space to celebrate scientific achievements and inspire the next generation. Videos of these displays have sparked online conversations in places like India, where some contrast it with local public messaging and call for emulating the focus on innovation over commercial noise.", "body_zh": "中国多地用科学家肖像替换地铁商业广告。\n\n走进地铁站，巨型屏幕上是杂交水稻先驱袁隆平等科学家，而非炫目广告。这一简单替换引来关于榜样的讨论。\n\n中国开始在地铁站、商场等公共大屏用著名科学家肖像替换广告，包括农学家袁隆平、因疟疾治疗获诺奖的屠呦呦、火箭专家钱学森、核物理学家邓稼先等。举措 2026 年 8 月起自山东推开，并扩展至郑州、重庆等城市，尤其在国庆等节点，企业自愿腾出空间致敬科学成就、激励下一代。\n\n相关视频在印度等地引发讨论，有人对比本地公共传播，呼吁更重视创新而非商业喧嚣。", "url": "https://x.com/i/trending/2112810342728323293", "category": "News", "topics": ["Celebrity"], "updated_at": "2026-10-21T10:44:04.000Z"}, {"id": "2112405151768100963", "domain": "中国", "title_en": "Philippine Senators Push to Expel Chinese Ambassador Over Sea Threat", "title_zh": "菲律宾参议员推动驱逐中国大使", "hook_en": "Chinese Ambassador Jing Quan's words hung heavy: China could 'easily win' with force in the West Philippine Sea, though it prefers peace. Philippine senators fired back, demanding he be sent home.", "hook_zh": "中国大使景泉称中国可「轻松打赢」与菲冲突，引发参议员要求将其驱逐。", "summary_en": "Senators Risa Hontiveros and Erwin Tulfo filed resolutions urging President Marcos to declare Ambassador Jing persona non grata after his remarks, seen as a veiled threat amid China's vessel harassment and illegal fishing in Philippine waters. The Department of Foreign Affairs summoned Jing to protest, while Senator Kiko Pangilinan sharply challenged Marcos to act decisively. The Chinese Embassy hit back by listing critical lawmakers online, but Malacañang favors diplomatic channels over expulsion to avoid escalation.", "summary_zh": "参议员洪蒂维罗斯与图尔福于 10 月 20 日前后提交决议，敦促马科斯总统宣布大使为不受欢迎人士或要求北京召回。言论回应菲防长称中国为地区麻烦制造者，中国使馆随后在社媒发出「你已上榜」等嘲讽帖。外交部 10 月 19 日召见景泉，称其言论具挑衅性；马科斯更倾向外交沟通而非驱逐。", "body_en": "Philippine Senators Push to Expel Chinese Ambassador Over Threatening Remarks.\n\nChinese Ambassador Jing Quan boasted that China could 'easily win' any conflict with the Philippines, igniting calls from senators to send him packing.\n\nSenators Risa Hontiveros and Erwin Tulfo filed resolutions on October 20 and the day before, urging President Marcos to declare Ambassador Jing persona non grata or request his recall from Beijing. The remarks responded to Defense Secretary Gilberto Teodoro Jr.\n\nlabeling China a regional troublemaker, prompting the Chinese Embassy's taunting social media posts like 'You are now on the list' targeting critics. The Department of Foreign Affairs summoned Jing on October 19, calling his words a provocative threat amid ongoing West Philippine Sea tensions, though Marcos prefers diplomatic talks over expulsion.", "body_zh": "菲律宾参议员推动驱逐中国大使。\n\n中国大使景泉称中国可「轻松打赢」与菲冲突，引发参议员要求将其驱逐。\n\n参议员洪蒂维罗斯与图尔福于 10 月 20 日前后提交决议，敦促马科斯总统宣布大使为不受欢迎人士或要求北京召回。言论回应菲防长称中国为地区麻烦制造者，中国使馆随后在社媒发出「你已上榜」等嘲讽帖。\n\n外交部 10 月 19 日召见景泉，称其言论具挑衅性；马科斯更倾向外交沟通而非驱逐。", "url": "https://x.com/i/trending/2112405151768100963", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T10:24:16.000Z"}, {"id": "2112161836116132305", "domain": "中国", "title_en": "China Restricts Tunnel Boring Machine Exports Targeting India's Projects", "title_zh": "中国限制全断面掘进机出口，印度基建承压", "hook_en": "India's metro and border tunnel builds now face new hurdles from China's export curbs on key machinery. Analysts see it as a direct hit amid ongoing tensions.", "hook_zh": "印度地铁与边境隧道建设因中国对关键机械出口设限再添障碍。分析认为在持续紧张背景下属直接冲击。", "summary_en": "China's commerce ministry imposed export licenses on full-face tunnel boring machines, cutterheads, and high-altitude shotcrete equipment, effective November 18, citing dual-use military risks. The controls target sensitive regions like India, which has relied on these imports for infrastructure despite dropping purchases from $18 million to $3 million yearly. India is countering with a $1.2 billion incentive for local production by firms like BEML and L&T, accelerating self-reliance in heavy machinery.", "summary_zh": "中国商务部对全断面隧道掘进机、刀盘及高原喷射混凝土设备实施出口许可，11 月 18 日起生效，理由为军民两用风险。管控针对印度等敏感地区；印度基建仍依赖此类进口，尽管年采购已从约 1800 万美元降至 300 万美元。印度正以约 12 亿美元激励推动 BEML、L&T 等本土生产，加速重型机械自力更生。", "body_en": "China Restricts Tunnel Boring Machine Exports Targeting India's Projects.\n\nIndia's metro and border tunnel builds now face new hurdles from China's export curbs on key machinery. Analysts see it as a direct hit amid ongoing tensions.\n\nChina's commerce ministry imposed export licenses on full-face tunnel boring machines, cutterheads, and high-altitude shotcrete equipment, effective November 18, citing dual-use military risks.\n\nThe controls target sensitive regions like India, which has relied on these imports for infrastructure despite dropping purchases from $18 million to $3 million yearly. India is countering with a $1.2 billion incentive for local production by firms like BEML and L&T, accelerating self-reliance in heavy machinery.", "body_zh": "中国限制全断面掘进机出口，印度基建承压。\n\n印度地铁与边境隧道建设因中国对关键机械出口设限再添障碍。分析认为在持续紧张背景下属直接冲击。\n\n中国商务部对全断面隧道掘进机、刀盘及高原喷射混凝土设备实施出口许可，11 月 18 日起生效，理由为军民两用风险。管控针对印度等敏感地区；印度基建仍依赖此类进口，尽管年采购已从约 1800 万美元降至 300 万美元。\n\n印度正以约 12 亿美元激励推动 BEML、L&T 等本土生产，加速重型机械自力更生。", "url": "https://x.com/i/trending/2112161836116132305", "category": "News", "topics": ["News", "Business & Finance"], "updated_at": "2026-10-20T19:24:59.000Z"}, {"id": "2112437946263474495", "domain": "中国", "title_en": "China Tracks U.S. Warship Near Disputed South China Sea Shoal", "title_zh": "中国跟踪靠近争议南沙礁盘的美舰", "hook_en": "Early Tuesday, a U.S. littoral combat ship sailed into waters China calls its own near Xianbin Jiao, prompting Beijing to send forces for close monitoring.", "hook_zh": "周二早间，一艘美军濒海战斗舰驶入中方所称仙宾礁附近水域，北京派出力量抵近监控。", "summary_en": "China's PLA Navy accused the USS Charleston of illegally entering waters adjacent to Xianbin Jiao in the Spratly Islands on October 20, claiming it threatens sovereignty and regional stability. The Philippines countered that the ship stayed in international waters, requiring no permission, and referenced a 2016 arbitral ruling against China's claims. This follows a recent vessel collision near the same shoal and comes amid overlapping territorial assertions by multiple nations in the South China Sea.", "summary_zh": "中国人民解放军海军指责美舰「查尔斯顿」号于 10 月 20 日非法进入南沙群岛仙宾礁邻近水域，称其威胁主权与地区稳定。菲律宾反驳称该舰处于国际水域、无需许可，并援引 2016 年仲裁裁决否定中方主张。事件发生在同礁附近近期船只擦碰之后，正值多国在南海存在重叠领土主张。", "body_en": "China Tracks U.S. Warship Near Disputed South China Sea Shoal.\n\nEarly Tuesday, a U.S. littoral combat ship sailed into waters China calls its own near Xianbin Jiao, prompting Beijing to send forces for close monitoring.\n\nChina's PLA Navy accused the USS Charleston of illegally entering waters adjacent to Xianbin Jiao in the Spratly Islands on October 20, claiming it threatens sovereignty and regional stability.\n\nThe Philippines countered that the ship stayed in international waters, requiring no permission, and referenced a 2016 arbitral ruling against China's claims. This follows a recent vessel collision near the same shoal and comes amid overlapping territorial assertions by multiple nations in the South China Sea.", "body_zh": "中国跟踪靠近争议南沙礁盘的美舰。\n\n周二早间，一艘美军濒海战斗舰驶入中方所称仙宾礁附近水域，北京派出力量抵近监控。\n\n中国人民解放军海军指责美舰「查尔斯顿」号于 10 月 20 日非法进入南沙群岛仙宾礁邻近水域，称其威胁主权与地区稳定。菲律宾反驳称该舰处于国际水域、无需许可，并援引 2016 年仲裁裁决否定中方主张。\n\n事件发生在同礁附近近期船只擦碰之后，正值多国在南海存在重叠领土主张。", "url": "https://x.com/i/trending/2112437946263474495", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-20T15:35:04.000Z"}, {"id": "2112529713906200727", "domain": "中国", "title_en": "Lincolnshire Mayor Signs Taiwan Partnership Amid Authority Questions", "title_zh": "林肯郡市长与台湾台南签署伙伴协议引权限争议", "hook_en": "Dame Andrea Jenkyns beamed from a video call, pen in hand, announcing a new deal with Taiwan's Tainan to boost trade and innovation. Online replies quickly pointed out mayors don't handle international agreements.", "hook_zh": "这位市长在视频连线中高调宣布与台南达成协议，网友很快指出市长无权签署国际条约。", "summary_en": "Greater Lincolnshire's mayor shared images of signing what she called a landmark trade agreement with Tainan, highlighting opportunities in agriculture, tech, and culture. Critics, including a former council leader, labeled it deluded and beyond her powers, clarifying it's actually a sister-city partnership for local exchanges. Taiwanese media confirmed the first such UK-Taiwan link, while users stressed precise wording to avoid misleading the public on formal trade deals.", "summary_zh": "大林肯郡市长分享与台南签署“里程碑贸易协议”的画面，强调农业、科技与文化机会。包括前议会领袖在内的批评者称其越权，澄清实为姐妹城市式地方交流。台湾媒体确认此为英台此类联系的首例，舆论呼吁措辞准确，避免被误解为正式贸易协定。", "body_en": "Lincolnshire Mayor Signs Taiwan Partnership Amid Authority Questions.\n\nDame Andrea Jenkyns beamed from a video call, pen in hand, announcing a new deal with Taiwan's Tainan to boost trade and innovation. Online replies quickly pointed out mayors don't handle international agreements.\n\nGreater Lincolnshire's mayor shared images of signing what she called a landmark trade agreement with Tainan, highlighting opportunities in agriculture, tech, and culture.\n\nCritics, including a former council leader, labeled it deluded and beyond her powers, clarifying it's actually a sister-city partnership for local exchanges. Taiwanese media confirmed the first such UK-Taiwan link, while users stressed precise wording to avoid misleading the public on formal trade deals.", "body_zh": "林肯郡市长与台湾台南签署伙伴协议引权限争议。\n\n这位市长在视频连线中高调宣布与台南达成协议，网友很快指出市长无权签署国际条约。\n\n大林肯郡市长分享与台南签署“里程碑贸易协议”的画面，强调农业、科技与文化机会。\n\n包括前议会领袖在内的批评者称其越权，澄清实为姐妹城市式地方交流。台湾媒体确认此为英台此类联系的首例，舆论呼吁措辞准确，避免被误解为正式贸易协定。", "url": "https://x.com/i/trending/2112529713906200727", "category": "News", "topics": ["News"], "updated_at": "2026-10-20T13:07:49.000Z"}, {"id": "2112336528253047290", "domain": "中国", "title_en": "Debate Heats Up Over Self-Driving Cars vs Manual Control", "title_zh": "自动驾驶与手动驾驶之争升温，Waymo 大订中国极氪车", "hook_en": "Fitness coach Jason Helmes shared his Boomer take: he loves gripping the wheel, blasting music, and decompressing on the road without screens.", "hook_zh": "有人留恋握方向盘放歌减压；也有人期待解放双手聊天、阅读或小憩。", "summary_en": "People are split on self-driving cars, with some cherishing the hands-on drive for its mental break, while others welcome the freedom for family chats, reading, or napping. Waymo is expanding its U.S. robotaxi fleet by ordering thousands of Chinese-made Zeekr vehicles from Geely, adding its sensors in Arizona for service in cities like Los Angeles and San Francisco—though lawmakers raise security and data concerns. Riders already praise perks like sipping coffee in a Tesla Cybercab or easing traffic stress, but many hold onto manual driving's simple joys, eyeing a mix for fun drives and routine trips.", "summary_zh": "公众对自动驾驶态度分化：有人珍惜亲自驾驶带来的心理喘息，有人欢迎腾出时间。Waymo 正扩大美国 Robotaxi 车队，向吉利旗下极氪订购数千辆中国制造车辆，并在亚利桑那加装传感器，服务洛杉矶、旧金山等城市——议员则提出安全与数据担忧。乘客已称赞在 Cybercab 里喝咖啡、减轻路怒等体验，但许多人仍想保留手动驾驶乐趣，设想「偶尔自驾、日常交给自动」的组合。", "body_en": "Debate Heats Up Over Self-Driving Cars vs Manual Control.\n\nFitness coach Jason Helmes shared his Boomer take: he loves gripping the wheel, blasting music, and decompressing on the road without screens.\n\nPeople are split on self-driving cars, with some cherishing the hands-on drive for its mental break, while others welcome the freedom for family chats, reading, or napping. Waymo is expanding its U.S.\n\nrobotaxi fleet by ordering thousands of Chinese-made Zeekr vehicles from Geely, adding its sensors in Arizona for service in cities like Los Angeles and San Francisco—though lawmakers raise security and data concerns. Riders already praise perks like sipping coffee in a Tesla Cybercab or easing traffic stress, but many hold onto manual driving's simple joys, eyeing a mix for fun drives and routine trips.", "body_zh": "自动驾驶与手动驾驶之争升温，Waymo 大订中国极氪车。\n\n有人留恋握方向盘放歌减压；也有人期待解放双手聊天、阅读或小憩。\n\n公众对自动驾驶态度分化：有人珍惜亲自驾驶带来的心理喘息，有人欢迎腾出时间。\n\nWaymo 正扩大美国 Robotaxi 车队，向吉利旗下极氪订购数千辆中国制造车辆，并在亚利桑那加装传感器，服务洛杉矶、旧金山等城市——议员则提出安全与数据担忧。乘客已称赞在 Cybercab 里喝咖啡、减轻路怒等体验，但许多人仍想保留手动驾驶乐趣，设想「偶尔自驾、日常交给自动」的组合。", "url": "https://x.com/i/trending/2112336528253047290", "category": "News", "topics": ["Technology", "Robotics"], "updated_at": "2026-10-20T00:20:46.000Z"}, {"id": "2112741572102242464", "domain": "中国", "title_en": "Japan's September Trade Deficit Widens to ¥536.6 Billion", "title_zh": "日本 9 月贸易逆差扩大至 5366 亿日元", "hook_en": "Japan's trade numbers landed with a surprise: a deficit far bigger than expected, even as exports kept climbing on chip and auto demand.", "hook_zh": "日本贸易数据出人意料：逆差远超预期，即便出口仍受芯片与汽车需求支撑继续增长。", "summary_en": "Japan posted a ¥536.6 billion ($3.39 billion) trade deficit in September, beating forecasts of ¥181 billion and marking the fifth straight month in the red. Exports rose 16.7% year-on-year—the 13th month of growth—driven by AI semiconductors and cars, with U.S. shipments up 22.9% and Asia up 17.5%, though below the 20-21% expected. Imports grew 18.9%, also under projections, signaling moderating expansion ahead of the Bank of Japan's policy meeting.", "summary_zh": "日本 9 月贸易逆差达 5366 亿日元（约 33.9 亿美元），远高于预估的 1810 亿日元，连续第五个月赤字。出口同比增长 16.7%，连续第 13 个月扩张，主因 AI 半导体与汽车；对美出口增 22.9%，对亚洲增 17.5%，但仍低于 20%–21% 的预期。进口增 18.9%，同样低于预估，显示扩张势头有所放缓，市场正关注日本央行政策会议。", "body_en": "Japan's September Trade Deficit Widens to ¥536.6 Billion.\n\nJapan's trade numbers landed with a surprise: a deficit far bigger than expected, even as exports kept climbing on chip and auto demand.\n\nJapan posted a ¥536.6 billion ($3.39 billion) trade deficit in September, beating forecasts of ¥181 billion and marking the fifth straight month in the red. Exports rose 16.7% year-on-year—the 13th month of growth—driven by AI semiconductors and cars, with U.S.\n\nshipments up 22.9% and Asia up 17.5%, though below the 20-21% expected. Imports grew 18.9%, also under projections, signaling moderating expansion ahead of the Bank of Japan's policy meeting.", "body_zh": "日本 9 月贸易逆差扩大至 5366 亿日元。\n\n日本贸易数据出人意料：逆差远超预期，即便出口仍受芯片与汽车需求支撑继续增长。\n\n日本 9 月贸易逆差达 5366 亿日元（约 33.9 亿美元），远高于预估的 1810 亿日元，连续第五个月赤字。\n\n出口同比增长 16.7%，连续第 13 个月扩张，主因 AI 半导体与汽车；对美出口增 22.9%，对亚洲增 17.5%，但仍低于 20%–21% 的预期。进口增 18.9%，同样低于预估，显示扩张势头有所放缓，市场正关注日本央行政策会议。", "url": "https://x.com/i/trending/2112741572102242464", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T03:08:30.000Z"}, {"id": "2112538623471964597", "domain": "中国", "title_en": "USDA Confirms Major Soybean Export Sale to China", "title_zh": "美农部确认对华大豆大单出口", "hook_en": "Farmers and traders perked up Tuesday when the USDA announced a hefty private sale of U.S. soybeans to China—the first real sign of renewed buying after quiet months.", "hook_zh": "沉寂数月后，美国农业部公布一笔可观的对华民间大豆销售，农户与交易商视为回暖信号。", "summary_en": "Private exporters reported selling 612,000 metric tons of American soybeans to China for the 2026/27 marketing year, one of the largest single-day deals lately. Chinese customs data showed the first U.S. soybean arrivals in September at 360,878 tons, up from zero a year ago, though total imports fell 8% to 11.88 million tons with Brazil supplying most at 10.7 million. For January through September, U.S. exports to China dropped 34% year-over-year to 11.06 million tons, while Brazil's climbed 3.4% to 65.84 million—yet recent data points to U.S. rebounding amid improving trade conditions.", "summary_zh": "民间出口商报告向中国售出 61.2 万吨 2026/27 市场年度美国大豆，为近期较大单日成交之一。中国海关显示 9 月首次到港美国大豆 360878 吨（去年同期为零），但总进口仍降 8% 至 1188 万吨，巴西供应约 1070 万吨居首。1–9 月美豆对华出口同比降 34% 至 1106 万吨，巴西则增 3.4% 至 6584 万吨；近期数据则显示美方在贸易环境改善下有所回升。", "body_en": "USDA Confirms Major Soybean Export Sale to China.\n\nFarmers and traders perked up Tuesday when the USDA announced a hefty private sale of U.S. soybeans to China—the first real sign of renewed buying after quiet months.\n\nPrivate exporters reported selling 612,000 metric tons of American soybeans to China for the 2026/27 marketing year, one of the largest single-day deals lately. Chinese customs data showed the first U.S. soybean arrivals in September at 360,878 tons, up from zero a year ago, though total imports fell 8% to 11.88 million tons with Brazil supplying most at 10.7 million.\n\nFor January through September, U.S. exports to China dropped 34% year-over-year to 11.06 million tons, while Brazil's climbed 3.4% to 65.84 million—yet recent data points to U.S. rebounding amid improving trade conditions.", "body_zh": "美农部确认对华大豆大单出口。\n\n沉寂数月后，美国农业部公布一笔可观的对华民间大豆销售，农户与交易商视为回暖信号。\n\n民间出口商报告向中国售出 61.2 万吨 2026/27 市场年度美国大豆，为近期较大单日成交之一。\n\n中国海关显示 9 月首次到港美国大豆 360878 吨（去年同期为零），但总进口仍降 8% 至 1188 万吨，巴西供应约 1070 万吨居首。1–9 月美豆对华出口同比降 34% 至 1106 万吨，巴西则增 3.4% 至 6584 万吨；近期数据则显示美方在贸易环境改善下有所回升。", "url": "https://x.com/i/trending/2112538623471964597", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T13:42:34.000Z"}, {"id": "2112101207397601450", "domain": "国际", "title_en": "Trump Administration Delays Patriot Missiles for Ukraine Amid Russian Attacks", "title_zh": "欧洲已付款的爱国者导弹，美方迟迟未交乌克兰", "hook_en": "As Russian missiles pound Ukrainian cities, President Zelenskyy pleads for urgent U.S. approval on Patriot interceptors that allies have already paid for and are ready to ship.", "hook_zh": "乌克兰面临弹道导弹打击，爱国者拦截弹告急，而欧洲盟友已为增援付款。", "summary_en": "Ukrainian officials report critically low Patriot interceptor stocks, vital for shielding civilians from Russian ballistic missiles and drones, while European partners await U.S. sign-off on transfers of the American-made weapons. Zelenskyy appealed directly to U.S. leaders for the missiles, early warning intelligence, and restored Starlink services, describing talks with Secretary Rubio as constructive with follow-up planned. Critics like Rep. Mike Levin and Sen. Thom Tillis blast the delays as a betrayal that weakens Ukraine's defenses, while administration officials call obstruction claims outrageous and attribute issues to technical matters. Both sides stress pursuing diplomacy to end the war, with Zelenskyy open to trilateral talks.", "summary_zh": "尽管欧洲已付款，爱国者导弹移交仍待国防部长签字；泽连斯基在俄军袭击背景下向鲁比奥国务卿强调紧迫性。", "body_en": "Trump Administration Delays Patriot Missiles for Ukraine Amid Russian Attacks.\n\nAs Russian missiles pound Ukrainian cities, President Zelenskyy pleads for urgent U.S. approval on Patriot interceptors that allies have already paid for and are ready to ship.\n\nUkrainian officials report critically low Patriot interceptor stocks, vital for shielding civilians from Russian ballistic missiles and drones, while European partners await U.S. sign-off on transfers of the American-made weapons. Zelenskyy appealed directly to U.S. leaders for the missiles, early warning intelligence, and restored Starlink services, describing talks with Secretary Rubio as constructive with follow-up planned.\n\nCritics like Rep. Mike Levin and Sen. Thom Tillis blast the delays as a betrayal that weakens Ukraine's defenses, while administration officials call obstruction claims outrageous and attribute issues to technical matters. Both sides stress pursuing diplomacy to end the war, with Zelenskyy open to trilateral talks.", "body_zh": "欧洲已付款的爱国者导弹，美方迟迟未交乌克兰。\n\n乌克兰面临弹道导弹打击，爱国者拦截弹告急，而欧洲盟友已为增援付款。\n\n尽管欧洲已付款，爱国者导弹移交仍待国防部长签字；泽连斯基在俄军袭击背景下向鲁比奥国务卿强调紧迫性。", "url": "https://x.com/i/trending/2112101207397601450", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T07:28:55.000Z"}, {"id": "2112296384745631848", "domain": "国际", "title_en": "France Protests Spark Debate on Russian Interference Claims", "title_zh": "法国抗议潮引发「俄方干涉」说法之争", "hook_en": "Hundreds of thousands marched in France on October 17 over soaring living costs and cuts to education, only for the unrest to fuel sharp online arguments about hidden foreign hands.", "hook_zh": "10 月 17 日法国数十万人抗议生活成本飙升与教育削减，骚乱随后在网上激起「是否有外部黑手」的激烈争论。", "summary_en": "Demonstrations drew around 550,000 people nationwide, including 110,000 in Paris, starting with student demands before expanding to unions and turning violent with looting, arson, and over 1,200 arrests. Estonian MP Marko Mihkelson claimed Russia benefits from the chaos in France and Italy as part of a shadow war, while a satirical post by Wolfgang Richter mocked the idea of Putin paying protesters and called for speech curbs. Officials insist the unrest stems from domestic economic woes, with no evidence of Russian or Iranian organization, though both nations have amplified the violence in propaganda; online views split between those seeing Moscow's gain and critics dismissing it as scapegoating real policy failures.", "summary_zh": "全国约 55 万人上街，巴黎约 11 万，由学生诉求扩至工会，并演变为抢劫、纵火与逾 1200 人被捕。爱沙尼亚议员 Marko Mihkelson 称俄从法、意乱局获益，属影子战争；Wolfgang Richter 的讽刺帖则嘲讽「普京出钱抗议」说法并呼吁限制言论。官方坚持动因是国内经济困境，并无俄、伊组织证据，尽管两国宣传放大了暴力画面；网上有人强调莫斯科受益，也有人批评这是在替真正的政策失败找替罪羊。", "body_en": "France Protests Spark Debate on Russian Interference Claims.\n\nHundreds of thousands marched in France on October 17 over soaring living costs and cuts to education, only for the unrest to fuel sharp online arguments about hidden foreign hands.\n\nDemonstrations drew around 550,000 people nationwide, including 110,000 in Paris, starting with student demands before expanding to unions and turning violent with looting, arson, and over 1,200 arrests.\n\nEstonian MP Marko Mihkelson claimed Russia benefits from the chaos in France and Italy as part of a shadow war, while a satirical post by Wolfgang Richter mocked the idea of Putin paying protesters and called for speech curbs. Officials insist the unrest stems from domestic economic woes, with no evidence of Russian or Iranian organization, though both nations have amplified the violence in propaganda; online views split between those seeing Moscow's gain and critics dismissing it as scapegoating real policy failures.", "body_zh": "法国抗议潮引发「俄方干涉」说法之争。\n\n10 月 17 日法国数十万人抗议生活成本飙升与教育削减，骚乱随后在网上激起「是否有外部黑手」的激烈争论。\n\n全国约 55 万人上街，巴黎约 11 万，由学生诉求扩至工会，并演变为抢劫、纵火与逾 1200 人被捕。爱沙尼亚议员 Marko Mihkelson 称俄从法、意乱局获益，属影子战争；Wolfgang Richter 的讽刺帖则嘲讽「普京出钱抗议」说法并呼吁限制言论。\n\n官方坚持动因是国内经济困境，并无俄、伊组织证据，尽管两国宣传放大了暴力画面；网上有人强调莫斯科受益，也有人批评这是在替真正的政策失败找替罪羊。", "url": "https://x.com/i/trending/2112296384745631848", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T14:03:55.000Z"}, {"id": "2112460842902151394", "domain": "国际", "title_en": "Lawmakers Back Ukraine Aid Amid Online Backlash from Trump Supporters", "title_zh": "两党议员力挺援乌，遭特朗普支持者网上猛烈抨击", "hook_en": "U.S. lawmakers from both parties rallied behind Zelensky on calls about sanctions waivers and restricted weapons access, only to face fierce online accusations of treason from Trump backers pushing for peace talks with Russia.", "hook_zh": "美国两党议员就制裁豁免与武器受限与泽连斯基通话力挺，却遭主张对俄和谈的特朗普支持者网上痛批为「叛国」。", "summary_en": "Rep. Brad Schneider, a Democrat, joined a bipartisan call where Zelensky raised alarms over waived U.S. sanctions on Russia and limits on Starlink and Patriot missiles, urging steady defense support. Rep. Brian Fitzpatrick, a Republican, plans his own talk with Zelensky on Starshield, sanctions, and aid, promising probes into any restrictions. Critics online branded the lawmakers traitors for prioritizing Ukraine over Trump's negotiation push, calling the country corrupt and demanding an America First end to involvement. The clash highlights deep divides over U.S. policy shifts like energy deals with Russia and Starlink curbs.", "summary_zh": "民主党众议员布拉德·施奈德参加两党通话，泽连斯基对美豁免对俄制裁及限制星链、爱国者导弹表示警惕，敦促稳定防务支持。共和党众议员布赖恩·菲茨帕特里克计划另与泽连斯基谈星盾、制裁与援助，并承诺调查任何限制。网上批评者称议员「叛国」、优先乌克兰而非特朗普谈判路线，指乌腐败并要求「美国优先」结束介入。争执凸显能源交易、星链限制等政策转向下的深刻分裂。", "body_en": "Lawmakers Back Ukraine Aid Amid Online Backlash from Trump Supporters.\n\nU.S. lawmakers from both parties rallied behind Zelensky on calls about sanctions waivers and restricted weapons access, only to face fierce online accusations of treason from Trump backers pushing for peace talks with Russia.\n\nRep. Brad Schneider, a Democrat, joined a bipartisan call where Zelensky raised alarms over waived U.S. sanctions on Russia and limits on Starlink and Patriot missiles, urging steady defense support. Rep.\n\nBrian Fitzpatrick, a Republican, plans his own talk with Zelensky on Starshield, sanctions, and aid, promising probes into any restrictions. Critics online branded the lawmakers traitors for prioritizing Ukraine over Trump's negotiation push, calling the country corrupt and demanding an America First end to involvement. The clash highlights deep divides over U.S. policy shifts like energy deals with Russia and Starlink curbs.", "body_zh": "两党议员力挺援乌，遭特朗普支持者网上猛烈抨击。\n\n美国两党议员就制裁豁免与武器受限与泽连斯基通话力挺，却遭主张对俄和谈的特朗普支持者网上痛批为「叛国」。\n\n民主党众议员布拉德·施奈德参加两党通话，泽连斯基对美豁免对俄制裁及限制星链、爱国者导弹表示警惕，敦促稳定防务支持。共和党众议员布赖恩·菲茨帕特里克计划另与泽连斯基谈星盾、制裁与援助，并承诺调查任何限制。\n\n网上批评者称议员「叛国」、优先乌克兰而非特朗普谈判路线，指乌腐败并要求「美国优先」结束介入。争执凸显能源交易、星链限制等政策转向下的深刻分裂。", "url": "https://x.com/i/trending/2112460842902151394", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T08:32:59.000Z"}, {"id": "2112442700796690870", "domain": "国际", "title_en": "Online Debate Heats Up Over Ukraine's Status as U.S. Ally", "title_zh": "乌克兰是否算美国「盟友」引网络激辩", "hook_en": "Congresswoman Madeleine Dean called Ukraine a key ally amid Washington's cooling ties with Kyiv. Conservative voices fired back, questioning any formal bond.", "hook_zh": "众议员玛德琳·迪恩称乌克兰是关键盟友，恰逢华盛顿与基辅关系降温；保守派则追问有无正式同盟关系。", "summary_en": "The argument centers on whether Ukraine counts as a U.S. ally, with no mutual defense treaty, NATO membership, or Major Non-NATO Ally designation. Posts clash over history too: Ukraine inherited Soviet nukes in 1991, gave them up under the 1994 Budapest Memorandum for security promises from the U.S., U.K., and Russia—but those pledges didn't stop invasions in 2014 or 2022. Recent tensions spiked in mid-October 2026 when President Trump criticized Zelenskyy, eased Russia sanctions, and pushed for peace, cooling U.S.-Ukraine relations and fueling views of Ukraine as either a vital partner or a non-ally in a pricey proxy war.", "summary_zh": "争论核心在于乌克兰是否算美国盟友：双方并无共同防御条约、北约成员身份或「主要非北约盟友」认定。历史也成焦点：乌克兰 1991 年继承苏联核武，却依 1994 年《布达佩斯备忘录》放弃核武，换取美英俄安全承诺，但未能阻止 2014 与 2022 年入侵。2026 年 10 月中旬特朗普批评泽连斯基、放松对俄制裁并推动和谈，美乌关系降温，网络上「关键伙伴」与「昂贵代理人战争中的非盟友」两种叙事激烈对撞。", "body_en": "Online Debate Heats Up Over Ukraine's Status as U.S. Ally.\n\nCongresswoman Madeleine Dean called Ukraine a key ally amid Washington's cooling ties with Kyiv. Conservative voices fired back, questioning any formal bond.\n\nThe argument centers on whether Ukraine counts as a U.S. ally, with no mutual defense treaty, NATO membership, or Major Non-NATO Ally designation.\n\nPosts clash over history too: Ukraine inherited Soviet nukes in 1991, gave them up under the 1994 Budapest Memorandum for security promises from the U.S., U.K., and Russia—but those pledges didn't stop invasions in 2014 or 2022. Recent tensions spiked in mid-October 2026 when President Trump criticized Zelenskyy, eased Russia sanctions, and pushed for peace, cooling U.S.-Ukraine relations and fueling views of Ukraine as either a vital partner or a non-ally in a pricey proxy war.", "body_zh": "乌克兰是否算美国「盟友」引网络激辩。\n\n众议员玛德琳·迪恩称乌克兰是关键盟友，恰逢华盛顿与基辅关系降温；保守派则追问有无正式同盟关系。\n\n争论核心在于乌克兰是否算美国盟友：双方并无共同防御条约、北约成员身份或「主要非北约盟友」认定。\n\n历史也成焦点：乌克兰 1991 年继承苏联核武，却依 1994 年《布达佩斯备忘录》放弃核武，换取美英俄安全承诺，但未能阻止 2014 与 2022 年入侵。2026 年 10 月中旬特朗普批评泽连斯基、放松对俄制裁并推动和谈，美乌关系降温，网络上「关键伙伴」与「昂贵代理人战争中的非盟友」两种叙事激烈对撞。", "url": "https://x.com/i/trending/2112442700796690870", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T20:56:58.000Z"}, {"id": "2112533926879125584", "domain": "国际", "title_en": "Zelenskyy Warns of Russia's Propaganda Push Across Europe", "title_zh": "泽连斯基警告俄罗斯在欧洲的宣传攻势", "hook_en": "In a candid interview, Ukraine's president laid out Russia's quiet strategy to sway opinions through media and social platforms.", "hook_zh": "乌克兰总统在采访中勾勒俄罗斯通过媒体与社交平台悄然影响舆论的策略。", "summary_en": "Volodymyr Zelenskyy described Russia's decades-long hybrid war as heavily funded efforts targeting media, internet, and social platforms in countries like Italy, France, Britain, and Germany. He highlighted exploitation of issues such as migration, religion, far-right movements, and gender to influence public opinion. Social media responses pointed to Britain's £25 billion in aid to Ukraine—including £16 billion in weapons—and framed dissent as legitimate debate over spending rather than manipulation. The exchange underscores tensions between hybrid threat warnings and fatigue over war aid costs.", "summary_zh": "泽连斯基称俄罗斯数十年混合战投入大量资金，针对意大利、法国、英国、德国等国的媒体、互联网与社交平台，并利用移民、宗教、极右与性别等议题影响民意。社交平台回应中有人指出英国对乌援助约 250 亿英镑（含约 160 亿武器），并将异议视为对开支的正当辩论而非被操纵。交流凸显混合威胁警示与战争援助疲劳之间的张力。", "body_en": "Zelenskyy Warns of Russia's Propaganda Push Across Europe.\n\nIn a candid interview, Ukraine's president laid out Russia's quiet strategy to sway opinions through media and social platforms.\n\nVolodymyr Zelenskyy described Russia's decades-long hybrid war as heavily funded efforts targeting media, internet, and social platforms in countries like Italy, France, Britain, and Germany. He highlighted exploitation of issues such as migration, religion, far-right movements, and gender to influence public opinion.\n\nSocial media responses pointed to Britain's £25 billion in aid to Ukraine—including £16 billion in weapons—and framed dissent as legitimate debate over spending rather than manipulation. The exchange underscores tensions between hybrid threat warnings and fatigue over war aid costs.", "body_zh": "泽连斯基警告俄罗斯在欧洲的宣传攻势。\n\n乌克兰总统在采访中勾勒俄罗斯通过媒体与社交平台悄然影响舆论的策略。\n\n泽连斯基称俄罗斯数十年混合战投入大量资金，针对意大利、法国、英国、德国等国的媒体、互联网与社交平台，并利用移民、宗教、极右与性别等议题影响民意。\n\n社交平台回应中有人指出英国对乌援助约 250 亿英镑（含约 160 亿武器），并将异议视为对开支的正当辩论而非被操纵。交流凸显混合威胁警示与战争援助疲劳之间的张力。", "url": "https://x.com/i/trending/2112533926879125584", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-20T13:26:36.000Z"}, {"id": "2112536417826205770", "domain": "国际", "title_en": "EU Unveils New Arctic Strategy Prioritizing Security", "title_zh": "欧盟公布新北极战略，安全置于核心", "hook_en": "Ursula von der Leyen called the Arctic where geopolitics' tectonic plates collide, urging Europe to bolster its stance amid rising rivalries.", "hook_zh": "冯德莱恩称北极是地缘「板块碰撞」之地，呼吁欧洲在竞争加剧中站稳脚跟。", "summary_en": "The European Union adopted an updated Arctic Strategy on Tuesday, placing security at its heart to counter growing competition from Russia and China as melting ice reveals new shipping routes and resources. Key steps include enhanced satellite surveillance, an Arctic Cable Hub for undersea protection, more icebreakers, extreme-condition technologies, and improved military mobility, alongside priorities like climate action, prosperity, and support for local communities. Leaders like Kaja Kallas warned against letting rivals dominate, while Russia dismissed it as neocolonial and Finland's prime minister praised contributions in icebreaking and cables. The plan seeks partnerships with Canada, Norway, the UK, and others for a safer High North.", "summary_zh": "欧盟周二通过更新版北极战略，以安全为核心，应对俄中竞争升温以及融冰带来的新航道与资源。举措包括加强卫星监视、建设海底光缆枢纽、增加破冰船与极端环境技术、提升军事机动，并兼顾气候、繁荣与本地社区。卡拉斯等领导人警告勿让对手主导；俄方斥为新殖民，芬兰总理则肯定破冰与光缆贡献。计划寻求与加拿大、挪威、英国等合作，守护高北安全。", "body_en": "EU Unveils New Arctic Strategy Prioritizing Security.\n\nUrsula von der Leyen called the Arctic where geopolitics' tectonic plates collide, urging Europe to bolster its stance amid rising rivalries.\n\nThe European Union adopted an updated Arctic Strategy on Tuesday, placing security at its heart to counter growing competition from Russia and China as melting ice reveals new shipping routes and resources. Key steps include enhanced satellite surveillance, an Arctic Cable Hub for undersea protection, more icebreakers, extreme-condition technologies, and improved military mobility, alongside priorities like climate action, prosperity, and support for local communities.\n\nLeaders like Kaja Kallas warned against letting rivals dominate, while Russia dismissed it as neocolonial and Finland's prime minister praised contributions in icebreaking and cables. The plan seeks partnerships with Canada, Norway, the UK, and others for a safer High North.", "body_zh": "欧盟公布新北极战略，安全置于核心。\n\n冯德莱恩称北极是地缘「板块碰撞」之地，呼吁欧洲在竞争加剧中站稳脚跟。\n\n欧盟周二通过更新版北极战略，以安全为核心，应对俄中竞争升温以及融冰带来的新航道与资源。举措包括加强卫星监视、建设海底光缆枢纽、增加破冰船与极端环境技术、提升军事机动，并兼顾气候、繁荣与本地社区。\n\n卡拉斯等领导人警告勿让对手主导；俄方斥为新殖民，芬兰总理则肯定破冰与光缆贡献。计划寻求与加拿大、挪威、英国等合作，守护高北安全。", "url": "https://x.com/i/trending/2112536417826205770", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-20T22:00:47.000Z"}, {"id": "2112813401197998100", "domain": "国际", "title_en": "Zelenskyy: Ukraine Losing People and Time, Not the War", "title_zh": "泽连斯基缅怀战争中逝去的生命与童年", "hook_en": "Ukrainian President Volodymyr Zelenskyy spoke from the heart in Oslo, mourning how Russian attacks are robbing children of their childhood and all Ukrainians of normal lives.", "hook_zh": "在奥斯陆，泽连斯基动情谈到孩子被夺走的童年，以及俄军袭击下每天消逝的生命。", "summary_en": "During a joint press conference on October 20 with U.S., Norwegian, and Finnish leaders, Zelenskyy said Ukraine holds strong on the battlefield but suffers heavy losses in people and time from ongoing Russian strikes. He backed an energy ceasefire that Russia ignored and called for quick peace through American and European support, plus security guarantees and possible trilateral talks. His candid words about the human cost drew praise for Ukrainian resilience alongside sharp criticism over prolonging the fight, highlighting deep divides on the war's path forward.", "summary_zh": "10 月 20 日，乌克兰总统泽连斯基在会见美特使史蒂夫·威特科夫、挪威首相斯特勒与芬兰总统斯图布后举行记者会。他强调乌克兰并未输掉战争，但指出生命、时间与正常童年代价沉重，呼吁尽快结束冲突。泽连斯基赞扬士兵坚强，并希望美欧伙伴协助迈向和谈与停火。反应不一：有人强烈声援，也有人因人道代价催促谈判。", "body_en": "Zelenskyy Mourns Lives and Childhood Lost in Ukraine War.\n\nIn Oslo, Zelenskyy spoke from the heart about children robbed of their childhood and lives slipping away daily from Russian attacks.\n\nOn October 20, Ukrainian President Volodymyr Zelenskyy addressed a press conference after meetings with U.S. envoy Steve Witkoff, Norwegian Prime Minister Jonas Gahr Støre, and Finnish President Alexander Stubb.\n\nHe affirmed Ukraine is not losing the war but highlighted the heavy toll of lost lives, time, and normal childhoods, urging a quick end to the conflict. Zelenskyy praised his soldiers' strength and expressed hope for help from American and European partners toward peace talks and ceasefires. Reactions varied, with some voicing strong support and others calling for negotiations amid the mounting human cost.", "body_zh": "泽连斯基缅怀战争中逝去的生命与童年。\n\n在奥斯陆，泽连斯基动情谈到孩子被夺走的童年，以及俄军袭击下每天消逝的生命。\n\n10 月 20 日，乌克兰总统泽连斯基在会见美特使史蒂夫·威特科夫、挪威首相斯特勒与芬兰总统斯图布后举行记者会。他强调乌克兰并未输掉战争，但指出生命、时间与正常童年代价沉重，呼吁尽快结束冲突。\n\n泽连斯基赞扬士兵坚强，并希望美欧伙伴协助迈向和谈与停火。反应不一：有人强烈声援，也有人因人道代价催促谈判。", "url": "https://x.com/i/trending/2112813401197998100", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T10:24:27.000Z"}, {"id": "2112663042865639469", "domain": "国际", "title_en": "Turkey, Qatar, Pakistan, Indonesia Sign Defense Industry Pact in Doha", "title_zh": "土、卡、巴、印尼在多哈签署防务工业合作备忘录", "hook_en": "In Doha on Wednesday, defense ministers from four nations gathered to ink a deal that turns bilateral projects into a shared future for weapons and training.", "hook_zh": "四国防长在多哈签约，把双边项目推进为武器研发与训练的共享框架。", "summary_en": "The quadrilateral Memorandum of Understanding, known as the Badr MoU, sets up joint weapons development, technology sharing, and military training among Turkey, Qatar, Pakistan, and Indonesia. Turkish Defense Minister Yaşar Güler joined his counterparts at the signing, building on existing ties like Bayraktar TB2 drones for Qatar, MILGEM corvettes for Pakistan, and the Kaplan MT tank with Indonesia. Officials see it as a push for deeper collaboration in manufacturing and engineering, distinct from broader defense pacts like the recent Mecca agreement with Saudi Arabia. The move highlights Turkey's rising arms exports, topping $10 billion in 2025, amid efforts for self-reliant defense production.", "summary_zh": "名为 Badr 的四方谅解备忘录，确立土耳其、卡塔尔、巴基斯坦与印度尼西亚在联合武器研发、技术共享与军事训练上的合作。土防长 Yaşar Güler 与各方同席签署，延续向卡塔尔出口 Bayraktar TB2、向巴基斯坦提供 MILGEM 护卫舰、与印尼合作 Kaplan MT 坦克等既有纽带。官员视之为制造与工程深化合作，有别于近期与沙特的麦加防务安排。土耳其 2025 年军贸出口已超 100 亿美元，正推动自主产能。", "body_en": "Turkey, Qatar, Pakistan, Indonesia Sign Defense Industry Pact in Doha.\n\nIn Doha on Wednesday, defense ministers from four nations gathered to ink a deal that turns bilateral projects into a shared future for weapons and training.\n\nThe quadrilateral Memorandum of Understanding, known as the Badr MoU, sets up joint weapons development, technology sharing, and military training among Turkey, Qatar, Pakistan, and Indonesia. Turkish Defense Minister Yaşar Güler joined his counterparts at the signing, building on existing ties like Bayraktar TB2 drones for Qatar, MILGEM corvettes for Pakistan, and the Kaplan MT tank with Indonesia.\n\nOfficials see it as a push for deeper collaboration in manufacturing and engineering, distinct from broader defense pacts like the recent Mecca agreement with Saudi Arabia. The move highlights Turkey's rising arms exports, topping $10 billion in 2025, amid efforts for self-reliant defense production.", "body_zh": "土、卡、巴、印尼在多哈签署防务工业合作备忘录。\n\n四国防长在多哈签约，把双边项目推进为武器研发与训练的共享框架。\n\n名为 Badr 的四方谅解备忘录，确立土耳其、卡塔尔、巴基斯坦与印度尼西亚在联合武器研发、技术共享与军事训练上的合作。土防长 Yaşar Güler 与各方同席签署，延续向卡塔尔出口 Bayraktar TB2、向巴基斯坦提供 MILGEM 护卫舰、与印尼合作 Kaplan MT 坦克等既有纽带。\n\n官员视之为制造与工程深化合作，有别于近期与沙特的麦加防务安排。土耳其 2025 年军贸出口已超 100 亿美元，正推动自主产能。", "url": "https://x.com/i/trending/2112663042865639469", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-21T11:29:30.000Z"}, {"id": "2112602589699436902", "domain": "国际", "title_en": "Trump Team Proposes U.S. Control of Frozen Russian Assets, Europe Rejects", "title_zh": "特朗普团队提议美方掌控冻结俄资，欧洲拒绝", "hook_en": "In Miami talks, Steve Witkoff and Jared Kushner pitched shifting Europe's frozen Russian assets to a U.S.-run fund to lure peace negotiations on Ukraine. European delegates shut it down fast.", "hook_zh": "迈阿密会谈中，威特科夫与库什纳提议把欧洲冻结的俄资产转入美方基金以换和谈，欧方迅速否决。", "summary_en": "The Trump administration suggested moving part of the €260 billion in immobilized Russian assets—mostly held in the EU, like €202 billion at Belgium's Euroclear—into a Washington-controlled vehicle to restart Ukraine talks with officials from Ukraine, Britain, France, Germany, the EU, and NATO. European representatives firmly opposed giving up control or returning funds to Moscow, with German Chancellor Friedrich Merz insisting the assets stay frozen in Europe. The plan drew surprise in Kyiv and sharp online backlash, with critics calling it outrageous and urging direct aid to Ukraine instead. It underscores growing U.S.-Europe divides on using the assets for leverage versus incentives.", "summary_zh": "特朗普政府建议将约 2600 亿欧元被冻结俄资产（多数在欧盟，比利时 Euroclear 约持 2020 亿）的一部分转入华盛顿主导载体，以重启与乌克兰、英法德、欧盟及北约官员的和谈。欧洲代表坚决反对交出控制权或向莫斯科返还资金，德国总理默茨强调资产应继续冻结在欧洲。基辅方面感意外，网上批评声浪大，呼吁直接援助乌克兰。事件凸显美欧在「杠杆」与「激励」用法上的分歧。", "body_en": "Trump Team Proposes U.S. Control of Frozen Russian Assets, Europe Rejects.\n\nIn Miami talks, Steve Witkoff and Jared Kushner pitched shifting Europe's frozen Russian assets to a U.S.-run fund to lure peace negotiations on Ukraine. European delegates shut it down fast.\n\nThe Trump administration suggested moving part of the €260 billion in immobilized Russian assets—mostly held in the EU, like €202 billion at Belgium's Euroclear—into a Washington-controlled vehicle to restart Ukraine talks with officials from Ukraine, Britain, France, Germany, the EU, and NATO. European representatives firmly opposed giving up control or returning funds to Moscow, with German Chancellor Friedrich Merz insisting the assets stay frozen in Europe.\n\nThe plan drew surprise in Kyiv and sharp online backlash, with critics calling it outrageous and urging direct aid to Ukraine instead. It underscores growing U.S.-Europe divides on using the assets for leverage versus incentives.", "body_zh": "特朗普团队提议美方掌控冻结俄资，欧洲拒绝。\n\n迈阿密会谈中，威特科夫与库什纳提议把欧洲冻结的俄资产转入美方基金以换和谈，欧方迅速否决。\n\n特朗普政府建议将约 2600 亿欧元被冻结俄资产（多数在欧盟，比利时 Euroclear 约持 2020 亿）的一部分转入华盛顿主导载体，以重启与乌克兰、英法德、欧盟及北约官员的和谈。欧洲代表坚决反对交出控制权或向莫斯科返还资金，德国总理默茨强调资产应继续冻结在欧洲。\n\n基辅方面感意外，网上批评声浪大，呼吁直接援助乌克兰。事件凸显美欧在「杠杆」与「激励」用法上的分歧。", "url": "https://x.com/i/trending/2112602589699436902", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T00:39:08.000Z"}, {"id": "2112558002708648142", "domain": "国际", "title_en": "Zelensky's 2025 Warning on Russia Resurfaces Amid Skepticism", "title_zh": "泽连斯基 2025 年警告美若退出北约俄将占欧洲，言论再被热议", "hook_en": "A 2025 clip of Ukrainian President Volodymyr Zelensky warning that a U.S. NATO exit means certain Russian occupation of Europe has people online pushing back hard.", "hook_zh": "一段 2025 年采访片段再度流传：泽连斯基称美国退出北约则俄占欧洲「板上钉钉」，网上质疑声强烈。", "summary_en": "In a February 16, 2025, NBC Meet the Press interview, Zelensky told host Kristen Welker that European NATO forces lack enough brigades to match Russia's military, predicting a 100 percent risk of occupation starting with smaller ex-Soviet NATO states if the U.S. withdraws. The resurfaced excerpt drew skeptical reactions, with comments calling it 'bullshit,' pointing to supposed contradictions about Russia's struggles in Ukraine, and labeling it hyperbolic or a plea for more aid. The discussion highlights ongoing divides over Russian threats, NATO roles, and Western support for Ukraine as debates on assistance levels persist.", "summary_zh": "在 2025 年 2 月 16 日 NBC《Meet the Press》采访中，泽连斯基对主持人称欧洲北约兵力不足以匹敌俄军，若美国撤出，从前苏联加盟的较小北约国家起被占领的风险是「百分之百」。片段重火后评论两极，有人称「胡扯」，指出俄军在乌克兰受挫的矛盾，也有人视其为夸张或求援话术。讨论折射对俄威胁、北约角色与对乌援助力度的持续分歧。", "body_en": "Zelensky's 2025 Warning on Russia Resurfaces Amid Skepticism.\n\nA 2025 clip of Ukrainian President Volodymyr Zelensky warning that a U.S. NATO exit means certain Russian occupation of Europe has people online pushing back hard.\n\nIn a February 16, 2025, NBC Meet the Press interview, Zelensky told host Kristen Welker that European NATO forces lack enough brigades to match Russia's military, predicting a 100 percent risk of occupation starting with smaller ex-Soviet NATO states if the U.S. withdraws.\n\nThe resurfaced excerpt drew skeptical reactions, with comments calling it 'bullshit,' pointing to supposed contradictions about Russia's struggles in Ukraine, and labeling it hyperbolic or a plea for more aid. The discussion highlights ongoing divides over Russian threats, NATO roles, and Western support for Ukraine as debates on assistance levels persist.", "body_zh": "泽连斯基 2025 年警告美若退出北约俄将占欧洲，言论再被热议。\n\n一段 2025 年采访片段再度流传：泽连斯基称美国退出北约则俄占欧洲「板上钉钉」，网上质疑声强烈。\n\n在 2025 年 2 月 16 日 NBC《Meet the Press》采访中，泽连斯基对主持人称欧洲北约兵力不足以匹敌俄军，若美国撤出，从前苏联加盟的较小北约国家起被占领的风险是「百分之百」。\n\n片段重火后评论两极，有人称「胡扯」，指出俄军在乌克兰受挫的矛盾，也有人视其为夸张或求援话术。讨论折射对俄威胁、北约角色与对乌援助力度的持续分歧。", "url": "https://x.com/i/trending/2112558002708648142", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T17:59:26.000Z"}, {"id": "2112582275107852636", "domain": "国际", "title_en": "Iran Warns of Targeting Undersea Cables in Strait of Hormuz Amid U.S. Tensions", "title_zh": "伊朗警告或打击霍尔木兹海峡海底光缆，卡塔尔反驳", "hook_en": "Iran's Revolutionary Guard has singled out seven key undersea internet cables in the Strait of Hormuz as potential targets if war with the U.S. breaks out. Qatar quickly pushed back, warning that the real victims would be Gulf neighbors, including Iran itself.", "hook_zh": "伊斯兰革命卫队点名海峡七条关键海底互联网光缆为潜在打击目标；卡塔尔警告真正受害者将是海湾邻国乃至伊朗自身。", "summary_en": "The IRGC stated these cables carry vital internet and financial traffic for the region and beyond, declaring they 'will be Destroyed during the next War.' Qatar's Foreign Ministry urged Iran to reconsider, noting disruptions from cables, mines, or spills would harm desalination, navigation, fisheries, and marine resources most for local countries. Analysts say damage could disrupt banking, communications, and data across the Middle East, Asia, and Europe, though some alternative routes exist. The warnings underscore the strait's role as both an energy chokepoint and digital lifeline, with calls for diplomacy to de-escalate.", "summary_zh": "革命卫队称这些光缆承载区域内外关键互联网与金融流量，「下一场战争中将被摧毁」。卡塔尔外交部敦促伊朗三思，指出光缆、水雷或泄漏造成的中断，会对海水淡化、航运、渔业与海洋资源造成最大伤害，受害者首先是本地国家。分析认为冲击可波及中东、亚洲与欧洲的银行、通信与数据，尽管存在部分替代路由。警告凸显海峡既是能源咽喉也是数字生命线，各方呼吁以外交降温。", "body_en": "Iran Warns of Targeting Undersea Cables in Strait of Hormuz Amid U.S. Tensions.\n\nIran's Revolutionary Guard has singled out seven key undersea internet cables in the Strait of Hormuz as potential targets if war with the U.S. breaks out. Qatar quickly pushed back, warning that the real victims would be Gulf neighbors, including Iran itself.\n\nThe IRGC stated these cables carry vital internet and financial traffic for the region and beyond, declaring they 'will be Destroyed during the next War.' Qatar's Foreign Ministry urged Iran to reconsider, noting disruptions from cables, mines, or spills would harm desalination, navigation, fisheries, and marine resources most for local countries.\n\nAnalysts say damage could disrupt banking, communications, and data across the Middle East, Asia, and Europe, though some alternative routes exist. The warnings underscore the strait's role as both an energy chokepoint and digital lifeline, with calls for diplomacy to de-escalate.", "body_zh": "伊朗警告或打击霍尔木兹海峡海底光缆，卡塔尔反驳。\n\n伊斯兰革命卫队点名海峡七条关键海底互联网光缆为潜在打击目标；卡塔尔警告真正受害者将是海湾邻国乃至伊朗自身。\n\n革命卫队称这些光缆承载区域内外关键互联网与金融流量，「下一场战争中将被摧毁」。卡塔尔外交部敦促伊朗三思，指出光缆、水雷或泄漏造成的中断，会对海水淡化、航运、渔业与海洋资源造成最大伤害，受害者首先是本地国家。\n\n分析认为冲击可波及中东、亚洲与欧洲的银行、通信与数据，尽管存在部分替代路由。警告凸显海峡既是能源咽喉也是数字生命线，各方呼吁以外交降温。", "url": "https://x.com/i/trending/2112582275107852636", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T09:36:09.000Z"}, {"id": "2112444163392422181", "domain": "国际", "title_en": "Congress MP Manish Tewari Delivers India's UN Statement on Nuclear Disarmament", "title_zh": "国大党议员 Manish Tewari 代表印度在联大谈核裁军", "hook_en": "In a formal UN hall in New York, opposition MP Manish Tewari stood at India's desk, speaking for the nation on nuclear risks and restraint.", "hook_zh": "反对党议员站在印度席位上发言，重申最低可信威慑与不首先使用等立场。", "summary_en": "Manish Tewari, a three-term Congress parliamentarian and former minister, represented India at the UN General Assembly's First Committee. He reaffirmed commitments to credible minimum deterrence, No First Use policy, and step-by-step global disarmament, while warning against AI in nuclear systems and urging protections for non-nuclear states. The BJP-led government's choice of an opposition figure drew online praise for prioritizing national interest over party lines, alongside critiques questioning the ruling party's own talent pool. India's positions remained consistent, as noted by its UN mission.", "summary_zh": "三届国大党议员、前部长 Manish Tewari 代表印度出席联大一委。他重申可信最低威慑、不首先使用与分步全球裁军，并警告勿将 AI 嵌入核系统、呼吁保护无核国家。印人党政府起用反对党人士引发网上赞扬「国家利益高于党派」，亦有批评质疑执政党人才储备。印方联合国使团称立场与既往一致。", "body_en": "Congress MP Manish Tewari Delivers India's UN Statement on Nuclear Disarmament.\n\nIn a formal UN hall in New York, opposition MP Manish Tewari stood at India's desk, speaking for the nation on nuclear risks and restraint.\n\nManish Tewari, a three-term Congress parliamentarian and former minister, represented India at the UN General Assembly's First Committee. He reaffirmed commitments to credible minimum deterrence, No First Use policy, and step-by-step global disarmament, while warning against AI in nuclear systems and urging protections for non-nuclear states.\n\nThe BJP-led government's choice of an opposition figure drew online praise for prioritizing national interest over party lines, alongside critiques questioning the ruling party's own talent pool. India's positions remained consistent, as noted by its UN mission.", "body_zh": "国大党议员 Manish Tewari 代表印度在联大谈核裁军。\n\n反对党议员站在印度席位上发言，重申最低可信威慑与不首先使用等立场。\n\n三届国大党议员、前部长 Manish Tewari 代表印度出席联大一委。他重申可信最低威慑、不首先使用与分步全球裁军，并警告勿将 AI 嵌入核系统、呼吁保护无核国家。\n\n印人党政府起用反对党人士引发网上赞扬「国家利益高于党派」，亦有批评质疑执政党人才储备。印方联合国使团称立场与既往一致。", "url": "https://x.com/i/trending/2112444163392422181", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T12:40:01.000Z"}, {"id": "2112540743277719599", "domain": "国际", "title_en": "Scaramucci Accuses Trump of Being Putin's Agent", "title_zh": "斯卡拉穆奇指责特朗普是「普京代理人」", "hook_en": "Anthony Scaramucci, Trump's former communications director, didn't hold back on a podcast. He listed policy decisions he says show Trump serves Putin's interests.", "hook_zh": "特朗普前通讯主管斯卡拉穆奇在播客上列出多项政策，称其服务于普京利益。", "summary_en": "On the Newsweek podcast The 1600, Scaramucci called Trump an 'agent of Putin' and shared a checklist on X, citing moves like weakening NATO alliances, threats over Greenland, exiting the nuclear forces treaty, troop pullouts from Europe, and a quiet response to Russian intel aiding attacks on U.S. forces. He described Trump's election as Russia's biggest foreign policy win since the Czars. Reactions online ranged from amplifying old Russian asset claims and memes to questions about the accusations' timing, amid recent U.S. waivers on Russian diesel exports that critics tie to the pattern.", "summary_zh": "在 Newsweek 播客《The 1600》中，斯卡拉穆奇称特朗普是「普京的代理人」，并在 X 上晒出清单，列举削弱北约、格陵兰威胁、退出核力量条约、从欧洲撤军，以及对俄情报协助袭击美军反应冷淡等。他称特朗普当选是自沙皇时代以来俄方最大外交胜利。网上反应从旧「俄资产」论与梗图，到质疑指控时机不等；近期美方对俄柴油出口豁免也被批评者纳入同一叙事。", "body_en": "Scaramucci Accuses Trump of Being Putin's Agent.\n\nAnthony Scaramucci, Trump's former communications director, didn't hold back on a podcast. He listed policy decisions he says show Trump serves Putin's interests.\n\nOn the Newsweek podcast The 1600, Scaramucci called Trump an 'agent of Putin' and shared a checklist on X, citing moves like weakening NATO alliances, threats over Greenland, exiting the nuclear forces treaty, troop pullouts from Europe, and a quiet response to Russian intel aiding attacks on U.S. forces.\n\nHe described Trump's election as Russia's biggest foreign policy win since the Czars. Reactions online ranged from amplifying old Russian asset claims and memes to questions about the accusations' timing, amid recent U.S. waivers on Russian diesel exports that critics tie to the pattern.", "body_zh": "斯卡拉穆奇指责特朗普是「普京代理人」。\n\n特朗普前通讯主管斯卡拉穆奇在播客上列出多项政策，称其服务于普京利益。\n\n在 Newsweek 播客《The 1600》中，斯卡拉穆奇称特朗普是「普京的代理人」，并在 X 上晒出清单，列举削弱北约、格陵兰威胁、退出核力量条约、从欧洲撤军，以及对俄情报协助袭击美军反应冷淡等。\n\n他称特朗普当选是自沙皇时代以来俄方最大外交胜利。网上反应从旧「俄资产」论与梗图，到质疑指控时机不等；近期美方对俄柴油出口豁免也被批评者纳入同一叙事。", "url": "https://x.com/i/trending/2112540743277719599", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T07:40:46.000Z"}, {"id": "2112623559877042588", "domain": "体育", "title_en": "USL Unveils Unified Brand with 'United for Soccer' Slogan", "title_zh": "USL 发布统一品牌，口号「为足球联合」", "hook_en": "The USL just rolled out a fresh look designed to tie together its eight leagues and thousands of players, coaches, and fans across the country.", "hook_zh": "美国足球联赛推出全新视觉，意在串联旗下八条联赛以及全国成千上万球员、教练与球迷。", "summary_en": "On Tuesday, the United Soccer League introduced a new brand identity under the slogan “United for Soccer,” featuring a redesigned mark inspired by soccer ball geometry and an upward stair-step in the “S” for progress. This visual refresh, using consistent USL Blue and soccer-net icons, connects men’s leagues from the upcoming USL Premier in 2028 down to youth levels, plus women’s leagues like Gainbridge Super League and W League. It supports planned promotion and relegation across three professional men’s tiers, creating clearer pathways, with full rollout starting January 2027. Fans and observers have mixed reactions, from excitement over grassroots growth to questions about the design and timeline.", "summary_zh": "周二，United Soccer League 以口号「United for Soccer」发布新品牌标识，设计灵感来自足球几何结构，「S」中向上阶梯象征进步。统一的 USL 蓝与球网图标连接从 2028 年将推出的男子 USL Premier 到青少年层级，以及女子 Gainbridge Super League、W League 等。品牌亦支撑三层男子职业联赛的升降级规划，理顺上升通道，全面落地自 2027 年 1 月起。球迷与观察者反应不一：有人为草根成长欢呼，也有人对设计与时间表存疑。", "body_en": "USL Unveils Unified Brand with 'United for Soccer' Slogan.\n\nThe USL just rolled out a fresh look designed to tie together its eight leagues and thousands of players, coaches, and fans across the country.\n\nOn Tuesday, the United Soccer League introduced a new brand identity under the slogan “United for Soccer,” featuring a redesigned mark inspired by soccer ball geometry and an upward stair-step in the “S” for progress. This visual refresh, using consistent USL Blue and soccer-net icons, connects men’s leagues from the upcoming USL Premier in 2028 down to youth levels, plus women’s leagues like Gainbridge Super League and W League.\n\nIt supports planned promotion and relegation across three professional men’s tiers, creating clearer pathways, with full rollout starting January 2027. Fans and observers have mixed reactions, from excitement over grassroots growth to questions about the design and timeline.", "body_zh": "USL 发布统一品牌，口号「为足球联合」。\n\n美国足球联赛推出全新视觉，意在串联旗下八条联赛以及全国成千上万球员、教练与球迷。\n\n周二，United Soccer League 以口号「United for Soccer」发布新品牌标识，设计灵感来自足球几何结构，「S」中向上阶梯象征进步。统一的 USL 蓝与球网图标连接从 2028 年将推出的男子 USL Premier 到青少年层级，以及女子 Gainbridge Super League、W League 等。\n\n品牌亦支撑三层男子职业联赛的升降级规划，理顺上升通道，全面落地自 2027 年 1 月起。球迷与观察者反应不一：有人为草根成长欢呼，也有人对设计与时间表存疑。", "url": "https://x.com/i/trending/2112623559877042588", "category": "Sports", "topics": ["Soccer"], "updated_at": "2026-10-21T00:50:39.000Z"}, {"id": "2112637280108335380", "domain": "体育", "title_en": "NFL Umpire Larry Smith Tears Quadriceps in Rare Non-Contact Injury at Wembley", "title_zh": "NFL 裁判拉里·史密斯温布利湿草滑倒撕裂股四头肌", "hook_en": "Larry Smith slipped on wet grass between plays, stood briefly, then collapsed clutching his leg—a shocking moment that sidelined the umpire for good this season.", "hook_zh": "拉里·史密斯在死球间隙湿草上滑倒，短暂站起后又捂腿倒下——这一幕令他本赛季提前告别。", "summary_en": "During the Houston Texans-Jacksonville Jaguars game at Wembley Stadium, second-year NFL umpire Larry Smith tore his right quadriceps in a non-contact slip early in the first quarter. Trainers from both teams helped him off the field on a cart, and his crew finished with six officials while splitting his duties. A middle school principal from Kansas City, Kansas, in his full-time job, Smith won't return until 2027, prompting the NFL to seek a replacement like swing official Tab Slaughter or Ian Malepeai for referee Shawn Hochuli’s crew. Veteran line judge Carl Johnson knelt by his side, hat off in what looked like a prayer, as fans shared surprised laughs about refs joining the injury list.", "summary_zh": "休斯顿德州人队对阵杰克逊维尔美洲虎队的温布利比赛中，入行第二年的 NFL 裁判拉里·史密斯在第一节早段非对抗滑倒，右股四头肌撕裂。双方训练人员用球车将其抬离，执法组以六人完赛并分摊其职责。史密斯全职是堪萨斯城一名中学校长，预计要到 2027 年才能复出；联盟将为裁判肖恩·霍楚利组寻找替补，如轮换裁判 Tab Slaughter 或 Ian Malepeai。资深边线裁判卡尔·约翰逊跪其身旁、脱帽似在祈祷；球迷则半开玩笑「连裁判也进伤病名单了」。", "body_en": "NFL Umpire Larry Smith Tears Quadriceps in Rare Non-Contact Injury at Wembley.\n\nLarry Smith slipped on wet grass between plays, stood briefly, then collapsed clutching his leg—a shocking moment that sidelined the umpire for good this season.\n\nDuring the Houston Texans-Jacksonville Jaguars game at Wembley Stadium, second-year NFL umpire Larry Smith tore his right quadriceps in a non-contact slip early in the first quarter. Trainers from both teams helped him off the field on a cart, and his crew finished with six officials while splitting his duties.\n\nA middle school principal from Kansas City, Kansas, in his full-time job, Smith won't return until 2027, prompting the NFL to seek a replacement like swing official Tab Slaughter or Ian Malepeai for referee Shawn Hochuli’s crew. Veteran line judge Carl Johnson knelt by his side, hat off in what looked like a prayer, as fans shared surprised laughs about refs joining the injury list.", "body_zh": "NFL 裁判拉里·史密斯温布利湿草滑倒撕裂股四头肌。\n\n拉里·史密斯在死球间隙湿草上滑倒，短暂站起后又捂腿倒下——这一幕令他本赛季提前告别。\n\n休斯顿德州人队对阵杰克逊维尔美洲虎队的温布利比赛中，入行第二年的 NFL 裁判拉里·史密斯在第一节早段非对抗滑倒，右股四头肌撕裂。双方训练人员用球车将其抬离，执法组以六人完赛并分摊其职责。\n\n史密斯全职是堪萨斯城一名中学校长，预计要到 2027 年才能复出；联盟将为裁判肖恩·霍楚利组寻找替补，如轮换裁判 Tab Slaughter 或 Ian Malepeai。资深边线裁判卡尔·约翰逊跪其身旁、脱帽似在祈祷；球迷则半开玩笑「连裁判也进伤病名单了」。", "url": "https://x.com/i/trending/2112637280108335380", "category": "Sports", "topics": ["NFL"], "updated_at": "2026-10-20T20:16:29.000Z"}, {"id": "2112363184577191956", "domain": "体育", "title_en": "NFL Pushes Ahead with First France Game Amid Paris Unrest", "title_zh": "巴黎动荡中 NFL 仍推进法国首场常规赛", "hook_en": "As riots rage in Paris over rising costs and public services, the NFL stands firm on its historic game at Stade de France. Steelers star T.J. Watt's wife posted a headline questioning the decision with 'Tell me how this one make sense???'.", "hook_zh": "巴黎因生活成本与公共服务爆发骚乱，NFL 仍坚持法兰西体育场历史性比赛。钢人球星 T.J. 瓦特妻子发帖质问「这怎么说得通」。", "summary_en": "The Pittsburgh Steelers and New Orleans Saints are set to play the NFL's first regular-season game in France on October 25 at Stade de France in Saint-Denis, despite violent protests that erupted October 17-18, leading to arrests, fires, and curfews. League officials, including Roger Goodell, call the unrest 'mostly peaceful' and have ramped up security with local police, national authorities, and the U.S. State Department, confirming no plans to postpone. The Saints have arrived, Steelers are en route, and executives like Peter O’Reilly stress safety as the top priority, even as some players' families voice concerns.", "summary_zh": "匹兹堡钢人与新奥尔良圣徒定于 10 月 25 日在圣但尼法兰西体育场进行 NFL 法国首场常规赛，尽管 10 月 17–18 日暴力抗议导致逮捕、纵火与宵禁。包括罗杰·古德尔在内的联盟官员称动荡「大体和平」，并与地方警察、国家当局及美国国务院加强安保，暂无延期计划。圣徒已抵达、钢人在途，高管强调安全优先，部分球员家属仍表担忧。", "body_en": "NFL Pushes Ahead with First France Game Amid Paris Unrest.\n\nAs riots rage in Paris over rising costs and public services, the NFL stands firm on its historic game at Stade de France. Steelers star T.J. Watt's wife posted a headline questioning the decision with 'Tell me how this one make sense???'.\n\nThe Pittsburgh Steelers and New Orleans Saints are set to play the NFL's first regular-season game in France on October 25 at Stade de France in Saint-Denis, despite violent protests that erupted October 17-18, leading to arrests, fires, and curfews. League officials, including Roger Goodell, call the unrest 'mostly peaceful' and have ramped up security with local police, national authorities, and the U.S.\n\nState Department, confirming no plans to postpone. The Saints have arrived, Steelers are en route, and executives like Peter O’Reilly stress safety as the top priority, even as some players' families voice concerns.", "body_zh": "巴黎动荡中 NFL 仍推进法国首场常规赛。\n\n巴黎因生活成本与公共服务爆发骚乱，NFL 仍坚持法兰西体育场历史性比赛。钢人球星 T.J. 瓦特妻子发帖质问「这怎么说得通」。\n\n匹兹堡钢人与新奥尔良圣徒定于 10 月 25 日在圣但尼法兰西体育场进行 NFL 法国首场常规赛，尽管 10 月 17–18 日暴力抗议导致逮捕、纵火与宵禁。包括罗杰·古德尔在内的联盟官员称动荡「大体和平」，并与地方警察、国家当局及美国国务院加强安保，暂无延期计划。\n\n圣徒已抵达、钢人在途，高管强调安全优先，部分球员家属仍表担忧。", "url": "https://x.com/i/trending/2112363184577191956", "category": "Sports", "topics": ["NFL"], "updated_at": "2026-10-21T05:34:34.000Z"}, {"id": "2112623569473597808", "domain": "体育", "title_en": "Liverpool Fans Debate Skipping Villarreal Game for PSG-Barcelona Clash", "title_zh": "利物浦球迷纠结：欧冠主场与巴黎对巴萨同开", "hook_en": "Picture this: Liverpool's Champions League night at Anfield collides head-on with PSG versus Barcelona's star power, leaving fans torn on where to point their screens.", "hook_zh": "利物浦安菲尔德的欧冠之夜与巴黎圣日耳曼对阵巴塞罗那撞车，球迷纠结该把目光投向哪边屏幕。", "summary_en": "On Tuesday, Liverpool host Villarreal at Anfield at 8pm BST, the exact same time PSG welcomes Barcelona in another Champions League league-phase match. Fans are debating fiercely online after one called out those tempted to watch the glamorous PSG-Barcelona tie instead, with most insisting loyalty means sticking with the Reds no matter what. Some admit the pull of players like Lamine Yamal and Ousmane Dembélé but plan to prioritize their team, while others suggest splitting screens or note the spat feels like an online-only thing. It highlights football's tug between club devotion and big European showdowns.", "summary_zh": "周二英国夏令时晚 8 点，利物浦在安菲尔德主场迎战比利亚雷亚尔，同一时间巴黎在欧冠联赛阶段迎战巴萨。有人在网上点名「忍不住去看巴黎—巴萨」的球迷后，讨论升温；多数人坚持忠诚就该死守红军。也有人承认亚马尔、登贝莱等球星很有吸引力，但仍计划优先看本队，或考虑分屏观看。这场争论折射出俱乐部忠诚与「大欧洲对决」吸引力之间的拉扯。", "body_en": "Liverpool Fans Debate Skipping Villarreal Game for PSG-Barcelona Clash.\n\nPicture this: Liverpool's Champions League night at Anfield collides head-on with PSG versus Barcelona's star power, leaving fans torn on where to point their screens.\n\nOn Tuesday, Liverpool host Villarreal at Anfield at 8pm BST, the exact same time PSG welcomes Barcelona in another Champions League league-phase match. Fans are debating fiercely online after one called out those tempted to watch the glamorous PSG-Barcelona tie instead, with most insisting loyalty means sticking with the Reds no matter what.\n\nSome admit the pull of players like Lamine Yamal and Ousmane Dembélé but plan to prioritize their team, while others suggest splitting screens or note the spat feels like an online-only thing. It highlights football's tug between club devotion and big European showdowns.", "body_zh": "利物浦球迷纠结：欧冠主场与巴黎对巴萨同开。\n\n利物浦安菲尔德的欧冠之夜与巴黎圣日耳曼对阵巴塞罗那撞车，球迷纠结该把目光投向哪边屏幕。\n\n周二英国夏令时晚 8 点，利物浦在安菲尔德主场迎战比利亚雷亚尔，同一时间巴黎在欧冠联赛阶段迎战巴萨。有人在网上点名「忍不住去看巴黎—巴萨」的球迷后，讨论升温；多数人坚持忠诚就该死守红军。\n\n也有人承认亚马尔、登贝莱等球星很有吸引力，但仍计划优先看本队，或考虑分屏观看。这场争论折射出俱乐部忠诚与「大欧洲对决」吸引力之间的拉扯。", "url": "https://x.com/i/trending/2112623569473597808", "category": "Sports", "topics": ["UEFA Champions League"], "updated_at": "2026-10-20T19:23:57.000Z"}, {"id": "2112281281501528167", "domain": "体育", "title_en": "Kyrie Irving Doubts Playing into His Early 40s as NBA Evolves", "title_zh": "凯里·欧文质疑自己能否像勒布朗一样打到四十出头", "hook_en": "Kyrie Irving paused during media day to reflect on a league that's changed since his childhood dreams. At 34, he loves the game but sees modern pressures making a long career like LeBron's unlikely for him.", "hook_zh": "凯里·欧文在媒体日反思：联盟已非儿时梦想中的模样。34 岁的他仍爱篮球，但觉现代压力让勒布朗式超长生涯对己不太可能。", "summary_en": "The Mavericks guard shared honest thoughts after practice Monday, saying he can't envision suiting up at 42 or 43 amid social media, gambling, and a more 'robotic' NBA far from the one he fell in love with as a kid. Irving praised LeBron James, Stephen Curry, and Kevin Durant for their longevity while noting shifts like mental health talks and tipping meetings that weren't around when he entered as the 2011 No. 1 pick. Preparing for his 2026-27 return after missing last season with a torn ACL, he's focused on enjoying competition and personal growth as Dallas opens Wednesday against Houston.", "summary_zh": "这名独行侠后卫周一训练后坦诚，在社交媒体、博彩与更「机械」的 NBA 中，难以想象自己 42、43 岁还穿球衣——那与儿时爱上的篮球相去甚远。他称赞勒布朗、库里与杜兰特的长寿，同时提到心理健康讨论、赛前提示会等入行时（2011 年状元秀）尚不存在的变化。在因 ACL 撕裂缺席上赛季后，他备战 2026–27 回归，专注享受竞争与成长，达拉斯周三对休斯敦揭幕。", "body_en": "Kyrie Irving Doubts Playing into His Early 40s as NBA Evolves.\n\nKyrie Irving paused during media day to reflect on a league that's changed since his childhood dreams. At 34, he loves the game but sees modern pressures making a long career like LeBron's unlikely for him.\n\nThe Mavericks guard shared honest thoughts after practice Monday, saying he can't envision suiting up at 42 or 43 amid social media, gambling, and a more 'robotic' NBA far from the one he fell in love with as a kid. Irving praised LeBron James, Stephen Curry, and Kevin Durant for their longevity while noting shifts like mental health talks and tipping meetings that weren't around when he entered as the 2011 No.\n\n1 pick. Preparing for his 2026-27 return after missing last season with a torn ACL, he's focused on enjoying competition and personal growth as Dallas opens Wednesday against Houston.", "body_zh": "凯里·欧文质疑自己能否像勒布朗一样打到四十出头。\n\n凯里·欧文在媒体日反思：联盟已非儿时梦想中的模样。34 岁的他仍爱篮球，但觉现代压力让勒布朗式超长生涯对己不太可能。\n\n这名独行侠后卫周一训练后坦诚，在社交媒体、博彩与更「机械」的 NBA 中，难以想象自己 42、43 岁还穿球衣——那与儿时爱上的篮球相去甚远。他称赞勒布朗、库里与杜兰特的长寿，同时提到心理健康讨论、赛前提示会等入行时（2011 年状元秀）尚不存在的变化。\n\n在因 ACL 撕裂缺席上赛季后，他备战 2026–27 回归，专注享受竞争与成长，达拉斯周三对休斯敦揭幕。", "url": "https://x.com/i/trending/2112281281501528167", "category": "Sports", "topics": [], "updated_at": "2026-10-20T15:54:00.000Z"}, {"id": "2112804232634187907", "domain": "体育", "title_en": "NBA Season Tips Off with Thunder Victory and Fan Joy", "title_zh": "NBA 新季揭幕：雷霆取胜，球迷欢腾", "hook_en": "Fans lit up with pure excitement as the 2026-27 NBA season returned, comparing it to Christmas and loving the team rivalries packed with popcorn drama.", "hook_zh": "2026–27 赛季回归，球迷兴奋如过圣诞，津津乐道火药味十足的对档戏码。", "summary_en": "The season kicked off on October 20 with a tripleheader, highlighted by the Oklahoma City Thunder beating the San Antonio Spurs 116-104 in a Western Conference Finals rematch. Shai Gilgeous-Alexander scored 32 points to lead OKC, fueling the tension between teams with physical histories and stars like Chet Holmgren and Victor Wembanyama. Other games saw the Knicks drop their banner night to the 76ers, while the Pistons rallied past the Celtics. Supporters shared heartfelt posts calling it the best time of year, with real hate between teams making every matchup thrilling.", "summary_zh": "赛季 10 月 20 日以三场连赛揭幕，焦点之一是西决重演：俄克拉荷马城雷霆 116–104 击败圣安东尼奥马刺。谢伊·吉尔杰斯-亚历山大砍下 32 分领军，两队身体对抗史与霍姆格伦、文班亚马等球星令火药味十足。另场尼克斯主场横幅夜不敌 76 人，活塞逆转凯尔特人。球迷发帖称一年中最美好时光，真实「恨意」让每场都刺激。", "body_en": "NBA Season Tips Off with Thunder Victory and Fan Joy.\n\nFans lit up with pure excitement as the 2026-27 NBA season returned, comparing it to Christmas and loving the team rivalries packed with popcorn drama.\n\nThe season kicked off on October 20 with a tripleheader, highlighted by the Oklahoma City Thunder beating the San Antonio Spurs 116-104 in a Western Conference Finals rematch. Shai Gilgeous-Alexander scored 32 points to lead OKC, fueling the tension between teams with physical histories and stars like Chet Holmgren and Victor Wembanyama.\n\nOther games saw the Knicks drop their banner night to the 76ers, while the Pistons rallied past the Celtics. Supporters shared heartfelt posts calling it the best time of year, with real hate between teams making every matchup thrilling.", "body_zh": "NBA 新季揭幕：雷霆取胜，球迷欢腾。\n\n2026–27 赛季回归，球迷兴奋如过圣诞，津津乐道火药味十足的对档戏码。\n\n赛季 10 月 20 日以三场连赛揭幕，焦点之一是西决重演：俄克拉荷马城雷霆 116–104 击败圣安东尼奥马刺。谢伊·吉尔杰斯-亚历山大砍下 32 分领军，两队身体对抗史与霍姆格伦、文班亚马等球星令火药味十足。\n\n另场尼克斯主场横幅夜不敌 76 人，活塞逆转凯尔特人。球迷发帖称一年中最美好时光，真实「恨意」让每场都刺激。", "url": "https://x.com/i/trending/2112804232634187907", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T07:17:07.000Z"}, {"id": "2112801176995467757", "domain": "体育", "title_en": "Sixers Upset Knicks on Ring Night with LeBron and Brown Debuts", "title_zh": "76 人队揭幕战客场击败尼克斯，詹姆斯与布朗亮相", "hook_en": "LeBron James stepped onto Madison Square Garden's floor for his Sixers debut, and the team quickly turned a pre-game doubter's tweet into prime ammo for fans.", "hook_zh": "勒布朗·詹姆斯身披 76 人队服登陆麦迪逊广场花园，揭幕战即成粉丝话题。", "summary_en": "The Philadelphia 76ers kicked off the 2026-27 NBA season with a 106-100 road win over the defending champion New York Knicks, spoiling their ring night celebration. Tyrese Maxey led with 28 points in the second-half rally, while new additions LeBron James tallied 14 points, nine rebounds, and seven assists, and Jaylen Brown added 19 points, eight rebounds, and six assists alongside Joel Embiid and Maxey. Fans immediately called out a pre-game tweet dismissing the Sixers as non-contenders, though many noted it's just the first of 82 games and true tests lie ahead.", "summary_zh": "费城 76 人队以 106-100 客场击败卫冕冠军纽约尼克斯，扫了对方戒指之夜的兴。马克西砍下 28 分带领下半场逆转；新援詹姆斯得到 14 分 9 篮板 7 助攻，杰伦·布朗贡献 19 分 8 篮板 6 助攻，恩比德亦在阵中。赛前有人发帖否认 76 人争冠资格，赛后被粉丝翻出调侃；不过多数人提醒赛季漫长，真正考验还在后头。", "body_en": "Sixers Upset Knicks on Ring Night with LeBron and Brown Debuts.\n\nLeBron James stepped onto Madison Square Garden's floor for his Sixers debut, and the team quickly turned a pre-game doubter's tweet into prime ammo for fans.\n\nThe Philadelphia 76ers kicked off the 2026-27 NBA season with a 106-100 road win over the defending champion New York Knicks, spoiling their ring night celebration.\n\nTyrese Maxey led with 28 points in the second-half rally, while new additions LeBron James tallied 14 points, nine rebounds, and seven assists, and Jaylen Brown added 19 points, eight rebounds, and six assists alongside Joel Embiid and Maxey. Fans immediately called out a pre-game tweet dismissing the Sixers as non-contenders, though many noted it's just the first of 82 games and true tests lie ahead.", "body_zh": "76 人队揭幕战客场击败尼克斯，詹姆斯与布朗亮相。\n\n勒布朗·詹姆斯身披 76 人队服登陆麦迪逊广场花园，揭幕战即成粉丝话题。\n\n费城 76 人队以 106-100 客场击败卫冕冠军纽约尼克斯，扫了对方戒指之夜的兴。马克西砍下 28 分带领下半场逆转；新援詹姆斯得到 14 分 9 篮板 7 助攻，杰伦·布朗贡献 19 分 8 篮板 6 助攻，恩比德亦在阵中。\n\n赛前有人发帖否认 76 人争冠资格，赛后被粉丝翻出调侃；不过多数人提醒赛季漫长，真正考验还在后头。", "url": "https://x.com/i/trending/2112801176995467757", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T07:06:29.000Z"}, {"id": "2112718297158332458", "domain": "体育", "title_en": "Pistons Upset Celtics in NBA's Rare Afternoon Opener", "title_zh": "活塞下午赛爆冷击败凯尔特人，NBA 试水日间开赛", "hook_en": "On a Tuesday afternoon, the Detroit Pistons stunned the Boston Celtics 121-113 in the NBA's bold 3 p.m. tip-off experiment. Fans lit up with cheers and questions about daytime hoops during work hours.", "hook_zh": "底特律活塞 121–113 击败波士顿凯尔特人，NBA 罕见的下午 3 点揭幕战引发热议。", "summary_en": "The league kicked off its 2026-27 season with a tripleheader on NBC and Peacock, starting with Detroit's win over Boston to dodge overlap with the Knicks' banner ceremony in New York. Officials pitched the early slot as a test to mimic MLB's big opening days and catch European prime time viewers. While some fans loved the fresh vibe and called for more weekday matinees, others puzzled over the timing and griped about games often starting late anyway. Detroit grabbed its first opening-night win in years, spotlighting Boston's new-look team with Paul George.", "summary_zh": "2026–27 赛季在 NBC 与 Peacock 以三场连播揭幕，活塞战胜凯尔特人，以避免与尼克斯横幅仪式撞车。联盟称早场旨在对标大联盟开幕氛围并覆盖欧洲黄金时段。部分球迷呼吁更多工作日日场，也有人质疑时机。活塞取得多年来首场揭幕战胜利，凯尔特人新阵容（含保罗·乔治）亦受关注。", "body_en": "Pistons Upset Celtics in NBA's Rare Afternoon Opener.\n\nOn a Tuesday afternoon, the Detroit Pistons stunned the Boston Celtics 121-113 in the NBA's bold 3 p.m. tip-off experiment. Fans lit up with cheers and questions about daytime hoops during work hours.\n\nThe league kicked off its 2026-27 season with a tripleheader on NBC and Peacock, starting with Detroit's win over Boston to dodge overlap with the Knicks' banner ceremony in New York. Officials pitched the early slot as a test to mimic MLB's big opening days and catch European prime time viewers.\n\nWhile some fans loved the fresh vibe and called for more weekday matinees, others puzzled over the timing and griped about games often starting late anyway. Detroit grabbed its first opening-night win in years, spotlighting Boston's new-look team with Paul George.", "body_zh": "活塞下午赛爆冷击败凯尔特人，NBA 试水日间开赛。\n\n底特律活塞 121–113 击败波士顿凯尔特人，NBA 罕见的下午 3 点揭幕战引发热议。\n\n2026–27 赛季在 NBC 与 Peacock 以三场连播揭幕，活塞战胜凯尔特人，以避免与尼克斯横幅仪式撞车。联盟称早场旨在对标大联盟开幕氛围并覆盖欧洲黄金时段。\n\n部分球迷呼吁更多工作日日场，也有人质疑时机。活塞取得多年来首场揭幕战胜利，凯尔特人新阵容（含保罗·乔治）亦受关注。", "url": "https://x.com/i/trending/2112718297158332458", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T01:36:46.000Z"}, {"id": "2112754961222410533", "domain": "体育", "title_en": "Canberra Stadium Debate: Cricket and AFL in New Lakeside Venue?", "title_zh": "堪培拉新湖滨球场之争：板球与澳式足球能否同场？", "hook_en": "Andrew Barr envisions a shiny new lakeside stadium that doubles for cricket and AFL alongside rugby and NRL. Fans of rectangular codes are pushing back hard, fearing a diluted experience.", "hook_zh": "首席部长设想一座兼顾板球、澳式足球与橄榄球/NRL 的新球场；矩形项目球迷担心观赛体验被稀释。", "summary_en": "ACT Chief Minister Andrew Barr wants planners of a proposed 30,000-seat stadium near Lake Burley Griffin to make it suitable for cricket and AFL matches, beyond its main role for NRL's Raiders and Super Rugby's Brumbies. Sports executive Peter Filopoulos warns that trying to serve everyone could compromise the close fan-action feel vital for football codes, while fans note Manuka Oval already handles AFL and cricket fine. Though Barr cites past risks of over-design and examples like Adelaide Oval succeed as multi-use, many urge prioritizing rectangular sports needs amid ongoing location and funding talks.", "summary_zh": "首都特区首席部长 Andrew Barr 希望拟建的伯利·格里芬湖畔约 3 万座球场，除服务 Raiders 与 Brumbies 外，也能办板球与 AFL。体育高管 Peter Filopoulos 警告「谁都迁就」可能损害足球类项目所需的近距离观赛感；球迷指出 Manuka Oval 已能承办 AFL 与板球。Barr 以过去过度设计风险及阿德莱德椭圆球场等成功多用途为例，但许多人仍呼吁优先矩形项目，选址与资金讨论仍在继续。", "body_en": "Canberra Stadium Debate: Cricket and AFL in New Lakeside Venue?.\n\nAndrew Barr envisions a shiny new lakeside stadium that doubles for cricket and AFL alongside rugby and NRL. Fans of rectangular codes are pushing back hard, fearing a diluted experience.\n\nACT Chief Minister Andrew Barr wants planners of a proposed 30,000-seat stadium near Lake Burley Griffin to make it suitable for cricket and AFL matches, beyond its main role for NRL's Raiders and Super Rugby's Brumbies.\n\nSports executive Peter Filopoulos warns that trying to serve everyone could compromise the close fan-action feel vital for football codes, while fans note Manuka Oval already handles AFL and cricket fine. Though Barr cites past risks of over-design and examples like Adelaide Oval succeed as multi-use, many urge prioritizing rectangular sports needs amid ongoing location and funding talks.", "body_zh": "堪培拉新湖滨球场之争：板球与澳式足球能否同场？。\n\n首席部长设想一座兼顾板球、澳式足球与橄榄球/NRL 的新球场；矩形项目球迷担心观赛体验被稀释。\n\n首都特区首席部长 Andrew Barr 希望拟建的伯利·格里芬湖畔约 3 万座球场，除服务 Raiders 与 Brumbies 外，也能办板球与 AFL。\n\n体育高管 Peter Filopoulos 警告「谁都迁就」可能损害足球类项目所需的近距离观赛感；球迷指出 Manuka Oval 已能承办 AFL 与板球。Barr 以过去过度设计风险及阿德莱德椭圆球场等成功多用途为例，但许多人仍呼吁优先矩形项目，选址与资金讨论仍在继续。", "url": "https://x.com/i/trending/2112754961222410533", "category": "Sports", "topics": ["Cricket"], "updated_at": "2026-10-21T04:02:16.000Z"}, {"id": "2112444167981060097", "domain": "体育", "title_en": "Manchester City Faces Possible Relegation After 114 Financial Charges", "title_zh": "曼城 114 项财政指控成立，面临可能降级风险", "hook_en": "Manchester City supporters fear a crippling points deduction that could drop their club to the Championship, while rivals cheer the potential shake-up in English football.", "hook_zh": "独立委员会裁定多数指控成立，球迷担忧重罚扣分甚至降入英冠；对手则欢呼英超或洗牌。", "summary_en": "An independent commission ruled Manchester City guilty on 114 of 115 charges for breaching financial rules from 2009 to 2018, including inflated sponsorship revenue and lack of cooperation. The club has appealed and denies wrongdoing, with no punishment yet decided, though reports suggest a massive points deduction that might relegate them this season if the appeal fails. Fans are divided: rivals want justice now, while City backers warn it could harm the Premier League's global draw, drawing parallels to Juventus's past demotion. The case could drag into early 2027, reshaping the top flight's future.", "summary_zh": "独立委员会认定曼城在 2009–2018 年 115 项财政违规指控中 114 项成立，包括虚增赞助收入与不予配合等。俱乐部已上诉并否认过错，处罚尚未敲定；有报道称若上诉失败，巨额扣分或致本赛季降级。球迷分裂：对手要立刻「伸张正义」，蓝军支持者则警告或伤英超全球吸引力，并拿尤文图斯曾降级作比。案件或拖至 2027 年初，重塑顶级联赛格局。", "body_en": "Manchester City Faces Possible Relegation After 114 Financial Charges.\n\nManchester City supporters fear a crippling points deduction that could drop their club to the Championship, while rivals cheer the potential shake-up in English football.\n\nAn independent commission ruled Manchester City guilty on 114 of 115 charges for breaching financial rules from 2009 to 2018, including inflated sponsorship revenue and lack of cooperation. The club has appealed and denies wrongdoing, with no punishment yet decided, though reports suggest a massive points deduction that might relegate them this season if the appeal fails.\n\nFans are divided: rivals want justice now, while City backers warn it could harm the Premier League's global draw, drawing parallels to Juventus's past demotion. The case could drag into early 2027, reshaping the top flight's future.", "body_zh": "曼城 114 项财政指控成立，面临可能降级风险。\n\n独立委员会裁定多数指控成立，球迷担忧重罚扣分甚至降入英冠；对手则欢呼英超或洗牌。\n\n独立委员会认定曼城在 2009–2018 年 115 项财政违规指控中 114 项成立，包括虚增赞助收入与不予配合等。俱乐部已上诉并否认过错，处罚尚未敲定；有报道称若上诉失败，巨额扣分或致本赛季降级。\n\n球迷分裂：对手要立刻「伸张正义」，蓝军支持者则警告或伤英超全球吸引力，并拿尤文图斯曾降级作比。案件或拖至 2027 年初，重塑顶级联赛格局。", "url": "https://x.com/i/trending/2112444167981060097", "category": "Sports", "topics": ["Premier League"], "updated_at": "2026-10-21T11:29:33.000Z"}, {"id": "2111931440430739802", "domain": "体育", "title_en": "Eagles Fans Lament Injury Wave Hitting 2026 Season Hard", "title_zh": "费城老鹰伤病潮来袭，球迷哀叹 2026 赛季开局艰难", "hook_en": "Philadelphia Eagles fans are pouring out their hearts over a brutal string of injuries that's left their team battered and their offense sputtering.", "hook_zh": "一连串重伤让进攻陷入泥潭，老鹰球迷心情跌到谷底。", "summary_en": "Quarterback Jalen Hurts is on injured reserve with a calf blood clot, sidelining him for at least four games, while running back Saquon Barkley nurses a hamstring issue and edge rusher Nolan Smith deals with a concussion from the Week 6 loss to Carolina. The Eagles rank near the bottom of the NFL at 31st in total offense, 29th in points, and 28th in passing, marking their worst start since 2000 in key metrics. At 2-4, fans vent frustration with cries of voodoo curses and jokes about a nearby substation, but the sheer volume of injuries has everyone watching closely as the team fights to stabilize.", "summary_zh": "四分卫 Jalen Hurts 因小腿血栓进伤病名单，至少缺阵四周；跑卫 Saquon Barkley 腿筋不适，边锋 Nolan Smith 在第 6 周负于卡罗来纳后脑震荡。老鹰全联盟进攻排名约第 31、得分第 29、传球第 28，多项指标为 2000 年以来最差开局之一。战绩 2胜4负，球迷又是喊「被诅咒」又是拿附近变电站开玩笑，但伤病密度让所有人紧盯球队能否稳住局面。", "body_en": "Eagles Fans Lament Injury Wave Hitting 2026 Season Hard.\n\nPhiladelphia Eagles fans are pouring out their hearts over a brutal string of injuries that's left their team battered and their offense sputtering.\n\nQuarterback Jalen Hurts is on injured reserve with a calf blood clot, sidelining him for at least four games, while running back Saquon Barkley nurses a hamstring issue and edge rusher Nolan Smith deals with a concussion from the Week 6 loss to Carolina.\n\nThe Eagles rank near the bottom of the NFL at 31st in total offense, 29th in points, and 28th in passing, marking their worst start since 2000 in key metrics. At 2-4, fans vent frustration with cries of voodoo curses and jokes about a nearby substation, but the sheer volume of injuries has everyone watching closely as the team fights to stabilize.", "body_zh": "费城老鹰伤病潮来袭，球迷哀叹 2026 赛季开局艰难。\n\n一连串重伤让进攻陷入泥潭，老鹰球迷心情跌到谷底。\n\n四分卫 Jalen Hurts 因小腿血栓进伤病名单，至少缺阵四周；跑卫 Saquon Barkley 腿筋不适，边锋 Nolan Smith 在第 6 周负于卡罗来纳后脑震荡。\n\n老鹰全联盟进攻排名约第 31、得分第 29、传球第 28，多项指标为 2000 年以来最差开局之一。战绩 2胜4负，球迷又是喊「被诅咒」又是拿附近变电站开玩笑，但伤病密度让所有人紧盯球队能否稳住局面。", "url": "https://x.com/i/trending/2111931440430739802", "category": "Sports", "topics": ["NFL"], "updated_at": "2026-10-20T06:11:24.000Z"}, {"id": "2112527510105919970", "domain": "体育", "title_en": "Ex-NFL Player Accuses Refs of Rigging Games for Chiefs", "title_zh": "前 NFL 球员指控裁判偏袒酋长，争议再起", "hook_en": "Breiden Fehoko leaned into the mic on a podcast and called out what he saw as late-game favoritism for the Chiefs. His words tapped into frustrations many rival fans have felt for years.", "hook_zh": "Breiden Fehoko 在播客上称第四节有「幽灵判罚」帮堪萨斯城赢球，戳中多年对手球迷的怒点。", "summary_en": "Former Chargers defensive tackle Breiden Fehoko claimed on Jason Whitlock's podcast that officials give Kansas City 'ghost calls' in the fourth quarter to swing tight games. He pointed to a pattern where penalties bail out the Chiefs when trailing, calling it a 'mockery,' and challenged refs to stay impartial in the playoffs. Critics noted his limited experience—just one game against Kansas City and 19 career appearances—while fans referenced moments like the 2022 AFC Championship as supposed proof. The debate highlights ongoing gripes about NFL officiating but lacks hard evidence of rigging.", "summary_zh": "前闪电防守截锋 Fehoko 在 Jason Whitlock 播客上声称，官员会在第四节用「幽灵判罚」扭转胶着比赛，落后时点球「救」酋长，称之为「嘲弄」，并要求季后赛保持公正。批评指出他仅打过一场对阵堪萨斯城、生涯出场约 19 次；球迷则搬出 2022 年 AFC 冠军赛等片段作「证据」。争论凸显对 NFL 执法的积怨，但缺乏操纵确证。", "body_en": "Ex-NFL Player Accuses Refs of Rigging Games for Chiefs.\n\nBreiden Fehoko leaned into the mic on a podcast and called out what he saw as late-game favoritism for the Chiefs. His words tapped into frustrations many rival fans have felt for years.\n\nFormer Chargers defensive tackle Breiden Fehoko claimed on Jason Whitlock's podcast that officials give Kansas City 'ghost calls' in the fourth quarter to swing tight games. He pointed to a pattern where penalties bail out the Chiefs when trailing, calling it a 'mockery,' and challenged refs to stay impartial in the playoffs.\n\nCritics noted his limited experience—just one game against Kansas City and 19 career appearances—while fans referenced moments like the 2022 AFC Championship as supposed proof. The debate highlights ongoing gripes about NFL officiating but lacks hard evidence of rigging.", "body_zh": "前 NFL 球员指控裁判偏袒酋长，争议再起。\n\nBreiden Fehoko 在播客上称第四节有「幽灵判罚」帮堪萨斯城赢球，戳中多年对手球迷的怒点。\n\n前闪电防守截锋 Fehoko 在 Jason Whitlock 播客上声称，官员会在第四节用「幽灵判罚」扭转胶着比赛，落后时点球「救」酋长，称之为「嘲弄」，并要求季后赛保持公正。\n\n批评指出他仅打过一场对阵堪萨斯城、生涯出场约 19 次；球迷则搬出 2022 年 AFC 冠军赛等片段作「证据」。争论凸显对 NFL 执法的积怨，但缺乏操纵确证。", "url": "https://x.com/i/trending/2112527510105919970", "category": "Sports", "topics": ["NFL"], "updated_at": "2026-10-21T02:52:40.000Z"}, {"id": "2112367163868877083", "domain": "体育", "title_en": "Valkyries Coach Natalie Nakase's Intense Tactics Fuel WNBA Finals Push", "title_zh": "女勇士主帅中濑Natalie 高压训练助推总决赛冲刺", "hook_en": "Natalie Nakase blasts machine gun and bomb sounds in practice to steel her players for chaos. It's her way of building warriors ready to 'win or die' in the Finals.", "hook_zh": "训练中播放机枪与爆炸声，她要用「赢或死」心态把扩张球队打造成总决赛战士。", "summary_en": "Golden State Valkyries coach Natalie Nakase uses unconventional drills, like explosive noises and 4 a.m. texts to staff, inspired by Boston's Joe Mazzulla, to sharpen communication and mindset amid the playoffs. Her hypercompetitive style has transformed the expansion team into a defensive powerhouse, now tied 1-1 with the Atlanta Dream after a Game 2 loss marked by 19 turnovers. In her fiery postgame presser, Nakase snapped back at a reporter with 'Girl, what did I say?' while defending her squad's identity, drawing laughs and praise online as the series heads to Atlanta for Game 3.", "summary_zh": "金州女勇士主帅 Natalie Nakase 采用非常规训练——爆炸音效、凌晨 4 点给助教发消息等，灵感来自凯尔特人 Joe Mazzulla，旨在季后赛强化沟通与心态。她的高度竞争风格把扩张队打成防守强队；在与亚特兰大梦想队 1-1 战成平手后，第 2 场因 19 次失误落败。赛后新闻发布会上她回怼记者「Girl, what did I say?」，同时捍卫球队风格，网上笑赞一片；系列赛移师亚特兰大迎来第 3 场。", "body_en": "Valkyries Coach Natalie Nakase's Intense Tactics Fuel WNBA Finals Push.\n\nNatalie Nakase blasts machine gun and bomb sounds in practice to steel her players for chaos. It's her way of building warriors ready to 'win or die' in the Finals.\n\nGolden State Valkyries coach Natalie Nakase uses unconventional drills, like explosive noises and 4 a.m. texts to staff, inspired by Boston's Joe Mazzulla, to sharpen communication and mindset amid the playoffs.\n\nHer hypercompetitive style has transformed the expansion team into a defensive powerhouse, now tied 1-1 with the Atlanta Dream after a Game 2 loss marked by 19 turnovers. In her fiery postgame presser, Nakase snapped back at a reporter with 'Girl, what did I say?' while defending her squad's identity, drawing laughs and praise online as the series heads to Atlanta for Game 3.", "body_zh": "女勇士主帅中濑Natalie 高压训练助推总决赛冲刺。\n\n训练中播放机枪与爆炸声，她要用「赢或死」心态把扩张球队打造成总决赛战士。\n\n金州女勇士主帅 Natalie Nakase 采用非常规训练——爆炸音效、凌晨 4 点给助教发消息等，灵感来自凯尔特人 Joe Mazzulla，旨在季后赛强化沟通与心态。\n\n她的高度竞争风格把扩张队打成防守强队；在与亚特兰大梦想队 1-1 战成平手后，第 2 场因 19 次失误落败。赛后新闻发布会上她回怼记者「Girl, what did I say?」，同时捍卫球队风格，网上笑赞一片；系列赛移师亚特兰大迎来第 3 场。", "url": "https://x.com/i/trending/2112367163868877083", "category": "Sports", "topics": ["WNBA"], "updated_at": "2026-10-20T05:10:22.000Z"}, {"id": "2112675329613672597", "domain": "娱乐", "title_en": "YouTube Hits Record 14.2% of U.S. TV Viewing Time Over Netflix", "title_zh": "YouTube 占美国电视观看时长升至纪录 14.2%，超奈飞", "hook_en": "Every day, more Americans turn to YouTube for their TV time, leaving Netflix in the dust according to fresh Nielsen data.", "hook_zh": "尼尔森最新数据显示，美国人把越来越多「看电视」时间交给 YouTube，奈飞份额下滑。", "summary_en": "Nielsen's July 2026 report shows YouTube claiming 14.2% of total U.S. TV viewing, up from 13.4% a year ago, while Netflix dipped to 7.8% from 8.8%. Investor Chamath Palihapitiya shared the chart, explaining he watches YouTube daily and sees Netflix as a dormant subscription due to its high debt and content costs. Viewers praise YouTube's quick content discovery and long-form appeal, though analysts like Joseph Carlson note YouTube's hefty creator payouts offset its low-cost image. Streaming hit 49% of TV time that month, signaling a shift toward flexible, creator-driven platforms.", "summary_zh": "尼尔森 2026 年 7 月报告显示，YouTube 占美国电视总观看时长 14.2%，高于一年前的 13.4%；奈飞从 8.8% 降至 7.8%。投资人 Chamath Palihapitiya 转发图表称自己每天看 YouTube，并把奈飞视为因高负债与内容成本而「休眠」的订阅。观众称赞发现内容快、长视频吸引力强；分析师亦指出创作者分成抵消了「低成本」印象。当月流媒体占电视时长 49%，显示向灵活、创作者驱动平台迁移。", "body_en": "YouTube Hits Record 14.2% of U.S. TV Viewing Time Over Netflix.\n\nEvery day, more Americans turn to YouTube for their TV time, leaving Netflix in the dust according to fresh Nielsen data.\n\nNielsen's July 2026 report shows YouTube claiming 14.2% of total U.S. TV viewing, up from 13.4% a year ago, while Netflix dipped to 7.8% from 8.8%.\n\nInvestor Chamath Palihapitiya shared the chart, explaining he watches YouTube daily and sees Netflix as a dormant subscription due to its high debt and content costs. Viewers praise YouTube's quick content discovery and long-form appeal, though analysts like Joseph Carlson note YouTube's hefty creator payouts offset its low-cost image. Streaming hit 49% of TV time that month, signaling a shift toward flexible, creator-driven platforms.", "body_zh": "YouTube 占美国电视观看时长升至纪录 14.2%，超奈飞。\n\n尼尔森最新数据显示，美国人把越来越多「看电视」时间交给 YouTube，奈飞份额下滑。\n\n尼尔森 2026 年 7 月报告显示，YouTube 占美国电视总观看时长 14.2%，高于一年前的 13.4%；奈飞从 8.8% 降至 7.8%。投资人 Chamath Palihapitiya 转发图表称自己每天看 YouTube，并把奈飞视为因高负债与内容成本而「休眠」的订阅。\n\n观众称赞发现内容快、长视频吸引力强；分析师亦指出创作者分成抵消了「低成本」印象。当月流媒体占电视时长 49%，显示向灵活、创作者驱动平台迁移。", "url": "https://x.com/i/trending/2112675329613672597", "category": "News", "topics": ["Business & Finance", "Movies & TV"], "updated_at": "2026-10-20T22:49:16.000Z"}, {"id": "2111926403151356346", "domain": "娱乐", "title_en": "Entertainment Weekly Spotlights YAGA Cast in Sultry Digital Cover", "title_zh": "《娱乐周刊》用性感数字封面聚焦剧集 YAGA 卡司", "hook_en": "Carrie-Anne Moss places her hand on Hudson Williams' chest in a sleek black dress, their close pose capturing the witchy thriller's mix of mystery and desire.", "hook_zh": "Carrie-Anne Moss 与 Hudson Williams 的亲密构图，捕捉这部巫术惊悚片的神秘与欲望。", "summary_en": "The Entertainment Weekly digital cover features intimate photos of the YAGA cast, shot by Caitlin Cronenberg, with Moss and rising star Williams leading the steamy visuals amid dark forests and twisted branches. The series reimagines the Slavic Baba Yaga myth as a modern drama about a private investigator probing a disappearance in a coastal town, clashing with locals amid supernatural secrets—Williams plays dual roles as the missing heir and another character. Created by Kat Sandler from her play, it stars a tight Canadian ensemble including Noah Reid and Clark Backo, premiering October 23 on AMC+ and Crave with weekly episodes through a November 27 finale. Behind-the-scenes clips show the cast laughing in the woods, hinting at their strong chemistry.", "summary_zh": "由 Caitlin Cronenberg 拍摄的数字封面以 Moss 与新星 Williams 为主，置身暗林与扭曲枝桠。剧集将斯拉夫 baba Yaga 神话改写成现代剧：私家侦探在海滨小镇调查失踪案，与当地人及超自然秘密冲突；Williams 分饰失踪继承人等角色。Kat Sandler 由舞台剧改编，加拿大卡司包括 Noah Reid、Clark Backo 等，10 月 23 日起在 AMC+ 与 Crave 每周播出，11 月 27 日收官。幕后片段可见卡司林中欢笑，化学感足。", "body_en": "Entertainment Weekly Spotlights YAGA Cast in Sultry Digital Cover.\n\nCarrie-Anne Moss places her hand on Hudson Williams' chest in a sleek black dress, their close pose capturing the witchy thriller's mix of mystery and desire.\n\nThe Entertainment Weekly digital cover features intimate photos of the YAGA cast, shot by Caitlin Cronenberg, with Moss and rising star Williams leading the steamy visuals amid dark forests and twisted branches. The series reimagines the Slavic Baba Yaga myth as a modern drama about a private investigator probing a disappearance in a coastal town, clashing with locals amid supernatural secrets—Williams plays dual roles as the missing heir and another character.\n\nCreated by Kat Sandler from her play, it stars a tight Canadian ensemble including Noah Reid and Clark Backo, premiering October 23 on AMC+ and Crave with weekly episodes through a November 27 finale. Behind-the-scenes clips show the cast laughing in the woods, hinting at their strong chemistry.", "body_zh": "《娱乐周刊》用性感数字封面聚焦剧集 YAGA 卡司。\n\nCarrie-Anne Moss 与 Hudson Williams 的亲密构图，捕捉这部巫术惊悚片的神秘与欲望。\n\n由 Caitlin Cronenberg 拍摄的数字封面以 Moss 与新星 Williams 为主，置身暗林与扭曲枝桠。剧集将斯拉夫 baba Yaga 神话改写成现代剧：私家侦探在海滨小镇调查失踪案，与当地人及超自然秘密冲突；Williams 分饰失踪继承人等角色。\n\nKat Sandler 由舞台剧改编，加拿大卡司包括 Noah Reid、Clark Backo 等，10 月 23 日起在 AMC+ 与 Crave 每周播出，11 月 27 日收官。幕后片段可见卡司林中欢笑，化学感足。", "url": "https://x.com/i/trending/2111926403151356346", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-20T20:04:36.000Z"}, {"id": "2111675291110088931", "domain": "娱乐", "title_en": "Taylor Swift Shines in Custom Dior at 2026 Academy Museum Gala", "title_zh": "泰勒·斯威夫特定制迪奥惊艳 2026 电影学院博物馆晚会", "hook_en": "Taylor Swift stepped onto the red carpet in a custom icy-blue Dior gown, its soft pleats and sparkling bow catching every eye under the lights.", "hook_zh": "泰勒·斯威夫特红毯亮相冰蓝色定制迪奥礼服，柔褶与闪亮蝴蝶结在灯光下抢尽目光。", "summary_en": "The 2026 Academy Museum Gala on October 17 in Los Angeles raised over $14 million, honoring Charlize Theron, Colman Domingo, and John Carpenter. Swift performed hits like “Blank Space” and “Love Story” in her first full-band show since the Eras Tour, while Sabrina Carpenter and Rosé wowed in ruffled corsets and fringed gowns. Hannah Waddingham shared a warm selfie with Swift, praising her talent, as British Vogue called her the evening's belle in Chopard diamonds topping 40 carats. The horror-themed décor tied into the museum's new exhibition, blending fashion, music, and tributes into a standout night.", "summary_zh": "2026 年 10 月 17 日洛杉矶电影学院博物馆晚会筹得逾 1400 万美元，表彰查理兹·塞隆、科尔曼·多明戈与约翰·卡朋特。斯威夫特自 Eras 巡演后首度全乐队演出《Blank Space》《Love Story》等；Sabrina Carpenter 与 Rosé 也以荷叶边胸衣、流苏礼服惊艳。汉娜·瓦丁厄姆晒与斯威夫特自拍并赞其才华；《英国 Vogue》称其当晚焦点，肖邦钻石超 40 克拉。恐怖主题装饰呼应馆内新展，时尚、音乐与致敬融于一夜。", "body_en": "Taylor Swift Shines in Custom Dior at 2026 Academy Museum Gala.\n\nTaylor Swift stepped onto the red carpet in a custom icy-blue Dior gown, its soft pleats and sparkling bow catching every eye under the lights.\n\nThe 2026 Academy Museum Gala on October 17 in Los Angeles raised over $14 million, honoring Charlize Theron, Colman Domingo, and John Carpenter. Swift performed hits like “Blank Space” and “Love Story” in her first full-band show since the Eras Tour, while Sabrina Carpenter and Rosé wowed in ruffled corsets and fringed gowns.\n\nHannah Waddingham shared a warm selfie with Swift, praising her talent, as British Vogue called her the evening's belle in Chopard diamonds topping 40 carats. The horror-themed décor tied into the museum's new exhibition, blending fashion, music, and tributes into a standout night.", "body_zh": "泰勒·斯威夫特定制迪奥惊艳 2026 电影学院博物馆晚会。\n\n泰勒·斯威夫特红毯亮相冰蓝色定制迪奥礼服，柔褶与闪亮蝴蝶结在灯光下抢尽目光。\n\n2026 年 10 月 17 日洛杉矶电影学院博物馆晚会筹得逾 1400 万美元，表彰查理兹·塞隆、科尔曼·多明戈与约翰·卡朋特。斯威夫特自 Eras 巡演后首度全乐队演出《Blank Space》《Love Story》等；Sabrina Carpenter 与 Rosé 也以荷叶边胸衣、流苏礼服惊艳。\n\n汉娜·瓦丁厄姆晒与斯威夫特自拍并赞其才华；《英国 Vogue》称其当晚焦点，肖邦钻石超 40 克拉。恐怖主题装饰呼应馆内新展，时尚、音乐与致敬融于一夜。", "url": "https://x.com/i/trending/2111675291110088931", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-20T03:07:04.000Z"}, {"id": "2112653365356433717", "domain": "娱乐", "title_en": "Fans Defend Ariana Grande as Glinda Against Amanda Seyfried Casting Talk", "title_zh": "粉丝力挺格兰德饰演格琳达，回应赛弗里德「本可更好」论", "hook_en": "A post wondering if Amanda Seyfried would have topped Ariana Grande as Glinda in Wicked quickly met pushback from fans who love the film's magic just as it is.", "hook_zh": "有人猜测若由阿曼达·赛弗里德演《魔法坏女巫》格琳达会否更佳，粉丝迅速反驳：电影本身已够魔力。", "summary_en": "Ariana Grande shines as the bubbly Glinda opposite Cynthia Erivo's Elphaba in Jon M. Chu's hit musical films, which have pulled in hundreds of millions at the box office. Seyfried auditioned multiple times, even carving out time during The Dropout shoots, but later said Grande was meant for the role and called the movie fantastic. Fans highlight Grande's vocal range, her chemistry with Erivo, and director Chu's praise for her unique audition energy, shutting down the recurring what-if debate. The back-and-forth underscores fans' strong bond with Wicked's tale of friendship and ambition.", "summary_zh": "爱莉安娜·格兰德在朱浩伟执导的音乐电影中饰演活泼的格琳达，与辛西娅·埃里沃的艾尔法巴对手戏，票房累计数亿美元。赛弗里德曾多次试镜，后称角色本就属于格兰德并盛赞影片。粉丝强调其音域、与埃里沃的化学反应以及导演对其试镜能量的肯定，终结反复出现的「假如」争论。", "body_en": "Fans Defend Ariana Grande as Glinda Against Amanda Seyfried Casting Talk.\n\nA post wondering if Amanda Seyfried would have topped Ariana Grande as Glinda in Wicked quickly met pushback from fans who love the film's magic just as it is.\n\nAriana Grande shines as the bubbly Glinda opposite Cynthia Erivo's Elphaba in Jon M. Chu's hit musical films, which have pulled in hundreds of millions at the box office.\n\nSeyfried auditioned multiple times, even carving out time during The Dropout shoots, but later said Grande was meant for the role and called the movie fantastic. Fans highlight Grande's vocal range, her chemistry with Erivo, and director Chu's praise for her unique audition energy, shutting down the recurring what-if debate. The back-and-forth underscores fans' strong bond with Wicked's tale of friendship and ambition.", "body_zh": "粉丝力挺格兰德饰演格琳达，回应赛弗里德「本可更好」论。\n\n有人猜测若由阿曼达·赛弗里德演《魔法坏女巫》格琳达会否更佳，粉丝迅速反驳：电影本身已够魔力。\n\n爱莉安娜·格兰德在朱浩伟执导的音乐电影中饰演活泼的格琳达，与辛西娅·埃里沃的艾尔法巴对手戏，票房累计数亿美元。赛弗里德曾多次试镜，后称角色本就属于格兰德并盛赞影片。\n\n粉丝强调其音域、与埃里沃的化学反应以及导演对其试镜能量的肯定，终结反复出现的「假如」争论。", "url": "https://x.com/i/trending/2112653365356433717", "category": "Entertainment", "topics": ["Movies & TV", "Celebrity"], "updated_at": "2026-10-21T00:31:26.000Z"}, {"id": "2112605676610478278", "domain": "娱乐", "title_en": "Jaafar Jackson Wins Actor Award for Michael Jackson Role in 'Michael'", "title_zh": "贾法尔·杰克逊凭《Michael》迈克尔·杰克逊一角获演员奖", "hook_en": "Jaafar Jackson, nephew of the King of Pop, steps into the spotlight with a Critics Choice honor for his feature debut as Michael Jackson.", "hook_zh": "「流行之王」侄子贾法尔·杰克逊凭长片处女作饰演迈克尔·杰克逊，获评论选择荣誉，站上聚光灯。", "summary_en": "The Critics Choice Association named Jaafar Jackson the Actor Award – Film recipient at the 9th Annual Celebration of Black Cinema & Television for his portrayal in Lionsgate's 'Michael,' the first biopic to top $1 billion worldwide and Lionsgate's biggest release ever. Directed by Antoine Fuqua, the film traces Michael Jackson's rise and drew strong box-office success since opening in April. The ceremony happens November 16, 2026, at Fairmont Century Plaza in Los Angeles, with others like Debbie Allen receiving honors too. Fans celebrated the news, praising his acclaimed performance.", "summary_zh": "评论选择协会将第 9 届黑人电影与电视庆典「电影演员奖」授予贾法尔·杰克逊，表彰其在狮门《Michael》中的演绎——该片为全球票房破 10 亿美元的首部传记片，亦是狮门史上最大发行。安东尼·福奎阿执导，追溯杰克逊崛起，4 月上映后票房强劲。典礼 2026 年 11 月 16 日在洛杉矶 Fairmont Century Plaza 举行，黛比·艾伦等亦获表彰。粉丝庆祝并称赞其获好评的表演。", "body_en": "Jaafar Jackson Wins Actor Award for Michael Jackson Role in 'Michael'.\n\nJaafar Jackson, nephew of the King of Pop, steps into the spotlight with a Critics Choice honor for his feature debut as Michael Jackson.\n\nThe Critics Choice Association named Jaafar Jackson the Actor Award – Film recipient at the 9th Annual Celebration of Black Cinema & Television for his portrayal in Lionsgate's 'Michael,' the first biopic to top $1 billion worldwide and Lionsgate's biggest release ever. Directed by Antoine Fuqua, the film traces Michael Jackson's rise and drew strong box-office success since opening in April.\n\nThe ceremony happens November 16, 2026, at Fairmont Century Plaza in Los Angeles, with others like Debbie Allen receiving honors too. Fans celebrated the news, praising his acclaimed performance.", "body_zh": "贾法尔·杰克逊凭《Michael》迈克尔·杰克逊一角获演员奖。\n\n「流行之王」侄子贾法尔·杰克逊凭长片处女作饰演迈克尔·杰克逊，获评论选择荣誉，站上聚光灯。\n\n评论选择协会将第 9 届黑人电影与电视庆典「电影演员奖」授予贾法尔·杰克逊，表彰其在狮门《Michael》中的演绎——该片为全球票房破 10 亿美元的首部传记片，亦是狮门史上最大发行。安东尼·福奎阿执导，追溯杰克逊崛起，4 月上映后票房强劲。\n\n典礼 2026 年 11 月 16 日在洛杉矶 Fairmont Century Plaza 举行，黛比·艾伦等亦获表彰。粉丝庆祝并称赞其获好评的表演。", "url": "https://x.com/i/trending/2112605676610478278", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-20T18:15:13.000Z"}, {"id": "2112352804241285515", "domain": "娱乐", "title_en": "Dwayne Johnson Transforms into Elderly Chicken Man for Lizard Music", "title_zh": "巨石强森变装 70 岁「鸡肉人」出演《Lizard Music》", "hook_en": "Dwayne Johnson walked New York streets as a gray-haired, bearded 70-year-old, munching pizza with his young co-star beside a giant lizard puppet.", "hook_zh": "巨石强森现身纽约街头：灰发、皱纹、渔夫帽，几乎认不出他就是古怪的「鸡肉人」。", "summary_en": "The 54-year-old actor donned extensive prosthetics and makeup for five hours daily to play the eccentric Chicken Man in the upcoming film Lizard Music, adapting a 1976 children's book about a boy discovering lizard musicians on late-night TV. Slimmed down and nearly unrecognizable in a tan trench coat and bucket hat, he filmed alongside Theo Clark Leber near the green lizard puppet. Directed by Benny Safdie with a cast including Rachel McAdams and Jeff Goldblum, the live-action CGI hybrid hits theaters Christmas 2027 from Amazon MGM Studios.", "summary_zh": "他正在拍摄《Lizard Music》，这部真人与 CGI 结合的作品改编自丹尼尔·平克沃特 1976 年童书：男孩在深夜电视发现演奏异界音乐的蜥蜴，并结识鸡肉人及其 111 岁老母鸡。强森与年轻对手戏演员 Theo Clark Leber 同台，依赖大量化妆、假体与减重塑形；导演为本尼·萨夫迪，卡司还包括瑞秋·麦克亚当斯、杰夫·高布伦等。影片定档 2027 年圣诞节院线上映，花絮中披萨片与巨型蜥蜴玩偶尽显奇幻，外界称赞强森大胆转向戏剧角色。", "body_en": "Dwayne Johnson Transforms into 70-Year-Old Chicken Man for Lizard Music.\n\nDwayne Johnson stepped out on New York streets looking worlds away from his ripped action-hero self—gray hair, wrinkles, and a bucket hat making him truly unrecognizable as the eccentric Chicken Man.\n\nHe's filming Lizard Music, a live-action/CGI adaptation of Daniel Pinkwater’s 1976 children’s book about a boy who discovers lizards playing otherworldly music on late-night TV and befriends the Chicken Man and his 111-year-old chicken.\n\nJohnson, alongside young co-star Theo Clark Leber, sports extensive makeup, prosthetics, and weight loss for the role, directed by Benny Safdie with a cast including Rachel McAdams, Jeff Goldblum, and others. Set for a Christmas Day 2027 theatrical release, the family adventure captures whimsical moments like pizza slices and a giant lizard plush, drawing praise for Johnson's bold shift to dramatic roles.", "body_zh": "巨石强森变装 70 岁「鸡肉人」出演《Lizard Music》。\n\n巨石强森现身纽约街头：灰发、皱纹、渔夫帽，几乎认不出他就是古怪的「鸡肉人」。\n\n他正在拍摄《Lizard Music》，这部真人与 CGI 结合的作品改编自丹尼尔·平克沃特 1976 年童书：男孩在深夜电视发现演奏异界音乐的蜥蜴，并结识鸡肉人及其 111 岁老母鸡。\n\n强森与年轻对手戏演员 Theo Clark Leber 同台，依赖大量化妆、假体与减重塑形；导演为本尼·萨夫迪，卡司还包括瑞秋·麦克亚当斯、杰夫·高布伦等。影片定档 2027 年圣诞节院线上映，花絮中披萨片与巨型蜥蜴玩偶尽显奇幻，外界称赞强森大胆转向戏剧角色。", "url": "https://x.com/i/trending/2112352804241285515", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-21T11:29:20.000Z"}, {"id": "2112801173090587112", "domain": "娱乐", "title_en": "Thai Star Lingling Kwong Shines at Cartier's Wild Singapore Event", "title_zh": "Lingling Kwong 亮相新加坡卡地亚活动", "hook_en": "Lingling Sirilak Kwong glided through lush gardens in shimmering gowns and bold Cartier jewels, captivating everyone at the Faune & Flore celebration.", "hook_zh": "Lingling Kwong 身着黑色亮片长裙、配戏剧性手套，走进卡地亚丛林主题场景，以经典优雅吸引目光。", "summary_en": "Cartier transformed Rochester Park's historic bungalows into a nature-inspired wonderland for its 'Into the Wild' event, spotlighting panther motifs and floral designs across jewelry and more. Thai actress Kwong arrived as a special guest, switching elegant looks like a sequined halter gown with opera gloves and statement necklaces amid dances and illuminated gardens. The free public exhibition at 17 Rochester Park continues through October 25, with artisan demos and a tea salon inviting all to explore Cartier's craft.", "summary_zh": "10 月 21 日在罗切斯特公园举行的「Into the Wild」沉浸式体验中，她佩戴卡地亚全新 Faune & Flore 系列，搭配缟玛瑙、蓝宝石与钻石，被粉丝称为「女王范」。活动展出品牌动物灵感设计，持续至 10 月 25 日。同日她还在曼谷大型粉丝活动上推广 Her Hyness 防晒产品，凸显其在奢侈品与美妆领域的上升势头。", "body_en": "Lingling Kwong Shines at Cartier Event in Singapore.\n\nLingling Kwong stepped into Cartier’s wild jungle-themed world in a sleek black sequined gown and dramatic gloves, turning heads with her timeless elegance.\n\nAt the 'Into the Wild' immersive experience in Rochester Park on October 21, Kwong wore pieces from Cartier’s new Faune & Flore collection, featuring onyx, sapphires, and diamonds that fans called striking and queenly.\n\nThe event celebrates the brand’s animal-inspired designs through October 25. That same day, she promoted Her Hyness sunscreen at a big fan event in Bangkok, highlighting her rising star in luxury and beauty.", "body_zh": "Lingling Kwong 亮相新加坡卡地亚活动。\n\nLingling Kwong 身着黑色亮片长裙、配戏剧性手套，走进卡地亚丛林主题场景，以经典优雅吸引目光。\n\n10 月 21 日在罗切斯特公园举行的「Into the Wild」沉浸式体验中，她佩戴卡地亚全新 Faune & Flore 系列，搭配缟玛瑙、蓝宝石与钻石，被粉丝称为「女王范」。\n\n活动展出品牌动物灵感设计，持续至 10 月 25 日。同日她还在曼谷大型粉丝活动上推广 Her Hyness 防晒产品，凸显其在奢侈品与美妆领域的上升势头。", "url": "https://x.com/i/trending/2112801173090587112", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-21T11:50:05.000Z"}, {"id": "2112773061053460813", "domain": "娱乐", "title_en": "Global Fans Rally for 'Love On Hire' Premiere Tomorrow", "title_zh": "全球粉丝倒计时：《Love On Hire》明日首播", "hook_en": "Fans everywhere are buzzing with countdown posts like 'LOVE ON HIRE TOMORROW!!!!! T-O-M-O-R-R-O-W' as the Thai GL series gears up for its October 22 debut.", "hook_zh": "「明天！明天！」刷屏不断，泰国 GL 剧集定于 10 月 22 日开播。", "summary_en": "The WeTV Original romantic comedy stars Ginny Natnicha as poised CEO Chat in an arranged marriage and Jayna Angelina Stevens as Nan, hired to shake it up, blending revenge, fake dating, and real romance across 10 episodes airing Thursdays at 8 p.m. Thailand time. Chinese fans launched a 'Money Flower Bouquet' with 511,000 THB to cover production costs and celebrate Jayna's role, while U.S. supporters push WeTV VIP subscriptions and food projects deliver sushi platters to Ginny. From Bangkok screenings at Siam Paragon to subscription giveaways in the Philippines, Alkeys and global fandoms are turning excitement into coordinated gestures for the duo's latest work.", "summary_zh": "WeTV 原创浪漫喜剧由 Ginny Natnicha 饰演包办婚姻中的冷静 CEO Chat，Jayna Angelina Stevens 饰演受雇搅局的 Nan，揉合复仇、假约会与真感情，共 10 集，每周四泰国时间晚 8 点播出。中国粉丝发起约 51.1 万泰铢「Money Flower Bouquet」支援制作并庆祝 Jayna 新角；美国粉丝推动 WeTV VIP，餐饮应援把寿司送到 Ginny。从曼谷 Siam Paragon 放映到菲律宾订阅赠送，全球粉丝把热情变成协同应援。", "body_en": "Global Fans Rally for 'Love On Hire' Premiere Tomorrow.\n\nFans everywhere are buzzing with countdown posts like 'LOVE ON HIRE TOMORROW!!!!! T-O-M-O-R-R-O-W' as the Thai GL series gears up for its October 22 debut.\n\nThe WeTV Original romantic comedy stars Ginny Natnicha as poised CEO Chat in an arranged marriage and Jayna Angelina Stevens as Nan, hired to shake it up, blending revenge, fake dating, and real romance across 10 episodes airing Thursdays at 8 p.m. Thailand time.\n\nChinese fans launched a 'Money Flower Bouquet' with 511,000 THB to cover production costs and celebrate Jayna's role, while U.S. supporters push WeTV VIP subscriptions and food projects deliver sushi platters to Ginny. From Bangkok screenings at Siam Paragon to subscription giveaways in the Philippines, Alkeys and global fandoms are turning excitement into coordinated gestures for the duo's latest work.", "body_zh": "全球粉丝倒计时：《Love On Hire》明日首播。\n\n「明天！明天！」刷屏不断，泰国 GL 剧集定于 10 月 22 日开播。\n\nWeTV 原创浪漫喜剧由 Ginny Natnicha 饰演包办婚姻中的冷静 CEO Chat，Jayna Angelina Stevens 饰演受雇搅局的 Nan，揉合复仇、假约会与真感情，共 10 集，每周四泰国时间晚 8 点播出。\n\n中国粉丝发起约 51.1 万泰铢「Money Flower Bouquet」支援制作并庆祝 Jayna 新角；美国粉丝推动 WeTV VIP，餐饮应援把寿司送到 Ginny。从曼谷 Siam Paragon 放映到菲律宾订阅赠送，全球粉丝把热情变成协同应援。", "url": "https://x.com/i/trending/2112773061053460813", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-21T05:13:15.000Z"}, {"id": "2112252620291056101", "domain": "娱乐", "title_en": "Julia Stiles Honors Heath Ledger with Emotional Dancing With the Stars Tribute", "title_zh": "朱莉娅·斯蒂尔斯在《与星共舞》含泪致敬希斯·莱杰", "hook_en": "Julia Stiles danced through tears Tuesday night, recreating a heartfelt moment from 10 Things I Hate About You to honor her late friend Heath Ledger.", "hook_zh": "她重现《我恨你的十件事》经典桥段，向已故好友希斯·莱杰致意。", "summary_en": "Stiles and partner Ezra Sosa performed a contemporary routine to 'Can’t Take My Eyes Off You,' the song Ledger sang in the 1999 film, ending with a surprise reunion of co-stars like Joseph Gordon-Levitt and Gabrielle Union. She recited her character's poem from the movie, sharing that she aimed for authenticity in remembering Ledger, who died in 2008. Other highlights included Amber Glenn's top-scoring 38/40 dance for her sister, Ezra Frech's first 10 of the season for his mom, and Tyler Cameron's routine revealing he's expecting a baby girl with fiancée Tate Madden. The emotional night skipped eliminations, carrying scores to next week's double elimination.", "summary_zh": "斯蒂尔斯与舞伴 Ezra Sosa 以莱杰在 1999 年电影中演唱的《Can't Take My Eyes Off You》跳当代舞，结尾惊喜重聚约瑟夫·高登-莱维特、加布蕾·丝迪贝等昔日搭档。她朗诵片中角色诗句，称希望以真实方式纪念 2008 年去世的莱杰。同晚 Amber Glenn 为姐姐跳出满分边缘的 38/40，Ezra Frech 为本季首个满分 10 分向母亲致敬，Tyler Cameron 透露与未婚妻将迎女婴。本集未淘汰，分数带入下周双淘汰。", "body_en": "Julia Stiles Honors Heath Ledger with Emotional Dancing With the Stars Tribute.\n\nJulia Stiles danced through tears Tuesday night, recreating a heartfelt moment from 10 Things I Hate About You to honor her late friend Heath Ledger.\n\nStiles and partner Ezra Sosa performed a contemporary routine to 'Can’t Take My Eyes Off You,' the song Ledger sang in the 1999 film, ending with a surprise reunion of co-stars like Joseph Gordon-Levitt and Gabrielle Union. She recited her character's poem from the movie, sharing that she aimed for authenticity in remembering Ledger, who died in 2008.\n\nOther highlights included Amber Glenn's top-scoring 38/40 dance for her sister, Ezra Frech's first 10 of the season for his mom, and Tyler Cameron's routine revealing he's expecting a baby girl with fiancée Tate Madden. The emotional night skipped eliminations, carrying scores to next week's double elimination.", "body_zh": "朱莉娅·斯蒂尔斯在《与星共舞》含泪致敬希斯·莱杰。\n\n她重现《我恨你的十件事》经典桥段，向已故好友希斯·莱杰致意。\n\n斯蒂尔斯与舞伴 Ezra Sosa 以莱杰在 1999 年电影中演唱的《Can't Take My Eyes Off You》跳当代舞，结尾惊喜重聚约瑟夫·高登-莱维特、加布蕾·丝迪贝等昔日搭档。她朗诵片中角色诗句，称希望以真实方式纪念 2008 年去世的莱杰。\n\n同晚 Amber Glenn 为姐姐跳出满分边缘的 38/40，Ezra Frech 为本季首个满分 10 分向母亲致敬，Tyler Cameron 透露与未婚妻将迎女婴。本集未淘汰，分数带入下周双淘汰。", "url": "https://x.com/i/trending/2112252620291056101", "category": "Entertainment", "topics": ["Dancing With the Stars"], "updated_at": "2026-10-21T10:32:25.000Z"}, {"id": "2112468483736834436", "domain": "娱乐", "title_en": "Tate McRae's 'Housewife' Battles Olivia Rodrigo Remix for Hot 100 No. 2", "title_zh": "Tate McRae《Housewife》与 Olivia Rodrigo 混音争夺 Hot 100 亚军", "hook_en": "Tate McRae's bold red performance at the Victoria’s Secret Fashion Show has fans streaming 'Housewife' nonstop, fueling its tight race for No. 2 on the Billboard Hot 100.", "hook_zh": "维多利亚的秘密秀上的火红舞台带动《Housewife》猛冲榜，与 Rodrigo 合作曲缠斗第二名。", "summary_en": "Early forecasts show Tate McRae’s “Housewife” neck-and-neck with Olivia Rodrigo’s “expectations” remix featuring Chappell Roan for the No. 2 spot on the October 31, 2026 Hot 100 chart, alongside challengers like Taylor Swift and Lana Del Rey with Zach Bryan. “Housewife” notched over 6.5 million Spotify streams in a day, topped U.S. and global charts on debut, and won Billboard’s fan poll for favorite new music after Tate’s standout Fashion Show performance now selling for 69 cents. The Rodrigo-Roan remix video, with its fun game-show vibe and cameos, adds fresh push as streams and sales decide the final order in this streaming-driven showdown.", "summary_zh": "早期预测显示，Tate McRae 的《Housewife》与 Olivia Rodrigo 联手 Chappell Roan 的《expectations》混音，在 2026 年 10 月 31 日 Hot 100 亚军位置胶着，泰勒·斯威夫特及 Lana Del Rey 与 Zach Bryan 等亦在挑战。维多利亚的秘密时装秀表演助推串流。《Housewife》成为流行榜焦点之一。", "body_en": "Tate McRae's 'Housewife' Battles Olivia Rodrigo Remix for Hot 100 No. 2.\n\nTate McRae's bold red performance at the Victoria’s Secret Fashion Show has fans streaming 'Housewife' nonstop, fueling its tight race for No. 2 on the Billboard Hot 100.\n\nEarly forecasts show Tate McRae’s “Housewife” neck-and-neck with Olivia Rodrigo’s “expectations” remix featuring Chappell Roan for the No. 2 spot on the October 31, 2026 Hot 100 chart, alongside challengers like Taylor Swift and Lana Del Rey with Zach Bryan.\n\n“Housewife” notched over 6.5 million Spotify streams in a day, topped U.S. and global charts on debut, and won Billboard’s fan poll for favorite new music after Tate’s standout Fashion Show performance now selling for 69 cents. The Rodrigo-Roan remix video, with its fun game-show vibe and cameos, adds fresh push as streams and sales decide the final order in this streaming-driven showdown.", "body_zh": "Tate McRae《Housewife》与 Olivia Rodrigo 混音争夺 Hot 100 亚军。\n\n维多利亚的秘密秀上的火红舞台带动《Housewife》猛冲榜，与 Rodrigo 合作曲缠斗第二名。\n\n早期预测显示，Tate McRae 的《Housewife》与 Olivia Rodrigo 联手 Chappell Roan 的《expectations》混音，在 2026 年 10 月 31 日 Hot 100 亚军位置胶着，泰勒·斯威夫特及 Lana Del Rey 与 Zach Bryan 等亦在挑战。\n\n维多利亚的秘密时装秀表演助推串流。《Housewife》成为流行榜焦点之一。", "url": "https://x.com/i/trending/2112468483736834436", "category": "Entertainment", "topics": ["Music", "Pop"], "updated_at": "2026-10-21T10:32:22.000Z"}, {"id": "2112111882152910915", "domain": "娱乐", "title_en": "100 Days of Deception Captivates with Spy Romance in 1930s Korea", "title_zh": "《百日骗爱》以 1930 年代朝鲜间谍浪漫吸引观众", "hook_en": "In 1930s colonial Korea, a clever pickpocket goes undercover as a spy, sparking suspicion and romance with an elite interpreter amid high-stakes missions.", "hook_zh": "神偷卧底遇精英通译，怀疑与爱情在高风险任务中交织。", "summary_en": "tvN's '100 Days of Deception,' which premiered October 10, follows Lee Ga-kyung (Kim Yoo-jung), Gyeongseong’s top pickpocket on a 100-day undercover mission for the independence group, crossing paths with Kim Tae-woong (Park Jin-young), an adopted son of a high-ranking official. The series blends tense espionage, shifting loyalties, and budding romance, drawing praise for the leads' chemistry and climbing ratings from 5.3% at launch to around 9% by episode 4. Fans love behind-the-scenes clips of the stars laughing on set, while strong buzz rankings and Netflix availability worldwide fuel its momentum through late November.", "summary_zh": "tvN《百日骗爱》10 月 10 日开播，金裕贞饰京城顶尖扒手李佳京，受命为独立组织执行百日卧底；朴珍荣饰高官养子金泰雄。两人在殖民时期朝鲜的高危任务中萌生情愫与互疑。剧集以年代谍战加浪漫吸引观众。", "body_en": "100 Days of Deception Captivates with Spy Romance in 1930s Korea.\n\nIn 1930s colonial Korea, a clever pickpocket goes undercover as a spy, sparking suspicion and romance with an elite interpreter amid high-stakes missions.\n\ntvN's '100 Days of Deception,' which premiered October 10, follows Lee Ga-kyung (Kim Yoo-jung), Gyeongseong’s top pickpocket on a 100-day undercover mission for the independence group, crossing paths with Kim Tae-woong (Park Jin-young), an adopted son of a high-ranking official.\n\nThe series blends tense espionage, shifting loyalties, and budding romance, drawing praise for the leads' chemistry and climbing ratings from 5.3% at launch to around 9% by episode 4. Fans love behind-the-scenes clips of the stars laughing on set, while strong buzz rankings and Netflix availability worldwide fuel its momentum through late November.", "body_zh": "《百日骗爱》以 1930 年代朝鲜间谍浪漫吸引观众。\n\n神偷卧底遇精英通译，怀疑与爱情在高风险任务中交织。\n\ntvN《百日骗爱》10 月 10 日开播，金裕贞饰京城顶尖扒手李佳京，受命为独立组织执行百日卧底；朴珍荣饰高官养子金泰雄。\n\n两人在殖民时期朝鲜的高危任务中萌生情愫与互疑。剧集以年代谍战加浪漫吸引观众。", "url": "https://x.com/i/trending/2112111882152910915", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-20T08:04:03.000Z"}, {"id": "2111997785189093552", "domain": "娱乐", "title_en": "Netflix's Norm Macdonald Documentary Draws Laughs and Mixed Views", "title_zh": "网飞 Norm Macdonald 纪录片引笑声与两极评价", "hook_en": "Five years after Norm Macdonald's death at 61, fans are revisiting his deadpan genius through a new Netflix film that mixes laughs with heartfelt memories.", "hook_zh": "离世五年后，粉丝通过新片重温他的冷面幽默与深情回忆。", "summary_en": "Directed by Judd Apatow, 'Norm: The Tale of Norm Macdonald' premiered October 16 and runs two hours, using archival clips, home videos, photos, and his own audiobook narration instead of new interviews. Viewers praise it as a worthy tribute to his SNL Weekend Update days, O.J. jokes, and legendary timing, with some left laughing and crying over the man they miss. Others call it a clip show lacking fresh insight or his edgier routines, like certain 9/11 bits, though it highlights his private cancer battle and uncompromised style. The responses reflect his enduring, divisive impact on comedy.", "summary_zh": "由贾德·阿帕图执导的《Norm: The Tale of Norm Macdonald》10 月 16 日上线，时长约两小时，以档案片段、家庭影像、照片及其有声书旁白串联，未做新采访。观众称其为向 SNL《Weekend Update》、O.J. 玩笑与标志性节奏的致敬，有人边笑边哭；也有人觉得像精剪合集，缺少新洞察或其更锋利的段子。影片亦触及他私下与癌症抗争等面向，整体褒贬并存。", "body_en": "Netflix's Norm Macdonald Documentary Draws Laughs and Mixed Views.\n\nFive years after Norm Macdonald's death at 61, fans are revisiting his deadpan genius through a new Netflix film that mixes laughs with heartfelt memories.\n\nDirected by Judd Apatow, 'Norm: The Tale of Norm Macdonald' premiered October 16 and runs two hours, using archival clips, home videos, photos, and his own audiobook narration instead of new interviews. Viewers praise it as a worthy tribute to his SNL Weekend Update days, O.J.\n\njokes, and legendary timing, with some left laughing and crying over the man they miss. Others call it a clip show lacking fresh insight or his edgier routines, like certain 9/11 bits, though it highlights his private cancer battle and uncompromised style. The responses reflect his enduring, divisive impact on comedy.", "body_zh": "网飞 Norm Macdonald 纪录片引笑声与两极评价。\n\n离世五年后，粉丝通过新片重温他的冷面幽默与深情回忆。\n\n由贾德·阿帕图执导的《Norm: The Tale of Norm Macdonald》10 月 16 日上线，时长约两小时，以档案片段、家庭影像、照片及其有声书旁白串联，未做新采访。\n\n观众称其为向 SNL《Weekend Update》、O.J. 玩笑与标志性节奏的致敬，有人边笑边哭；也有人觉得像精剪合集，缺少新洞察或其更锋利的段子。影片亦触及他私下与癌症抗争等面向，整体褒贬并存。", "url": "https://x.com/i/trending/2111997785189093552", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-20T05:10:09.000Z"}, {"id": "2112852935252259068", "domain": "娱乐", "title_en": "Lena's Debut Film 'Her in Frame' Hits Netflix October 29", "title_zh": "莉娜首部电影《Her in Frame》10 月 29 日登陆网飞", "hook_en": "Fans are buzzing with joy as Thai actress Lena's first movie finally streams worldwide, marking her long-awaited big-screen moment.", "hook_zh": "泰国女演员莉娜大银幕处女作全球上线，粉丝期待已久。", "summary_en": "The romantic drama follows a young photographer chasing dreams of a mysterious woman from an old photo, blending past lives with present-day Thailand. Directed by Ekkasit Trakulkaesemsuk, it stars Thanapob Leeratanakachorn and Lena, inspired by the love story of King Bhumibol Adulyadej and Queen Sirikit. Available in Thailand, Indonesia, Malaysia, Vietnam, South Korea, and Japan, the 1-hour-41-minute film has a 13+ rating and early praise for its emotional depth and the leads' chemistry. Supporters are resubscribing to Netflix and organizing watch parties to celebrate this milestone.", "summary_zh": "这部爱情剧讲述年轻摄影师追寻旧照中神秘女子的梦想，交织前世今生与当代泰国。由 Ekkasit Trakulkaesemsuk 执导，Thanapob Leeratanakachorn 与莉娜主演，灵感来自普密蓬国王与诗丽吉王后的爱情故事。影片约 1 小时 41 分，13+ 分级，先在泰国、印尼、马来西亚、越南、韩国与日本上线，早期评价称情感与对手戏有吸引力。", "body_en": "Lena's Debut Film 'Her in Frame' Hits Netflix October 29.\n\nFans are buzzing with joy as Thai actress Lena's first movie finally streams worldwide, marking her long-awaited big-screen moment.\n\nThe romantic drama follows a young photographer chasing dreams of a mysterious woman from an old photo, blending past lives with present-day Thailand. Directed by Ekkasit Trakulkaesemsuk, it stars Thanapob Leeratanakachorn and Lena, inspired by the love story of King Bhumibol Adulyadej and Queen Sirikit.\n\nAvailable in Thailand, Indonesia, Malaysia, Vietnam, South Korea, and Japan, the 1-hour-41-minute film has a 13+ rating and early praise for its emotional depth and the leads' chemistry. Supporters are resubscribing to Netflix and organizing watch parties to celebrate this milestone.", "body_zh": "莉娜首部电影《Her in Frame》10 月 29 日登陆网飞。\n\n泰国女演员莉娜大银幕处女作全球上线，粉丝期待已久。\n\n这部爱情剧讲述年轻摄影师追寻旧照中神秘女子的梦想，交织前世今生与当代泰国。\n\n由 Ekkasit Trakulkaesemsuk 执导，Thanapob Leeratanakachorn 与莉娜主演，灵感来自普密蓬国王与诗丽吉王后的爱情故事。影片约 1 小时 41 分，13+ 分级，先在泰国、印尼、马来西亚、越南、韩国与日本上线，早期评价称情感与对手戏有吸引力。", "url": "https://x.com/i/trending/2112852935252259068", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-21T10:32:17.000Z"}, {"id": "2112433199888679267", "domain": "科学", "title_en": "AI Predicts Cancer Survival from Face Photos", "title_zh": "AI 凭面部照片预测癌症生存风险", "hook_en": "Doctors have always glanced at a patient's face to sense how sick they might be. Now AI makes that gut feel precise, spotting survival odds from a single snapshot.", "hook_zh": "医生一向会扫一眼患者面容判断病情轻重；如今 AI 把这种直觉量化，单张快照即可估计生存概率。", "summary_en": "Researchers from Mass General Brigham, Dana-Farber, Harvard, and Dutch partners unveiled FAHR-Face, two AI tools trained on millions of images that estimate biological age and forecast mortality risk for cancer patients. In tests with over 34,000 patients, the survival model showed those in the highest-risk group faced three times the death risk of the lowest, even after accounting for clinical factors, with strong results in an independent validation. While promising for low-cost checks using just a phone photo, the tools—mostly trained on white Boston patients—need more diverse testing and aren't ready for clinics yet. Lead researchers see it as a complement to doctor judgment, with the model now public on Hugging Face.", "summary_zh": "麻省总医院布莱根、丹娜法伯、哈佛与荷兰合作方发布 FAHR-Face：两款在海量图像上训练的 AI，可估计生物学年龄并预测癌症患者死亡风险。逾 3.4 万名患者测试显示，最高风险组死亡风险约为最低组三倍，即使校正临床因素后仍成立，独立验证表现稳健。工具有望用手机照片做低成本筛查，但主要在波士顿白人患者上训练，需更多元验证，尚不能进诊所。负责人视其为医生判断的补充，模型已在 Hugging Face 公开。", "body_en": "AI Predicts Cancer Survival from Face Photos.\n\nDoctors have always glanced at a patient's face to sense how sick they might be. Now AI makes that gut feel precise, spotting survival odds from a single snapshot.\n\nResearchers from Mass General Brigham, Dana-Farber, Harvard, and Dutch partners unveiled FAHR-Face, two AI tools trained on millions of images that estimate biological age and forecast mortality risk for cancer patients. In tests with over 34,000 patients, the survival model showed those in the highest-risk group faced three times the death risk of the lowest, even after accounting for clinical factors, with strong results in an independent validation.\n\nWhile promising for low-cost checks using just a phone photo, the tools—mostly trained on white Boston patients—need more diverse testing and aren't ready for clinics yet. Lead researchers see it as a complement to doctor judgment, with the model now public on Hugging Face.", "body_zh": "AI 凭面部照片预测癌症生存风险。\n\n医生一向会扫一眼患者面容判断病情轻重；如今 AI 把这种直觉量化，单张快照即可估计生存概率。\n\n麻省总医院布莱根、丹娜法伯、哈佛与荷兰合作方发布 FAHR-Face：两款在海量图像上训练的 AI，可估计生物学年龄并预测癌症患者死亡风险。逾 3.4 万名患者测试显示，最高风险组死亡风险约为最低组三倍，即使校正临床因素后仍成立，独立验证表现稳健。\n\n工具有望用手机照片做低成本筛查，但主要在波士顿白人患者上训练，需更多元验证，尚不能进诊所。负责人视其为医生判断的补充，模型已在 Hugging Face 公开。", "url": "https://x.com/i/trending/2112433199888679267", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T21:07:35.000Z"}, {"id": "2112771430316404992", "domain": "科学", "title_en": "Biosphere 2 Experiment Revives Debates on Self-Sustaining Living", "title_zh": "生物圈 2 号实验再引「自给生存」讨论", "hook_en": "Eight people stepped into a glass dome in the Arizona desert in 1991, aiming to create a sealed world with its own rainforest, ocean, and farm. Two years later, they emerged thinner but alive, sparking lessons that echo today.", "hook_zh": "1991 年八人走进亚利桑那沙漠玻璃穹顶，试图建造含雨林、海洋与农场的密封世界；两年后消瘦但存活走出，启示至今回响。", "summary_en": "The $150 million Biosphere 2 project tested if humans could thrive in a three-acre sealed ecosystem, growing 80 percent of their calories from crops like sweet potatoes and bananas, with goats providing key milk and a few pigs and chickens for scraps. Challenges hit hard: oxygen levels dropped to 14 percent from soil microbes outpacing plants, crew lost 10-20 percent body weight, and animals like pigs were slaughtered early amid calorie shortages. A popular thread recaps these struggles, with some calling it a warning against plant-heavy diets while others note fixes like added oxygen could work for space or Earth setups. The dome near Tucson now serves as a University of Arizona research site for ecology.", "summary_zh": "耗资约 1.5 亿美元的生物圈 2 号检验人类能否在三英亩密封生态中生存：约 80% 热量来自红薯、香蕉等作物，山羊供奶，少量猪鸡处理厨余。挑战严峻：土壤微生物耗氧快于植物，氧气降至 14%，成员减重 10–20%，猪等动物因热量不足提前宰杀。热门讨论有人视之为植物为主饮食的警示，也有人认为补氧等修正可用于太空或地球方案。图森附近穹顶现为亚利桑那大学生态研究站。", "body_en": "Biosphere 2 Experiment Revives Debates on Self-Sustaining Living.\n\nEight people stepped into a glass dome in the Arizona desert in 1991, aiming to create a sealed world with its own rainforest, ocean, and farm. Two years later, they emerged thinner but alive, sparking lessons that echo today.\n\nThe $150 million Biosphere 2 project tested if humans could thrive in a three-acre sealed ecosystem, growing 80 percent of their calories from crops like sweet potatoes and bananas, with goats providing key milk and a few pigs and chickens for scraps. Challenges hit hard: oxygen levels dropped to 14 percent from soil microbes outpacing plants, crew lost 10-20 percent body weight, and animals like pigs were slaughtered early amid calorie shortages.\n\nA popular thread recaps these struggles, with some calling it a warning against plant-heavy diets while others note fixes like added oxygen could work for space or Earth setups. The dome near Tucson now serves as a University of Arizona research site for ecology.", "body_zh": "生物圈 2 号实验再引「自给生存」讨论。\n\n1991 年八人走进亚利桑那沙漠玻璃穹顶，试图建造含雨林、海洋与农场的密封世界；两年后消瘦但存活走出，启示至今回响。\n\n耗资约 1.5 亿美元的生物圈 2 号检验人类能否在三英亩密封生态中生存：约 80% 热量来自红薯、香蕉等作物，山羊供奶，少量猪鸡处理厨余。挑战严峻：土壤微生物耗氧快于植物，氧气降至 14%，成员减重 10–20%，猪等动物因热量不足提前宰杀。\n\n热门讨论有人视之为植物为主饮食的警示，也有人认为补氧等修正可用于太空或地球方案。图森附近穹顶现为亚利桑那大学生态研究站。", "url": "https://x.com/i/trending/2112771430316404992", "category": "News", "topics": ["Science"], "updated_at": "2026-10-21T07:36:09.000Z"}, {"id": "2112514540671730138", "domain": "科学", "title_en": "Reuters Reveals Heat Storms Blanketing Earth for 18 Years Straight", "title_zh": "路透调查：热风暴已连续 18 年覆盖全球某处", "hook_en": "Imagine heat waves so massive they cover nearly 85% of the planet for over a year—Reuters' investigation uncovers this new reality reshaping daily life worldwide.", "hook_zh": "路透调查呈现新现实：热浪规模大到可覆盖近 85% 地球表面并持续逾一年，正重塑全球日常生活。", "summary_en": "Reuters analyzed over 600 billion temperature readings since 1960 and found heat storms—vast heat waves spanning at least 1% of Earth's surface—now strike 102 times a year on average, up from five in the 1960s. Since July 6, 2008, at least one has raged somewhere every single day, an unbroken 18-year cascade. People share struggles with the relentless heat, which kills nearly half a million annually and damages ecosystems, while the outlet launched a live tracker to monitor these events like hurricanes. Meteorologist Ryan Maue questions the framing, noting a shift in average temperatures explains much of the rise, but Reuters argues naming them helps the public grasp the scale.", "summary_zh": "路透分析自 1960 年以来逾 6000 亿条气温读数，发现「热风暴」——覆盖地球表面至少 1% 的巨大热浪——如今年均约 102 次，1960 年代仅约 5 次。自 2008 年 7 月 6 日起，全球每天至少有一处在经历热风暴，连续 18 年未断。人们分享酷热下的困境；此类事件每年致死近 50 万并损害生态。路透上线类似飓风的实时追踪器。气象学家 Ryan Maue 质疑表述，认为平均气温抬升可解释大部分增加；路透则称命名有助于公众理解规模。", "body_en": "Reuters Reveals Heat Storms Blanketing Earth for 18 Years Straight.\n\nImagine heat waves so massive they cover nearly 85% of the planet for over a year—Reuters' investigation uncovers this new reality reshaping daily life worldwide.\n\nReuters analyzed over 600 billion temperature readings since 1960 and found heat storms—vast heat waves spanning at least 1% of Earth's surface—now strike 102 times a year on average, up from five in the 1960s. Since July 6, 2008, at least one has raged somewhere every single day, an unbroken 18-year cascade.\n\nPeople share struggles with the relentless heat, which kills nearly half a million annually and damages ecosystems, while the outlet launched a live tracker to monitor these events like hurricanes. Meteorologist Ryan Maue questions the framing, noting a shift in average temperatures explains much of the rise, but Reuters argues naming them helps the public grasp the scale.", "body_zh": "路透调查：热风暴已连续 18 年覆盖全球某处。\n\n路透调查呈现新现实：热浪规模大到可覆盖近 85% 地球表面并持续逾一年，正重塑全球日常生活。\n\n路透分析自 1960 年以来逾 6000 亿条气温读数，发现「热风暴」——覆盖地球表面至少 1% 的巨大热浪——如今年均约 102 次，1960 年代仅约 5 次。自 2008 年 7 月 6 日起，全球每天至少有一处在经历热风暴，连续 18 年未断。\n\n人们分享酷热下的困境；此类事件每年致死近 50 万并损害生态。路透上线类似飓风的实时追踪器。气象学家 Ryan Maue 质疑表述，认为平均气温抬升可解释大部分增加；路透则称命名有助于公众理解规模。", "url": "https://x.com/i/trending/2112514540671730138", "category": "News", "topics": ["Science"], "updated_at": "2026-10-20T17:06:35.000Z"}, {"id": "2112620323275485557", "domain": "科学", "title_en": "SophontAI Launches Holon-S1 to Predict Tumor Biology from Routine Slides", "title_zh": "SophontAI 发布 Holon-S1：从常规病理切片预测肿瘤生物学", "hook_en": "Cancer patients often share the same diagnosis but have wildly different tumor behaviors. SophontAI's new Holon-S1 changes that by unlocking molecular insights straight from everyday pathology slides.", "hook_zh": "同样诊断的癌症患者肿瘤行为可能迥异；Holon-S1 从日常病理片直接读出分子线索。", "summary_en": "Holon-S1 predicts genes, biomarkers, and biological pathways directly from standard H&E slides that most patients already get, skipping slow and costly molecular tests. In tests, it beat leading models across 16 organ types, spotted novel breast and colon cancer biomarkers, and even analyzed a rare osteosarcoma case—matching a patient's real treatment findings on fibroblast genes like FAP. Co-founder Paul Scotti and CEO Tanishq Mathew Abraham stressed its interpretable biology, with shoutouts from Google's Jeff Dean and investor José Maria Macedo highlighting its promise for broader access to personalized tumor insights.", "summary_zh": "Holon-S1 可从多数患者已有的标准 H&E 切片预测基因、生物标志物与通路，跳过缓慢昂贵的分子检测。测试中其在 16 种器官上优于领先模型，发现乳腺与结肠癌新标志物，并分析罕见骨肉瘤病例——在 FAP 等成纤维基因上与患者真实治疗发现吻合。联合创始人与 CEO 强调可解释生物学；谷歌 Jeff Dean 与投资人等点赞其扩大个性化肿瘤洞察可及性。", "body_en": "SophontAI Launches Holon-S1 to Predict Tumor Biology from Routine Slides.\n\nCancer patients often share the same diagnosis but have wildly different tumor behaviors. SophontAI's new Holon-S1 changes that by unlocking molecular insights straight from everyday pathology slides.\n\nHolon-S1 predicts genes, biomarkers, and biological pathways directly from standard H&E slides that most patients already get, skipping slow and costly molecular tests.\n\nIn tests, it beat leading models across 16 organ types, spotted novel breast and colon cancer biomarkers, and even analyzed a rare osteosarcoma case—matching a patient's real treatment findings on fibroblast genes like FAP. Co-founder Paul Scotti and CEO Tanishq Mathew Abraham stressed its interpretable biology, with shoutouts from Google's Jeff Dean and investor José Maria Macedo highlighting its promise for broader access to personalized tumor insights.", "body_zh": "SophontAI 发布 Holon-S1：从常规病理切片预测肿瘤生物学。\n\n同样诊断的癌症患者肿瘤行为可能迥异；Holon-S1 从日常病理片直接读出分子线索。\n\nHolon-S1 可从多数患者已有的标准 H&E 切片预测基因、生物标志物与通路，跳过缓慢昂贵的分子检测。测试中其在 16 种器官上优于领先模型，发现乳腺与结肠癌新标志物，并分析罕见骨肉瘤病例——在 FAP 等成纤维基因上与患者真实治疗发现吻合。\n\n联合创始人与 CEO 强调可解释生物学；谷歌 Jeff Dean 与投资人等点赞其扩大个性化肿瘤洞察可及性。", "url": "https://x.com/i/trending/2112620323275485557", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T01:29:19.000Z"}, {"id": "2112552619117891920", "domain": "科学", "title_en": "Review Identifies 37 Anticancer Mechanisms for Ivermectin and Mebendazole Combo", "title_zh": "综述：伊维菌素与甲苯咪唑联用现 37 种抗癌机制", "hook_en": "A detailed scientific review uncovers 37 ways ivermectin and mebendazole team up against cancer cells across 25 human types, drawing from over 100 lab and animal studies.", "hook_zh": "详细科学综述梳理逾 100 项实验室与动物研究，归纳两种药物在 25 种人类癌症中协同对抗癌细胞的 37 种方式。", "summary_en": "Researchers at the McCullough Foundation, including Nicolas Hulscher, Peter A. McCullough, and Harvey Risch, synthesized preclinical evidence showing the drugs disrupt cancer cell division, trigger cell death, block energy and blood vessel growth, and more. The 44-page paper notes their low cost, off-patent status, and long safety record in humans, with overlapping effects on key cancer processes. While calling for large clinical trials, it references limited human reports like a Polish woman's normalized markers after using the combo, though experts stress the need for randomized trials amid some study retractions.", "summary_zh": "McCullough 基金会 Nicolas Hulscher、Peter A. McCullough、Harvey Risch 等综合临床前证据，显示药物可干扰癌细胞分裂、诱导死亡、阻断能量与血管生成等。44 页论文强调其成本低、已过专利、人类长期用药安全记录，以及对关键癌症过程有重叠作用。作者呼吁大型临床试验，并提及波兰一病例用药后指标正常化等有限人体报告；专家仍强调需随机试验，且部分研究曾遭撤稿。", "body_en": "Review Identifies 37 Anticancer Mechanisms for Ivermectin and Mebendazole Combo.\n\nA detailed scientific review uncovers 37 ways ivermectin and mebendazole team up against cancer cells across 25 human types, drawing from over 100 lab and animal studies.\n\nResearchers at the McCullough Foundation, including Nicolas Hulscher, Peter A. McCullough, and Harvey Risch, synthesized preclinical evidence showing the drugs disrupt cancer cell division, trigger cell death, block energy and blood vessel growth, and more.\n\nThe 44-page paper notes their low cost, off-patent status, and long safety record in humans, with overlapping effects on key cancer processes. While calling for large clinical trials, it references limited human reports like a Polish woman's normalized markers after using the combo, though experts stress the need for randomized trials amid some study retractions.", "body_zh": "综述：伊维菌素与甲苯咪唑联用现 37 种抗癌机制。\n\n详细科学综述梳理逾 100 项实验室与动物研究，归纳两种药物在 25 种人类癌症中协同对抗癌细胞的 37 种方式。\n\nMcCullough 基金会 Nicolas Hulscher、Peter A. McCullough、Harvey Risch 等综合临床前证据，显示药物可干扰癌细胞分裂、诱导死亡、阻断能量与血管生成等。44 页论文强调其成本低、已过专利、人类长期用药安全记录，以及对关键癌症过程有重叠作用。\n\n作者呼吁大型临床试验，并提及波兰一病例用药后指标正常化等有限人体报告；专家仍强调需随机试验，且部分研究曾遭撤稿。", "url": "https://x.com/i/trending/2112552619117891920", "category": "News", "topics": ["Health & Fitness"], "updated_at": "2026-10-20T20:43:03.000Z"}, {"id": "2112623559876952326", "domain": "科学", "title_en": "Reflect Orbital Simulates Orbital Sunlight in California Desert Test", "title_zh": "Reflect Orbital 在加州沙漠模拟「轨道阳光」", "hook_en": "In a dark desert near Mount Whitney, powerful spotlights turned night into a moonlit glow, mimicking future satellites beaming sunlight to Earth.", "hook_zh": "惠特尼山附近暗夜沙漠中，强光把夜色照成月色，预演未来阳光卫星。", "summary_en": "On October 10, California startup Reflect Orbital tested ground-based lights along Horseshoe Meadows Road near Lone Pine, illuminating three miles of terrain to aid nighttime search-and-rescue exercises with China Lake Mountain Rescue teams. The demo previews a satellite constellation with reflective mirrors to deliver targeted sunlight for emergencies or solar farms. While supporters highlight rescue benefits, astronomers worry about light pollution harming stargazing and wildlife, and skeptics question economics and environmental impacts as the company plans launches with India's Skyroot Aerospace.", "summary_zh": "Reflect Orbital 用地面灯具照亮约三英里范围，测试搜救用途；并预告将发射带镜子的卫星星座，向目标区域投送定向阳光。", "body_en": "Reflect Orbital Simulates Orbital Sunlight in California Desert Test.\n\nIn a dark desert near Mount Whitney, powerful spotlights turned night into a moonlit glow, mimicking future satellites beaming sunlight to Earth.\n\nOn October 10, California startup Reflect Orbital tested ground-based lights along Horseshoe Meadows Road near Lone Pine, illuminating three miles of terrain to aid nighttime search-and-rescue exercises with China Lake Mountain Rescue teams.\n\nThe demo previews a satellite constellation with reflective mirrors to deliver targeted sunlight for emergencies or solar farms. While supporters highlight rescue benefits, astronomers worry about light pollution harming stargazing and wildlife, and skeptics question economics and environmental impacts as the company plans launches with India's Skyroot Aerospace.", "body_zh": "Reflect Orbital 在加州沙漠模拟「轨道阳光」。\n\n惠特尼山附近暗夜沙漠中，强光把夜色照成月色，预演未来阳光卫星。\n\nReflect Orbital 用地面灯具照亮约三英里范围，测试搜救用途；并预告将发射带镜子的卫星星座，向目标区域投送定向阳光。\n\n综合以上信息，Reflect Orbital 在加州沙漠模拟「轨道阳光」一事持续引发关注。", "url": "https://x.com/i/trending/2112623559876952326", "category": "News", "topics": ["Technology", "Space"], "updated_at": "2026-10-21T00:18:52.000Z"}, {"id": "2112640445633499411", "domain": "科学", "title_en": "Electric Plant Launches Bombadil AI to Read Plant Electrical Signals", "title_zh": "Electric Plant 推出 Bombadil：解读植物电信号的 AI", "hook_en": "Imagine slipping a tiny sensor into a plant and getting a real-time readout of its health, just like monitoring brainwaves. Electric Plant's new AI, Bombadil, makes that possible by decoding subtle electrical signals from living plants.", "hook_zh": "像监测脑电一样，把微型传感器接入植物即可实时读健康——Bombadil 解码活体植物微弱电信号。", "summary_en": "The startup pairs low-cost Bud sensors with Bombadil, a foundation model trained on over seven million hours of data from 125 plant species, to track stress, water needs, photosynthesis efficiency, and more. Co-founder Justin Mast says it could cut water use by 20 percent or more for growers by enabling precise irrigation based on individual plant signals rather than soil alone. Backed by an $11.2 million seed round, the team—from neuroscientists to AI experts—built it after years of recording signals in labs, forests, and orchards, with early enthusiasm for its potential in farming and climate tech.", "summary_zh": "初创公司将低成本 Bud 传感器与在 125 种植物、逾 700 万小时数据上训练的基础模型 Bombadil 组合，追踪胁迫、需水、光合效率等。联合创始人 Justin Mast 称，按单株信号而非仅土壤精准灌溉，种植者用水或可降 20% 以上。种子轮 1120 万美元；团队含神经科学家与 AI 专家，经年在实验室、森林与果园记录信号，农业与气候科技前景获早期热捧。", "body_en": "Electric Plant Launches Bombadil AI to Read Plant Electrical Signals.\n\nImagine slipping a tiny sensor into a plant and getting a real-time readout of its health, just like monitoring brainwaves. Electric Plant's new AI, Bombadil, makes that possible by decoding subtle electrical signals from living plants.\n\nThe startup pairs low-cost Bud sensors with Bombadil, a foundation model trained on over seven million hours of data from 125 plant species, to track stress, water needs, photosynthesis efficiency, and more.\n\nCo-founder Justin Mast says it could cut water use by 20 percent or more for growers by enabling precise irrigation based on individual plant signals rather than soil alone. Backed by an $11.2 million seed round, the team—from neuroscientists to AI experts—built it after years of recording signals in labs, forests, and orchards, with early enthusiasm for its potential in farming and climate tech.", "body_zh": "Electric Plant 推出 Bombadil：解读植物电信号的 AI。\n\n像监测脑电一样，把微型传感器接入植物即可实时读健康——Bombadil 解码活体植物微弱电信号。\n\n初创公司将低成本 Bud 传感器与在 125 种植物、逾 700 万小时数据上训练的基础模型 Bombadil 组合，追踪胁迫、需水、光合效率等。联合创始人 Justin Mast 称，按单株信号而非仅土壤精准灌溉，种植者用水或可降 20% 以上。\n\n种子轮 1120 万美元；团队含神经科学家与 AI 专家，经年在实验室、森林与果园记录信号，农业与气候科技前景获早期热捧。", "url": "https://x.com/i/trending/2112640445633499411", "category": "News", "topics": ["Technology", "Biotech"], "updated_at": "2026-10-20T20:33:11.000Z"}, {"id": "2112802744491000212", "domain": "科学", "title_en": "UN Report: 1.5°C Warming Limit Now Requires Temporary Overshoot", "title_zh": "联合国报告：暂时超越 1.5°C 已不可避免，但仍可逆转", "hook_en": "The UN's latest report delivers a sobering update: holding global warming to 1.5°C means briefly exceeding it before pulling back. UNEP chief Inger Andersen insists it's still possible to limit the damage.", "hook_zh": "联合国传来沉重消息：数十年气候行动迟缓意味着将暂时突破 1.5°C 升温上限；但领导层称紧急行动仍可在本世纪末把温度拉回。", "summary_en": "The annual UN Emissions Gap Report, released ahead of COP31 in Turkey, states that the Paris Agreement's 1.5°C goal can no longer be met without overshooting to about 1.7-1.8°C mid-century, then returning by 2100. This demands global emissions cuts of 18% by 2030, 45% by 2035, and 69% by 2040 from 2025 levels, plus massive carbon removal—far beyond current pledges that lead to 2.6°C warming. Current policies without change point to 2.8°C, amid record-high emissions and reliance on coal. Andersen calls for urgent action across energy, industry, and methane to shorten any overshoot.", "summary_zh": "联合国环境规划署《2026 排放差距报告》警告，现行政策指向升温约 2.8°C，国家承诺可压至约 2.6°C。即便乐观路径，本世纪中叶仍见 1.7–1.8°C，之后才可能于 2100 年回到 1.5°C，需相对 2025 年水平在 2030 年减排 18%、2035 年 45%、2040 年 69%，并大规模碳移除。UNEP 负责人 Inger Andersen 与古特雷斯强调，要将「超标」幅度压到最小，必须立即全力以赴，在煤油气排放仍升之际依托可再生扩张。", "body_en": "UN Report: 1.5°C Limit Overshoot Now Inevitable.\n\nYears of slow action have closed the door on staying below 1.5°C warming without a temporary breach. The focus shifts to limiting how high and how long temperatures climb before dropping back.\n\nThe UN Environment Programme’s 2026 Emissions Gap Report states that global warming will exceed the Paris Agreement’s 1.5°C target in coming years, with the best-case peak at 1.7–1.8°C mid-century and a 50% chance of returning below 1.5°C by 2100. This requires emissions cuts of 18% by 2030, 45% by 2035, and 69% by 2040 from 2025 levels, plus large-scale carbon removal.\n\nCurrent pledges only achieve 5–8% cuts by 2030, heading toward 2.6°C or more warming. UNEP’s Inger Andersen calls for urgent action to minimize risks like floods and heatwaves ahead of COP31 talks.", "body_zh": "联合国报告：暂时超越 1.5°C 已不可避免，但仍可逆转。\n\n联合国传来沉重消息：数十年气候行动迟缓意味着将暂时突破 1.5°C 升温上限；但领导层称紧急行动仍可在本世纪末把温度拉回。\n\n联合国环境规划署《2026 排放差距报告》警告，现行政策指向升温约 2.8°C，国家承诺可压至约 2.6°C。即便乐观路径，本世纪中叶仍见 1.7–1.8°C，之后才可能于 2100 年回到 1.5°C，需相对 2025 年水平在 2030 年减排 18%、2035 年 45%、2040 年 69%，并大规模碳移除。\n\nUNEP 负责人 Inger Andersen 与古特雷斯强调，要将「超标」幅度压到最小，必须立即全力以赴，在煤油气排放仍升之际依托可再生扩张。", "url": "https://x.com/i/trending/2112802744491000212", "category": "News", "topics": ["News"], "updated_at": "2026-10-21T12:07:55.000Z"}, {"id": "2111892089000915435", "domain": "科学", "title_en": "President Ruto Launches Key Projects in Kapsabet Amid Huge Crowds", "title_zh": "鲁托总统在卡普萨贝特启动多项民生工程，万人夹道", "hook_en": "Thousands of residents in yellow caps lined Kapsabet's streets on October 18, cheering as President William Ruto arrived to unveil projects boosting healthcare, roads, and more.", "hook_zh": "10 月 18 日数千戴黄帽居民列队卡普萨贝特街头，欢呼威廉·鲁托总统到访揭幕医疗、道路等项目。", "summary_en": "Ruto opened the new Mother and Child Health Complex at Kapsabet County Referral Hospital, equipped with KSh392 million in modern tools and new intensive care units. He inspected the half-complete 10,000-seater stadium, laid a foundation for another hospital, commissioned the county headquarters, and committed to 12 km of local roads plus a four-lane highway upgrade. The visits also included flagging off a Sh351 million electricity project for thousands of homes and issuing Women Enterprise Fund cheques, with Governor Stephen Sang noting direct benefits to daily lives.", "summary_zh": "鲁托为卡普萨贝特县转诊医院新建母婴健康综合楼剪彩，配备价值约 3.92 亿肯先令的现代设备与新重症监护室。他视察半完工的万人体育场、为另一医院奠基、启用县总部，并承诺 12 公里地方道路与四车道公路升级。行程还包括启动约 3.51 亿肯先令电力项目惠及数千户，以及发放妇女企业基金支票；州长 Stephen Sang 称举措直接惠及日常生活。", "body_en": "President Ruto Launches Key Projects in Kapsabet Amid Huge Crowds.\n\nThousands of residents in yellow caps lined Kapsabet's streets on October 18, cheering as President William Ruto arrived to unveil projects boosting healthcare, roads, and more.\n\nRuto opened the new Mother and Child Health Complex at Kapsabet County Referral Hospital, equipped with KSh392 million in modern tools and new intensive care units.\n\nHe inspected the half-complete 10,000-seater stadium, laid a foundation for another hospital, commissioned the county headquarters, and committed to 12 km of local roads plus a four-lane highway upgrade. The visits also included flagging off a Sh351 million electricity project for thousands of homes and issuing Women Enterprise Fund cheques, with Governor Stephen Sang noting direct benefits to daily lives.", "body_zh": "鲁托总统在卡普萨贝特启动多项民生工程，万人夹道。\n\n10 月 18 日数千戴黄帽居民列队卡普萨贝特街头，欢呼威廉·鲁托总统到访揭幕医疗、道路等项目。\n\n鲁托为卡普萨贝特县转诊医院新建母婴健康综合楼剪彩，配备价值约 3.92 亿肯先令的现代设备与新重症监护室。他视察半完工的万人体育场、为另一医院奠基、启用县总部，并承诺 12 公里地方道路与四车道公路升级。\n\n行程还包括启动约 3.51 亿肯先令电力项目惠及数千户，以及发放妇女企业基金支票；州长 Stephen Sang 称举措直接惠及日常生活。", "url": "https://x.com/i/trending/2111892089000915435", "category": "News", "topics": ["Health & Fitness"], "updated_at": "2026-10-20T06:36:12.000Z"}, {"id": "2112414671194009776", "domain": "科学", "title_en": "Rocket Lab Videos Automated Machine Building Neutron Rocket Dome", "title_zh": "火箭实验室晒自动铺丝机制作 Neutron 整流罩穹顶", "hook_en": "Thousands of hair-thin carbon fibers whip into place at blistering speeds, forming the massive forward dome for Neutron's Stage 1 tank. It's a glimpse into the precision powering Rocket Lab's next big leap.", "hook_zh": "成千上万根发丝般碳纤维高速铺就 Neutron 一级贮箱巨大前穹顶。", "summary_en": "Rocket Lab released footage of its automated fiber placement machine at the Maryland facility laying down carbon strands up to 100 meters per minute on custom molds for the Neutron rocket's large composite forward dome. This step follows last week's news of a 2027 first-launch target after fixing voids in a prior manual dome, with CEO Peter Beck confirming refined processes and a successful aft dome. Investors and fans praised the update for building excitement around production progress toward a reusable rocket carrying 13,000 kg to orbit, with upcoming tests ahead.", "summary_zh": "火箭实验室公布马里兰工厂自动铺丝机画面：以最高约每分钟 100 米在定制模具上铺碳丝，制作 Neutron 大型复合材料前穹顶。此前手工穹顶空隙问题已修复，CEO 彼得·贝克确认工艺改进与后穹顶成功，首飞目标 2027 年。投资者与粉丝为可复用、运力约 1.3 万公斤入轨的火箭量产进展叫好，后续测试将至。", "body_en": "Rocket Lab Videos Automated Machine Building Neutron Rocket Dome.\n\nThousands of hair-thin carbon fibers whip into place at blistering speeds, forming the massive forward dome for Neutron's Stage 1 tank. It's a glimpse into the precision powering Rocket Lab's next big leap.\n\nRocket Lab released footage of its automated fiber placement machine at the Maryland facility laying down carbon strands up to 100 meters per minute on custom molds for the Neutron rocket's large composite forward dome.\n\nThis step follows last week's news of a 2027 first-launch target after fixing voids in a prior manual dome, with CEO Peter Beck confirming refined processes and a successful aft dome. Investors and fans praised the update for building excitement around production progress toward a reusable rocket carrying 13,000 kg to orbit, with upcoming tests ahead.", "body_zh": "火箭实验室晒自动铺丝机制作 Neutron 整流罩穹顶。\n\n成千上万根发丝般碳纤维高速铺就 Neutron 一级贮箱巨大前穹顶。\n\n火箭实验室公布马里兰工厂自动铺丝机画面：以最高约每分钟 100 米在定制模具上铺碳丝，制作 Neutron 大型复合材料前穹顶。此前手工穹顶空隙问题已修复，CEO 彼得·贝克确认工艺改进与后穹顶成功，首飞目标 2027 年。\n\n投资者与粉丝为可复用、运力约 1.3 万公斤入轨的火箭量产进展叫好，后续测试将至。", "url": "https://x.com/i/trending/2112414671194009776", "category": "News", "topics": ["Technology", "Space"], "updated_at": "2026-10-20T05:28:17.000Z"}, {"id": "2112831569891303643", "domain": "科学", "title_en": "Green Drops Summit 2026 Opens in Kampala on Sprinktech's 10th Anniversary", "title_zh": "坎帕拉举办 Green Drops 峰会，讨论可持续灌溉创新", "hook_en": "Jovan Mukundane, CEO of Sprinktech, welcomed a full house at Mestil Hotel with a clear call: rethink irrigation for tomorrow's farms.", "hook_zh": "Sprinktech CEO 在十周年之际呼吁：重新思考明日农业的灌溉方式。", "summary_en": "The second Green Drops Summit kicked off today in Kampala, gathering industry leaders, officials, engineers, and partners to discuss sustainable water management and irrigation innovations like solar pumps, drip systems, AI sensors, and remote monitoring. Under the theme 'The Future of Irrigation – Beyond Conventional Practices,' panels moderated by experts such as Eng. Enyetu Joshua of Grundfos tackle efficiency, energy optimization, and barriers like high costs and limited support. Attendees, including panelists like Mrs. Karin Jeanet Vezzini, stress collaboration, training, and practical solutions to help Ugandan and African farmers boost productivity amid climate challenges.", "summary_zh": "第二届 Green Drops Summit 在乌干达坎帕拉开幕，汇聚业界领袖、官员、工程师与合作伙伴，讨论太阳能泵、滴灌、AI 传感器与远程监控等可持续水管理与灌溉创新。主题为「灌溉的未来——超越传统做法」，专家主持讨论效率、能源优化及高成本、支持不足等障碍。与会者强调协作、培训与务实方案，帮助乌干达与非洲农民在气候挑战下提高生产力。", "body_en": "Green Drops Summit 2026 Opens in Kampala on Sprinktech's 10th Anniversary.\n\nJovan Mukundane, CEO of Sprinktech, welcomed a full house at Mestil Hotel with a clear call: rethink irrigation for tomorrow's farms.\n\nThe second Green Drops Summit kicked off today in Kampala, gathering industry leaders, officials, engineers, and partners to discuss sustainable water management and irrigation innovations like solar pumps, drip systems, AI sensors, and remote monitoring. Under the theme 'The Future of Irrigation – Beyond Conventional Practices,' panels moderated by experts such as Eng.\n\nEnyetu Joshua of Grundfos tackle efficiency, energy optimization, and barriers like high costs and limited support. Attendees, including panelists like Mrs. Karin Jeanet Vezzini, stress collaboration, training, and practical solutions to help Ugandan and African farmers boost productivity amid climate challenges.", "body_zh": "坎帕拉举办 Green Drops 峰会，讨论可持续灌溉创新。\n\nSprinktech CEO 在十周年之际呼吁：重新思考明日农业的灌溉方式。\n\n第二届 Green Drops Summit 在乌干达坎帕拉开幕，汇聚业界领袖、官员、工程师与合作伙伴，讨论太阳能泵、滴灌、AI 传感器与远程监控等可持续水管理与灌溉创新。\n\n主题为「灌溉的未来——超越传统做法」，专家主持讨论效率、能源优化及高成本、支持不足等障碍。与会者强调协作、培训与务实方案，帮助乌干达与非洲农民在气候挑战下提高生产力。", "url": "https://x.com/i/trending/2112831569891303643", "category": "News", "topics": ["Technology"], "updated_at": "2026-10-21T11:43:58.000Z"}, {"id": "2112833225118625949", "domain": "科学", "title_en": "Nigeria Debunks Viral Claims on US Medical Aid Deal", "title_zh": "尼日利亚驳斥美医疗援助协议「禁检疫苗」谣言", "hook_en": "Panic spread online after posts claimed a US deal would block Nigeria's drug agency from testing free vaccines and medicines. Officials stepped in swiftly to set the record straight.", "hook_zh": "网传美援协议禁止药监局检测免费疫苗药品，官方迅速澄清主权与安检仍在。", "summary_en": "Viral messages alleged a $3 billion US aid package for malaria and other diseases barred NAFDAC from reviewing supplies, sparking fears of unsafe products and lost sovereignty—claims that Ghana supposedly rejected. NAFDAC's Director-General Prof. Mojisola Adeyeye clarified on October 20, 2026, that the agency keeps full authority: US FDA-approved products get expedited review due to existing reliance, but all undergo safety checks, especially non-US ones, with tracking via blockchain. The five-year MoU, signed December 2025, provides nearly $2 billion in declining US grants for HIV/AIDS and health programs, while Nigeria boosts its spending to $3 billion for self-reliance.", "summary_zh": "病毒式帖文称约 30 亿美元美援疟疾等项目禁止 NAFDAC 审查物资，引发不安全与主权丧失恐慌，并称加纳已拒绝。NAFDAC 局长 Mojisola Adeyeye 教授 2026 年 10 月 20 日澄清：机构保留完整权限；FDA 已批产品可加快审评，但皆须安全检查，非美产品尤然，并以区块链追踪。2025 年 12 月签署的五年谅解备忘录提供近 20 亿美元递减美方拨款用于艾滋病等卫生项目，尼日利亚同步将本国投入提至约 30 亿美元以增强自立。", "body_en": "Nigeria Debunks Viral Claims on US Medical Aid Deal.\n\nPanic spread online after posts claimed a US deal would block Nigeria's drug agency from testing free vaccines and medicines. Officials stepped in swiftly to set the record straight.\n\nViral messages alleged a $3 billion US aid package for malaria and other diseases barred NAFDAC from reviewing supplies, sparking fears of unsafe products and lost sovereignty—claims that Ghana supposedly rejected. NAFDAC's Director-General Prof.\n\nMojisola Adeyeye clarified on October 20, 2026, that the agency keeps full authority: US FDA-approved products get expedited review due to existing reliance, but all undergo safety checks, especially non-US ones, with tracking via blockchain. The five-year MoU, signed December 2025, provides nearly $2 billion in declining US grants for HIV/AIDS and health programs, while Nigeria boosts its spending to $3 billion for self-reliance.", "body_zh": "尼日利亚驳斥美医疗援助协议「禁检疫苗」谣言。\n\n网传美援协议禁止药监局检测免费疫苗药品，官方迅速澄清主权与安检仍在。\n\n病毒式帖文称约 30 亿美元美援疟疾等项目禁止 NAFDAC 审查物资，引发不安全与主权丧失恐慌，并称加纳已拒绝。\n\nNAFDAC 局长 Mojisola Adeyeye 教授 2026 年 10 月 20 日澄清：机构保留完整权限；FDA 已批产品可加快审评，但皆须安全检查，非美产品尤然，并以区块链追踪。2025 年 12 月签署的五年谅解备忘录提供近 20 亿美元递减美方拨款用于艾滋病等卫生项目，尼日利亚同步将本国投入提至约 30 亿美元以增强自立。", "url": "https://x.com/i/trending/2112833225118625949", "category": "News", "topics": ["Health & Fitness"], "updated_at": "2026-10-21T11:29:22.000Z"}, {"id": "2112826877455053262", "domain": "科学", "title_en": "India Adds Three Sites to UNESCO World Heritage Tentative List", "title_zh": "印度三处遗址列入联合国教科文组织世界遗产预备名录", "hook_en": "From bubbling mud volcanoes in the Andamans to ancient temples along the Mahanadi River, three Indian treasures now stand closer to global recognition.", "hook_zh": "从安达曼泥火山到默哈讷迪河畔古庙，三处印度遗产向全球认可又近一步。", "summary_en": "India's Permanent Delegation to UNESCO announced on October 20, 2026, the addition of the Karst-mud-volcano Complex of Baratang and Andaman Subduction Volcanoes in the Andaman and Nicobar Islands, plus the Sirpur Cultural and Archaeological Landscape in Chhattisgarh. These sites highlight unique geology like active volcanoes and limestone caves, alongside historic temples reflecting Hindu, Buddhist, and Jain heritage with evidence of multi-faith harmony. Union Minister Gajendra Singh Shekhawat praised Sirpur for its traditions in art, architecture, spirituality, and learning, as India builds on its 45 inscribed World Heritage Sites.", "summary_zh": "印度常驻教科文组织代表团 2026 年 10 月 20 日宣布，将巴拉唐喀斯特—泥火山综合体与安达曼俯冲火山，以及恰蒂斯加尔邦西尔普尔文化考古景观列入预备名录。前者突出活火山与石灰岩洞穴等地质特色，后者涵盖印度教、佛教与耆那教古庙及多信仰共存证据。联邦部长 Gajendra Singh Shekhawat 称赞西尔普尔在艺术、建筑、精神与学问上的传统；印度已有 45 处列入世界遗产。", "body_en": "India Adds Three Sites to UNESCO World Heritage Tentative List.\n\nFrom bubbling mud volcanoes in the Andamans to ancient temples along the Mahanadi River, three Indian treasures now stand closer to global recognition.\n\nIndia's Permanent Delegation to UNESCO announced on October 20, 2026, the addition of the Karst-mud-volcano Complex of Baratang and Andaman Subduction Volcanoes in the Andaman and Nicobar Islands, plus the Sirpur Cultural and Archaeological Landscape in Chhattisgarh.\n\nThese sites highlight unique geology like active volcanoes and limestone caves, alongside historic temples reflecting Hindu, Buddhist, and Jain heritage with evidence of multi-faith harmony. Union Minister Gajendra Singh Shekhawat praised Sirpur for its traditions in art, architecture, spirituality, and learning, as India builds on its 45 inscribed World Heritage Sites.", "body_zh": "印度三处遗址列入联合国教科文组织世界遗产预备名录。\n\n从安达曼泥火山到默哈讷迪河畔古庙，三处印度遗产向全球认可又近一步。\n\n印度常驻教科文组织代表团 2026 年 10 月 20 日宣布，将巴拉唐喀斯特—泥火山综合体与安达曼俯冲火山，以及恰蒂斯加尔邦西尔普尔文化考古景观列入预备名录。\n\n前者突出活火山与石灰岩洞穴等地质特色，后者涵盖印度教、佛教与耆那教古庙及多信仰共存证据。联邦部长 Gajendra Singh Shekhawat 称赞西尔普尔在艺术、建筑、精神与学问上的传统；印度已有 45 处列入世界遗产。", "url": "https://x.com/i/trending/2112826877455053262", "category": "News", "topics": ["Travel"], "updated_at": "2026-10-21T11:43:52.000Z"}]};
